insert into public.livros_traducoes (texto_slug, idioma, cobertura, credito, titulos, paragrafos, total_paragrafos) values ('oscar-wilde_an-ideal-husband', 'pt', 'parcial', 'Tradução para o português do Brasil feita por IA (Claude) para o Alice''s Library; primeiros capítulos, revisão pendente.', $tr${"acti":"Ato I","actii":"Ato II","actiii":"Ato III"}$tr$::jsonb, $tr${"theoctagonroomatsirrobertchilternshousei~nshouseingrosvenorsquare~56":"A sala octogonal na casa de Sir Robert Chiltern, em Grosvenor Square.","theroomisbrilliantlylightedandfullofgues~ouldhavelovedtopaintthem~659":"A sala está brilhantemente iluminada e cheia de convidados. No alto da escada está Lady Chiltern, mulher de grave beleza grega, de uns vinte e sete anos de idade. Ela recebe os convidados à medida que chegam. Sobre o vão da escada pende um grande lustre com velas de cera, que iluminam uma grande tapeçaria francesa do século XVIII — representando o Triunfo do Amor, segundo um desenho de Boucher — esticada na parede da escada. À direita fica a entrada da sala de música. Ouve-se, ao longe, o som de um quarteto de cordas. A entrada à esquerda leva a outras salas de recepção. A Sra. Marchmont e Lady Basildon, duas mulheres muito bonitas, estão sentadas lado a lado num sofá Luís XVI. São tipos de requintada fragilidade. A afetação de suas maneiras tem um encanto delicado. Watteau teria adorado pintá-las.","mrsmarchmontgoingontothehartlockstonight~hartlockstonightmargaret~48":"Sra. Marchmont — Vai aos Hartlock hoje à noite, Margaret?","ladybasildonisupposesoareyou~basildonisupposesoareyou~28":"Lady Basildon — Suponho que sim. E você?","mrsmarchmontyeshorriblytediouspartiesthe~spartiestheygivedontthey~53":"Sra. Marchmont — Vou. Dão festas horrivelmente tediosas, não é?","ladybasildonhorriblytediousneverknowwhyi~oneverknowwhyigoanywhere~65":"Lady Basildon — Horrivelmente tediosas! Nunca sei por que vou. Nunca sei por que vou a lugar nenhum.","mrsmarchmonticomeheretobeeducated~onticomeheretobeeducated~33":"Sra. Marchmont — Eu venho aqui para me educar.","ladybasildonahihatebeingeducated~ldonahihatebeingeducated~32":"Lady Basildon — Ah! Detesto ser educada!","mrsmarchmontsodoiitputsonealmostonalevel~oicomeheretotrytofindone~176":"Sra. Marchmont — Eu também. Isso nos põe quase no nível das classes comerciais, não é? Mas a querida Gertrude Chiltern está sempre me dizendo que eu deveria ter algum propósito sério na vida. Então venho aqui tentar encontrar um.","ladybasildonlookingroundthroughherlorgne~abouthiswifethewholetime~167":"Lady Basildon — Olhando em volta através do lornhão. Não vejo ninguém aqui esta noite a quem se pudesse chamar, com propriedade, de propósito sério. O homem que me levou para jantar falou da esposa o tempo todo.","mrsmarchmonthowverytrivialofhim~hmonthowverytrivialofhim~31":"Sra. Marchmont — Que futilidade a dele!","ladybasildonterriblytrivialwhatdidyourma~lwhatdidyourmantalkabout~50":"Lady Basildon — Terrivelmente fútil! E o seu, falou do quê?","mrsmarchmontaboutmyself~mrsmarchmontaboutmyself~23":"Sra. Marchmont — De mim mesma.","ladybasildonlanguidlyandwereyouintereste~idlyandwereyouinterested~41":"Lady Basildon — Languidamente. E você se interessou?","mrsmarchmontshakingherheadnotinthesmalle~adnotinthesmallestdegree~48":"Sra. Marchmont — Balançando a cabeça. Nem um pouquinho.","ladybasildonwhatmartyrswearedearmargaret~martyrswearedearmargaret~40":"Lady Basildon — Que mártires somos, querida Margaret!","mrsmarchmontrisingandhowwellitbecomesuso~howwellitbecomesusolivia~45":"Sra. Marchmont — Levantando-se. E como isso nos cai bem, Olivia!","theyriseandgotowardsthemusicroomthevicom~ndentersintoconversation~144":"Levantam-se e vão em direção à sala de música. O Visconde de Nanjac, jovem adido conhecido por suas gravatas e sua anglomania, aproxima-se com uma profunda reverência e entra em conversa.","masonannouncingguestsfromthetopofthestai~janebarfordlordcaversham~78":"Mason — Anunciando os convidados do alto da escada. O Sr. e Lady Jane Barford. Lorde Caversham.","enterlordcavershamanoldgentlemanofsevent~rlikeaportraitbylawrence~117":"Entra Lorde Caversham, um senhor de setenta anos, usando a fita e a estrela da Ordem da Jarreteira. Um belo tipo whig. Bem parecido com um retrato de Lawrence.","lordcavershamgoodeveningladychilternhasm~rnothingyoungsonbeenhere~71":"Lorde Caversham — Boa noite, Lady Chiltern! Meu filho imprestável já esteve por aqui?","ladychilternsmilingidontthinklordgoringh~klordgoringhasarrivedyet~52":"Lady Chiltern — Sorrindo. Não creio que Lorde Goring tenha chegado ainda.","mabelchilterncominguptolordcavershamwhyd~lordgoringgoodfornothing~72":"Mabel Chiltern — Aproximando-se de Lorde Caversham. Por que o senhor chama Lorde Goring de imprestável?","mabelchilternisaperfectexampleoftheengli~erannoyedifsheweretoldso~412":"Mabel Chiltern é um exemplo perfeito do tipo inglês de beleza, o tipo flor de macieira. Tem toda a fragrância e a liberdade de uma flor. Há onda após onda de luz do sol em seu cabelo, e a boquinha, de lábios entreabertos, é expectante, como a boca de uma criança. Tem a fascinante tirania da juventude e a espantosa coragem da inocência. Para pessoas sensatas, não faz lembrar nenhuma obra de arte. Mas é realmente como uma estatueta de Tanagra, e ficaria bastante aborrecida se lho dissessem.","lordcavershambecauseheleadssuchanidlelif~useheleadssuchanidlelife~41":"Lorde Caversham — Porque leva uma vida tão ociosa.","mabelchilternhowcanyousaysuchathingwhyhe~atleadinganidlelifedoyou~211":"Mabel Chiltern — Como pode dizer uma coisa dessas? Ora, ele cavalga no Row às dez da manhã, vai à Ópera três vezes por semana, troca de roupa pelo menos cinco vezes ao dia e janta fora todas as noites da temporada. O senhor não chama isso de levar uma vida ociosa, chama?","lordcavershamlookingatherwithakindlytwin~reaverycharmingyounglady~80":"Lorde Caversham — Olhando para ela com um brilho bondoso nos olhos. A senhorita é uma jovem encantadora!","mabelchilternhowsweetofyoutosaythatlordc~oulooksowellwithyourstar~131":"Mabel Chiltern — Que gentileza a sua, Lord Caversham! Venha nos ver com mais frequência. O senhor sabe que recebemos sempre às quartas-feiras, e fica tão bem com a sua condecoração!","lordcavershamnevergoanywherenowsickoflon~andladycavershamsbonnets~212":"Lord Caversham — Não vou mais a lugar nenhum. Farto da Sociedade londrina. Não me importaria de ser apresentado ao meu próprio alfaiate; ele ao menos vota sempre do lado certo. Mas faço sérias objeções a ser mandado à mesa de jantar com a modista da minha mulher. Nunca suportei os chapéus de Lady Caversham.","mabelchilternohilovelondonsocietyithinki~sjustwhatsocietyshouldbe~144":"Mabel Chiltern — Ah, eu adoro a Sociedade londrina! Acho que melhorou imensamente. Hoje é composta inteiramente de belos idiotas e loucos brilhantes. Exatamente o que a Sociedade deve ser.","lordcavershamhumwhichisgoringbeautifulid~ifulidiotortheotherthing~58":"Lord Caversham — Hum! Qual dos dois é Goring? O belo idiota ou o outro?","mabelchilterngravelyihavebeenobligedfort~heisdevelopingcharmingly~115":"Mabel Chiltern — Gravemente. Fui obrigada, por ora, a colocar Lord Goring numa classe só dele. Mas ele está se desenvolvendo encantadoramente!","lordcavershamintowhat~lordcavershamintowhat~21":"Lord Caversham — Em quê?","mabelchilternwithalittlecurtseyihopetole~nowverysoonlordcaversham~69":"Mabel Chiltern — Com uma pequena reverência. Espero poder lhe dizer muito em breve, Lord Caversham!","masonannouncingguestsladymarkbymrschevel~stsladymarkbymrscheveley~42":"Mason — Anunciando os convidados. Lady Markby. Sra. Cheveley.","enterladymarkbyandmrscheveleyladymarkbyi~nfluenceoftoomanyschools~514":"Entram Lady Markby e a Sra. Cheveley. Lady Markby é uma mulher agradável, bondosa e popular, de cabelos grisalhos penteados à marquesa e de renda fina. A Sra. Cheveley, que a acompanha, é alta e bastante esguia. Lábios muito finos e intensamente corados, uma linha escarlate num rosto pálido. Cabelos de um vermelho veneziano, nariz aquilino e pescoço longo. O ruge acentua a palidez natural da pele. Olhos verde-acinzentados que se movem inquietos. Veste-se de heliotrópio, com diamantes. Parece uma orquídea e faz grandes exigências à nossa curiosidade. Em todos os movimentos, é extremamente graciosa. Uma obra de arte, em suma, mas que denota a influência de escolas demais.","ladymarkbygoodeveningdeargertrudesokindo~womenshouldknoweachother~114":"Lady Markby — Boa noite, querida Gertrude! Que gentileza a sua permitir que eu trouxesse minha amiga, a Sra. Cheveley. Duas mulheres tão encantadoras devem se conhecer!","ladychilternadvancestowardsmrscheveleywi~shehadmarriedasecondtime~161":"Lady Chiltern — Avança na direção da Sra. Cheveley com um doce sorriso. Depois, de repente, detém-se e a cumprimenta com certo distanciamento. Creio que a Sra. Cheveley e eu já nos encontramos antes. Não sabia que ela havia se casado uma segunda vez.","ladymarkbygeniallyahnowadayspeoplemarrya~isnothinglikeraceisthere~241":"Lady Markby — Jovialmente. Ah, hoje em dia as pessoas se casam sempre que podem, não é mesmo? É o que há de mais elegante. À Duquesa de Maryborough. Querida Duquesa, e como vai o Duque? O cérebro ainda fraco, suponho? Bem, é de se esperar, não é? O bom pai dele era exatamente igual. Não há nada como a boa raça, não é?","mrscheveleyplayingwithherfanbuthavewerea~eenoutofenglandforsolong~112":"Sra. Cheveley — Brincando com o leque. Mas será que nos encontramos mesmo antes, Lady Chiltern? Não consigo lembrar onde. Estive tanto tempo fora da Inglaterra.","ladychilternwewereatschooltogethermrsche~chooltogethermrscheveley~45":"Lady Chiltern — Estudamos juntas na escola, Sra. Cheveley.","mrscheveleysuperciliouslyindeedihaveforg~onthattheyweredetestable~108":"Sra. Cheveley — Com altivez. Verdade? Esqueci por completo meus tempos de escola. Tenho a vaga impressão de que eram detestáveis.","ladychilterncoldlyiamnotsurprised~erncoldlyiamnotsurprised~33":"Lady Chiltern — Friamente. Não me admira!","mrscheveleyinhersweetestmannerdoyouknowi~selfisfameonthecontinent~250":"Sra. Cheveley — Com a maior doçura. Sabe, estou ansiosa para conhecer o seu inteligente marido, Lady Chiltern. Desde que ele entrou para o Foreign Office, tem-se falado tanto dele em Viena. Chegam mesmo a conseguir escrever o nome dele corretamente nos jornais. Só isso já é fama, no continente.","ladychilternihardlythinktherewillbemuchi~bandmrscheveleymovesaway~89":"Lady Chiltern — Duvido muito que haja grande coisa em comum entre a senhora e meu marido, Sra. Cheveley! Afasta-se.","vicomtedenanjacahcheremadamequellesurpri~avenotseenyousinceberlin~68":"Vicomte de Nanjac — Ah! chère Madame, quelle surprise! Não a vejo desde Berlim!","mrscheveleynotsinceberlinvicomtefiveyear~erlinvicomtefiveyearsago~44":"Sra. Cheveley — Desde Berlim, Visconde. Cinco anos atrás!","vicomtedenanjacandyouareyoungerandmorebe~thaneverhowdoyoumanageit~71":"Vicomte de Nanjac — E a senhora está mais jovem e mais bela do que nunca. Como consegue?","mrscheveleybymakingitaruleonlytotalktope~armingpeoplelikeyourself~73":"Sra. Cheveley — Fazendo da regra só conversar com pessoas perfeitamente encantadoras como o senhor.","vicomtedenanjacahyouflattermeyoubutterme~youbuttermeastheysayhere~53":"Vicomte de Nanjac — Ah! a senhora me lisonjeia. Me passa manteiga, como dizem aqui.","mrscheveleydotheysaythatherehowdreadfulo~hatherehowdreadfulofthem~45":"Sra. Cheveley — Dizem isso aqui? Que horror da parte deles!","vicomtedenanjacyestheyhaveawonderfullang~tshouldbemorewidelyknown~69":"Vicomte de Nanjac — Sim, têm uma língua maravilhosa. Deveria ser mais conhecida.","sirrobertchilternentersamanoffortybutloo~ikedtohavepaintedhishead~798":"Entra Sir Robert Chiltern. Um homem de quarenta anos, mas que parece um pouco mais jovem. Barbeado, de traços finamente talhados, cabelos e olhos escuros. Uma personalidade marcante. Não é popular — poucas personalidades são. Mas é intensamente admirado por poucos e profundamente respeitado por muitos. O tom de suas maneiras é de perfeita distinção, com um leve toque de orgulho. Sente-se que ele tem consciência do sucesso que alcançou na vida. Um temperamento nervoso, de aspecto cansado. A boca e o queixo firmemente cinzelados contrastam de modo notável com a expressão romântica dos olhos fundos. A discrepância sugere uma separação quase completa entre paixão e intelecto, como se pensamento e emoção estivessem, cada qual, isolados em sua própria esfera por alguma violência da força de vontade. Há nervosismo nas narinas e nas mãos pálidas, finas e pontiagudas. Seria inexato chamá-lo de pitoresco. O pitoresco não sobrevive à Câmara dos Comuns. Mas van Dyck teria gostado de pintar-lhe a cabeça.","sirrobertchilterngoodeveningladymarkbyih~avebroughtsirjohnwithyou~71":"Sir Robert Chiltern — Boa noite, Lady Markby! Espero que tenha trazido Sir John.","ladymarkbyohihavebroughtamuchmorecharmin~ulitdoesagreatdealofharm~204":"Lady Markby — Ah! Trouxe uma pessoa muito mais encantadora do que Sir John. O gênio de Sir John tornou-se simplesmente insuportável desde que ele passou a levar a política a sério. Realmente, agora que a Câmara dos Comuns está tentando se tornar útil, faz um mal enorme.","sirrobertchilternihopenotladymarkbyatany~eenkindenoughtobringtous~139":"Sir Robert Chiltern — Espero que não, Lady Markby. Em todo caso, fazemos o possível para desperdiçar o tempo público, não é? Mas quem é essa pessoa encantadora que a senhora teve a bondade de nos trazer?","ladymarkbyhernameismrscheveleyoneofthedo~turnsouttobesomebodyelse~156":"Lady Markby — Chama-se Sra. Cheveley! Uma das Cheveley de Dorsetshire, suponho. Mas na verdade não sei. As famílias andam tão misturadas hoje em dia. Aliás, via de regra, todo mundo acaba sendo outra pessoa.","sirrobertchilternmrscheveleyiseemtoknowt~eveleyiseemtoknowthename~46":"Sir Robert Chiltern — Sra. Cheveley? Parece que conheço o nome.","ladymarkbyshehasjustarrivedfromvienna~hasjustarrivedfromvienna~37":"Lady Markby — Acabou de chegar de Viena.","sirrobertchilternahyesithinkiknowwhomyou~esithinkiknowwhomyoumean~44":"Sir Robert Chiltern — Ah! sim. Creio que sei de quem se trata.","ladymarkbyohshegoeseverywherethereandhas~eisagoodchefattheembassy~142":"Lady Markby — Ah! Ela frequenta tudo por lá, e tem escândalos tão agradáveis sobre todos os amigos. Preciso mesmo ir a Viena no próximo inverno. Espero que haja um bom cozinheiro na Embaixada.","sirrobertchilternifthereisnottheambassad~ytomeishouldliketoseeher~117":"Sir Robert Chiltern — Se não houver, o Embaixador certamente terá de ser chamado de volta. Faça-me o favor de me indicar a Sra. Cheveley. Gostaria de vê-la.","ladymarkbyletmeintroduceyoutomrscheveley~chilternisdyingtoknowyou~79":"Lady Markby — Deixe-me apresentá-los. À Sra. Cheveley. Minha querida, Sir Robert Chiltern está morrendo de vontade de conhecê-la!","sirrobertchilternbowingeveryoneisdyingto~ritetousaboutnothingelse~111":"Sir Robert Chiltern — Inclinando-se. Todos estão morrendo de vontade de conhecer a brilhante Sra. Cheveley. Nossos adidos em Viena não escrevem a respeito de outra coisa.","mrscheveleythankyousirrobertanacquaintan~iknowladychilternalready~161":"Sra. Cheveley — Obrigada, Sir Robert. Uma amizade que começa com um elogio está fadada a se tornar uma verdadeira amizade. Começa da maneira certa. E descubro que já conheço Lady Chiltern.","sirrobertchilternreally~sirrobertchilternreally~23":"Sir Robert Chiltern — Verdade?","mrscheveleyyesshehasjustremindedmethatwe~ttingthegoodconductprize~186":"Sra. Cheveley — Sim. Ela acabou de me lembrar que estudamos juntas. Agora me recordo perfeitamente. Ela sempre ganhava o prêmio de bom comportamento. Tenho uma lembrança nítida de Lady Chiltern sempre ganhando o prêmio de bom comportamento!","sirrobertchilternsmilingandwhatprizesdid~izesdidyougetmrscheveley~57":"Sir Robert Chiltern — Sorrindo. E que prêmios a senhora ganhou, Sra. Cheveley?","mrscheveleymyprizescamealittlelateroninl~ereforgoodconductiforget~87":"Sra. Cheveley — Meus prêmios vieram um pouco mais tarde na vida. Não creio que algum deles tenha sido por bom comportamento. Esqueço!","sirrobertchilterniamsuretheywereforsomet~wereforsomethingcharming~52":"Sir Robert Chiltern — Tenho certeza de que foram por algo encantador!","mrscheveleyidontknowthatwomenarealwaysre~fyourprettywomeninlondon~278":"Sra. Cheveley — Não sei se as mulheres são sempre recompensadas por serem encantadoras. Acho que, em geral, são punidas por isso! Certamente hoje em dia há mais mulheres que envelhecem por causa da fidelidade de seus admiradores do que por qualquer outra coisa! Pelo menos é a única maneira que encontro de explicar o aspecto terrivelmente abatido da maioria das suas belas mulheres de Londres!","sirrobertchilternwhatanappallingphilosop~eligionslefttousnowadays~210":"Sir Robert Chiltern — Que filosofia apavorante! Tentar classificá-la, Sra. Cheveley, seria impertinência. Mas posso perguntar-lhe, no fundo, a senhora é otimista ou pessimista? Parecem ser as duas únicas religiões da moda que nos restam hoje em dia.","mrscheveleyohimneitheroptimismbeginsinab~arebothofthemmerelyposes~117":"Sra. Cheveley — Oh, não sou nem uma coisa nem outra. O Otimismo começa num largo sorriso, e o Pessimismo acaba em óculos azuis. Além disso, ambos não passam de poses.","sirrobertchilternyouprefertobenatural~ternyouprefertobenatural~37":"Sir Robert Chiltern — A senhora prefere ser natural?","mrscheveleysometimesbutitissuchaverydiff~erydifficultposetokeepup~57":"Sra. Cheveley — Às vezes. Mas é uma pose tão difícil de manter.","sirrobertchilternwhatwouldthosemodernpsy~chsaytosuchatheoryasthat~99":"Sir Robert Chiltern — O que diriam os modernos romancistas psicológicos, de quem tanto ouvimos falar, de uma teoria como essa?","mrscheveleyahthestrengthofwomencomesfrom~nalysedwomenmerelyadored~109":"Sra. Cheveley — Ah! a força das mulheres vem do fato de que a psicologia não consegue nos explicar. Os homens podem ser analisados, as mulheres… apenas adoradas.","sirrobertchilternyouthinksciencecannotgr~plewiththeproblemofwomen~66":"Sir Robert Chiltern — A senhora acha que a ciência não consegue lidar com o problema das mulheres?","mrscheveleysciencecannevergrapplewiththe~uturebeforeitinthisworld~91":"Sra. Cheveley — A ciência nunca consegue lidar com o irracional. É por isso que ela não tem futuro, neste mundo.","sirrobertchilternandwomenrepresenttheirr~enrepresenttheirrational~47":"Sir Robert Chiltern — E as mulheres representam o irracional.","mrscheveleywelldressedwomendo~eveleywelldressedwomendo~29":"Sra. Cheveley — As bem-vestidas, sim.","sirrobertchilternwithapolitebowifearicou~sthequestionisindiscreet~175":"Sir Robert Chiltern — Com uma polida reverência. Temo não poder concordar inteiramente com a senhora. Mas sente-se, por favor. E agora diga-me, o que a faz deixar a sua brilhante Viena pela nossa sombria Londres — ou talvez a pergunta seja indiscreta?","mrscheveleyquestionsareneverindiscreetan~creetanswerssometimesare~57":"Sra. Cheveley — As perguntas nunca são indiscretas. As respostas às vezes são.","sirrobertchilternwellatanyratemayiknowif~ifitispoliticsorpleasure~62":"Sir Robert Chiltern — Bem, em todo caso, posso saber se é política ou prazer?","mrscheveleypoliticsaremyonlypleasureyous~thinktheyaremorebecoming~338":"Sra. Cheveley — A política é o meu único prazer. Veja, hoje em dia não está na moda flertar até os quarenta anos, nem ser romântica até os quarenta e cinco, de modo que nós, pobres mulheres com menos de trinta anos, ou que dizem ter, não temos outra opção senão a política ou a filantropia. E a filantropia me parece ter se tornado simplesmente o refúgio de gente que deseja importunar o próximo. Prefiro a política. Acho-a mais… favorecedora!","sirrobertchilternapoliticallifeisanoblec~iticallifeisanoblecareer~45":"Sir Robert Chiltern — A vida política é uma carreira nobre!","mrscheveleysometimesandsometimesitisacle~etimesitisagreatnuisance~86":"Sra. Cheveley — Às vezes. E às vezes é um jogo inteligente, Sir Robert. E às vezes é um grande aborrecimento.","sirrobertchilternwhichdoyoufindit~chilternwhichdoyoufindit~33":"Sir Robert Chiltern — Qual dos três a senhora acha que é?","mrscheveleyiacombinationofallthreedropsh~ionofallthreedropsherfan~45":"Sra. Cheveley — Eu? Uma combinação dos três. Deixa cair o leque.","sirrobertchilternpicksupfanallowme~hilternpicksupfanallowme~34":"Sir Robert Chiltern — Apanha o leque. Permita-me!","mrscheveleythanks~mrscheveleythanks~17":"Sra. Cheveley — Obrigada.","sirrobertchilternbutyouhavenottoldmeyetw~nlyourseasonisalmostover~94":"Sir Robert Chiltern — Mas a senhora ainda não me disse o que a leva a honrar Londres tão de repente. Nossa temporada está quase no fim.","mrscheveleyohidontcareaboutthelondonseas~askyoutodosomethingforme~241":"Sra. Cheveley — Ah! Não me importo com a temporada londrina! É matrimonial demais. As pessoas ou estão caçando maridos ou fugindo deles. Eu queria conhecê-lo. É a mais pura verdade. O senhor sabe o que é a curiosidade de uma mulher. Quase tão grande quanto a de um homem! Eu queria imensamente conhecê-lo e… lhe pedir que fizesse algo por mim.","sirrobertchilternihopeitisnotalittlethin~gsaresoverydifficulttodo~95":"Sir Robert Chiltern — Espero que não seja coisa pequena, Sra. Cheveley. Acho que as coisas pequenas são tão difíceis de fazer.","mrscheveleyafteramomentsreflectionnoidon~inkitisquitealittlething~67":"Sra. Cheveley — Depois de um momento de reflexão. Não, não creio que seja propriamente uma coisa pequena.","sirrobertchilterniamsogladdotellmewhatit~amsogladdotellmewhatitis~42":"Sir Robert Chiltern — Fico tão contente. Diga-me do que se trata.","mrscheveleylateronrisesandnowmayiwalkthr~ouhadsomewonderfulcorots~162":"Sra. Cheveley — Mais tarde. Levanta-se. E agora, posso percorrer a sua bela casa? Ouvi dizer que seus quadros são encantadores. O pobre Barão Arnheim — lembra-se do Barão? — costumava me dizer que o senhor tinha uns Corots maravilhosos.","sirrobertchilternwithanalmostimperceptib~dyouknowbaronarnheimwell~73":"Sir Robert Chiltern — Com um sobressalto quase imperceptível. A senhora conhecia bem o Barão Arnheim?","mrscheveleysmilingintimatelydidyou~ysmilingintimatelydidyou~34":"Sra. Cheveley — Sorrindo. Intimamente. E o senhor?","sirrobertchilternatonetime~rrobertchilternatonetime~26":"Sir Robert Chiltern — Numa época.","mrscheveleywonderfulmanwasnthe~veleywonderfulmanwasnthe~30":"Sra. Cheveley — Homem extraordinário, não era?","sirrobertchilternafterapausehewasveryrem~veryremarkableinmanyways~57":"Sir Robert Chiltern — Depois de uma pausa. Era muito notável, em muitos aspectos.","mrscheveleyioftenthinkitsuchapityhenever~dhavebeenmostinteresting~87":"Sra. Cheveley — Penso muitas vezes que pena ele nunca ter escrito suas memórias. Teriam sido interessantíssimas.","sirrobertchilternyesheknewmenandcitieswe~itieswellliketheoldgreek~57":"Sir Robert Chiltern — Sim: conhecia os homens e as cidades, como o velho grego.","mrscheveleywithoutthedreadfuldisadvantag~elopewaitingathomeforhim~77":"Sra. Cheveley — Sem a terrível desvantagem de ter uma Penélope esperando por ele em casa.","masonlordgoring~masonlordgoring~15":"Mason — Lord Goring.","enterlordgoringthirtyfourbutalwayssayshe~itgiveshimapostofvantage~274":"Entra Lord Goring. Trinta e quatro anos, mas sempre diz ser mais jovem. Um rosto bem-educado e inexpressivo. É inteligente, mas não gostaria de passar por isso. Dândi impecável, ficaria aborrecido se o julgassem romântico. Brinca com a vida e vive em perfeitos termos com o mundo. Gosta de ser mal compreendido. Isso lhe dá uma posição vantajosa.","sirrobertchilterngoodeveningmydeararthur~ringtheidlestmaninlondon~104":"Sir Robert Chiltern — Boa noite, meu caro Arthur! Sra. Cheveley, permita-me apresentar-lhe Lord Goring, o homem mais ocioso de Londres.","mrscheveleyihavemetlordgoringbefore~ihavemetlordgoringbefore~35":"Sra. Cheveley — Já conheci Lord Goring.","lordgoringbowingididnotthinkyouwouldreme~uldremembermemrscheveley~57":"Lord Goring — Inclinando-se. Não pensei que a senhora se lembrasse de mim, Sra. Cheveley.","mrscheveleymymemoryisunderadmirablecontr~landareyoustillabachelor~65":"Sra. Cheveley — Minha memória está sob admirável controle. E o senhor continua solteiro?","lordgoringibelieveso~lordgoringibelieveso~20":"Lord Goring — Eu… creio que sim.","mrscheveleyhowveryromantic~scheveleyhowveryromantic~26":"Sra. Cheveley — Que romântico!","lordgoringohiamnotatallromanticiamnotold~ileaveromancetomyseniors~70":"Lord Goring — Oh! Não sou nem um pouco romântico. Não tenho idade para isso. Deixo o romance para meus mais velhos.","sirrobertchilternlordgoringistheresultof~ofboodlesclubmrscheveley~62":"Sir Robert Chiltern — Lord Goring é produto do Boodle’s Club, Sra. Cheveley.","mrscheveleyhereflectseverycreditontheins~rycreditontheinstitution~48":"Sra. Cheveley — Ele honra sobremaneira a instituição.","lordgoringmayiaskareyoustayinginlondonlo~reyoustayinginlondonlong~42":"Lord Goring — Posso perguntar se a senhora pretende ficar muito tempo em Londres?","mrscheveleythatdependspartlyontheweather~kingandpartlyonsirrobert~78":"Sra. Cheveley — Depende em parte do tempo, em parte da cozinha e em parte de Sir Robert.","sirrobertchilternyouarenotgoingtoplungeu~eusintoaeuropeanwarihope~62":"Sir Robert Chiltern — Não vai nos lançar numa guerra europeia, espero?","mrscheveleythereisnodangeratpresent~thereisnodangeratpresent~35":"Sra. Cheveley — Não há perigo, por enquanto!","shenodstolordgoringwithalookofamusementi~ntersovertomabelchiltern~116":"Ela acena com a cabeça para Lord Goring, com um olhar divertido, e sai com Sir Robert Chiltern. Lord Goring caminha displicente até Mabel Chiltern.","mabelchilternyouareverylate~elchilternyouareverylate~27":"Mabel Chiltern — O senhor está muito atrasado!","lordgoringhaveyoumissedme~ordgoringhaveyoumissedme~25":"Lord Goring — Sentiu a minha falta?","mabelchilternawfully~mabelchilternawfully~20":"Mabel Chiltern — Horrivelmente!","lordgoringtheniamsorryididnotstayawaylon~aylongerilikebeingmissed~59":"Lord Goring — Então lamento não ter ficado ausente por mais tempo. Gosto que sintam a minha falta.","mabelchilternhowveryselfishofyou~lternhowveryselfishofyou~32":"Mabel Chiltern — Que egoísmo o seu!","lordgoringiamveryselfish~lordgoringiamveryselfish~24":"Lord Goring — Sou muito egoísta.","mabelchilternyouarealwaystellingmeofyour~urbadqualitieslordgoring~62":"Mabel Chiltern — O senhor está sempre me contando seus defeitos, Lord Goring.","lordgoringihaveonlytoldyouhalfofthemasye~halfofthemasyetmissmabel~50":"Lord Goring — Só lhe contei metade deles até agora, Srta. Mabel!","mabelchilternaretheothersverybad~lternaretheothersverybad~32":"Mabel Chiltern — Os outros são muito ruins?","lordgoringquitedreadfulwhenithinkofthema~matnightigotosleepatonce~62":"Lord Goring — Simplesmente terríveis! Quando penso neles à noite, adormeço na hora.","mabelchilternwellidelightinyourbadqualit~haveyoupartwithoneofthem~75":"Mabel Chiltern — Pois eu me encanto com os seus defeitos. Não gostaria que o senhor abrisse mão de nenhum.","lordgoringhowveryniceofyoubutthenyouarea~oftheroomwithyourbrother~175":"Lord Goring — Que gentileza a sua! Mas a senhorita é sempre gentil. A propósito, quero lhe fazer uma pergunta, Srta. Mabel. Quem trouxe a Sra. Cheveley aqui? Aquela mulher de heliotrópio, que acabou de sair da sala com o seu irmão?","mabelchilternohithinkladymarkbybroughthe~kbybroughtherwhydoyouask~52":"Mabel Chiltern — Ah, acho que foi Lady Markby. Por que pergunta?","lordgoringihaventseenherforyearsthatisal~seenherforyearsthatisall~41":"Lord Goring — Não a vejo há anos, só isso.","mabelchilternwhatanabsurdreason~ilternwhatanabsurdreason~31":"Mabel Chiltern — Que razão absurda!","lordgoringallreasonsareabsurd~oringallreasonsareabsurd~29":"Lord Goring — Todas as razões são absurdas.","mabelchilternwhatsortofawomanisshe~ernwhatsortofawomanisshe~34":"Mabel Chiltern — Que tipo de mulher ela é?","lordgoringohageniusinthedaytimeandabeaut~daytimeandabeautyatnight~48":"Lord Goring — Ah! Um gênio de dia e uma beldade à noite!","mabelchilternidislikeheralready~ilternidislikeheralready~31":"Mabel Chiltern — Já não gosto dela.","lordgoringthatshowsyouradmirablegoodtast~wsyouradmirablegoodtaste~41":"Lord Goring — Isso mostra o seu admirável bom gosto.","vicomtedenanjacapproachingahtheenglishyo~uitethedragonofgoodtaste~102":"Vicomte de Nanjac — Aproximando-se. Ah, a jovem inglesa é o dragão do bom gosto, não é? Um verdadeiro dragão do bom gosto.","lordgoringsothenewspapersarealwaystellin~papersarealwaystellingus~43":"Lord Goring — É o que os jornais vivem nos dizendo.","vicomtedenanjacireadallyourenglishnewspa~papersifindthemsoamusing~62":"Vicomte de Nanjac — Leio todos os seus jornais ingleses. Acho-os tão divertidos.","lordgoringthenmydearnanjacyoumustcertain~ainlyreadbetweenthelines~61":"Lord Goring — Então, meu caro Nanjac, o senhor deve certamente ler nas entrelinhas.","vicomtedenanjacishouldliketobutmyprofess~themusicroommademoiselle~123":"Vicomte de Nanjac — Eu gostaria, mas meu professor não permite. A Mabel Chiltern. Posso ter o prazer de acompanhá-la até a sala de música, Mademoiselle?","mabelchilternlookingverydisappointeddeli~tyoucomingtothemusicroom~113":"Mabel Chiltern — Parecendo muito desapontada. Encantada, Visconde, absolutamente encantada! Voltando-se para Lord Goring. O senhor não vem à sala de música?","lordgoringnotifthereisanymusicgoingonmis~anymusicgoingonmissmabel~46":"Lord Goring — Não se houver música sendo tocada, Srta. Mabel.","mabelchilternseverelythemusicisingermany~nyouwouldnotunderstandit~62":"Mabel Chiltern — Severamente. A música é em alemão. O senhor não entenderia.","goesoutwiththevicomtedenanjaclordcaversh~cavershamcomesuptohisson~57":"Sai com o Vicomte de Nanjac. Lord Caversham aproxima-se do filho.","lordcavershamwellsirwhatareyoudoingherew~llfouroclockinthemorning~170":"Lord Caversham — Pois então, senhor! que faz aqui? Desperdiçando a vida como de costume! Devia estar na cama, senhor. Mantém horários demasiado tardios! Ouvi falar de você outra noite na casa de Lady Rufford, dançando até as quatro da manhã!","lordgoringonlyaquartertofourfather~onlyaquartertofourfather~34":"Lord Goring — Só até um quarto para as quatro, pai.","lordcavershamcantmakeouthowyoustandlondo~odiestalkingaboutnothing~111":"Lord Caversham — Não consigo entender como suporta a Sociedade londrina. A coisa foi para o brejo, um bando de malditos joões-ninguém falando sobre nada.","lordgoringilovetalkingaboutnothingfather~ythingiknowanythingabout~74":"Lord Goring — Adoro falar sobre nada, pai. É a única coisa sobre a qual entendo alguma coisa.","lordcavershamyouseemtometobelivingentire~ivingentirelyforpleasure~53":"Lord Caversham — Parece-me que você vive inteiramente para o prazer.","lordgoringwhatelseistheretoliveforfather~nothingageslikehappiness~64":"Lord Goring — Para que mais se há de viver, pai? Nada envelhece tanto quanto a felicidade.","lordcavershamyouareheartlesssirveryheart~eartlesssirveryheartless~44":"Lord Caversham — Você é sem coração, senhor, muito sem coração!","lordgoringihopenotfathergoodeveningladyb~rgoodeveningladybasildon~47":"Lord Goring — Espero que não, pai. Boa noite, Lady Basildon!","ladybasildonarchingtwoprettyeyebrowsarey~ercametopoliticalparties~85":"Lady Basildon — Arqueando duas lindas sobrancelhas. O senhor está aqui? Não fazia ideia de que frequentava reuniões políticas!","lordgoringiadorepoliticalpartiestheyaret~repeopledonttalkpolitics~86":"Lord Goring — Adoro reuniões políticas. São o único lugar que nos resta onde as pessoas não falam de política.","ladybasildonidelightintalkingpoliticsita~usestandtheselongdebates~143":"Lady Basildon — Eu adoro falar de política. Falo dela o dia inteiro. Mas não suporto ouvi-la. Não sei como os infelizes homens da Câmara aguentam esses debates intermináveis.","lordgoringbyneverlistening~rdgoringbyneverlistening~26":"Lord Goring — Nunca ouvindo.","ladybasildonreally~ladybasildonreally~18":"Lady Basildon — Verdade?","lordgoringinhismostseriousmannerofcourse~oughlyunreasonableperson~185":"Lord Goring — Em seu tom mais sério. Naturalmente. Veja, é muito perigoso ouvir. Se a gente ouve, pode acabar convencido; e um homem que se deixa convencer por um argumento é uma pessoa absolutamente desarrazoada.","ladybasildonahthataccountsforsomuchinmen~ndsneverappreciateinthem~118":"Lady Basildon — Ah! isso explica tantas coisas nos homens que eu nunca compreendi, e tantas coisas nas mulheres que os maridos nunca apreciam nelas!","mrsmarchmontwithasighourhusbandsneverapp~ehavetogotoothersforthat~84":"Sra. Marchmont — Com um suspiro. Nossos maridos nunca apreciam nada em nós. Temos de recorrer a outros para isso!","ladybasildonemphaticallyyesalwaystoother~salwaystoothershavewenot~50":"Lady Basildon — Enfaticamente. Sim, sempre a outros, não é mesmo?","lordgoringsmilingandthosearetheviewsofth~dmirablehusbandsinlondon~99":"Lord Goring — Sorrindo. E essa é a opinião das duas damas que se sabe terem os mais admiráveis maridos de Londres.","mrsmarchmontthatisexactlywhatwecantstand~ofexcitementinknowinghim~158":"Sra. Marchmont — É exatamente isso que não suportamos. Meu Reginald é irremediavelmente irrepreensível. É realmente insuportável, às vezes! Não há o menor elemento de emoção em conhecê-lo.","lordgoringhowterriblereallythethingshoul~gshouldbemorewidelyknown~58":"Lord Goring — Que terrível! Realmente, isso deveria ser mais conhecido!","ladybasildonbasildonisquiteasbadheisasdo~mesticasifhewasabachelor~64":"Lady Basildon — Basildon é igualzinho; é tão caseiro como se fosse solteiro.","mrsmarchmontpressingladybasildonshandmyp~ndwearewellpunishedforit~102":"Sra. Marchmont — Apertando a mão de Lady Basildon. Minha pobre Olivia! Casamo-nos com maridos perfeitos e somos bem castigadas por isso.","lordgoringishouldhavethoughtitwasthehusb~ehusbandswhowerepunished~59":"Lord Goring — Eu teria pensado que os castigados eram os maridos.","mrsmarchmontdrawingherselfupohdearnothey~tragichowmuchtheytrustus~106":"Sra. Marchmont — Empertigando-se. Oh, de modo algum! Eles são felicíssimos! E quanto a confiarem em nós, é trágico o quanto confiam.","ladybasildonperfectlytragic~ybasildonperfectlytragic~27":"Lady Basildon — Perfeitamente trágico!","lordgoringorcomicladybasildon~oringorcomicladybasildon~29":"Lord Goring — Ou cômico, Lady Basildon?","ladybasildoncertainlynotcomiclordgoringh~ofyoutosuggestsuchathing~72":"Lady Basildon — Certamente não cômico, Lord Goring. Que maldade a sua sugerir uma coisa dessas!","mrsmarchmontiamafraidlordgoringisintheca~tmrscheveleywhenhecamein~102":"Sra. Marchmont — Receio que Lord Goring esteja no campo inimigo, como de costume. Vi-o conversando com aquela Sra. Cheveley quando ele entrou.","lordgoringhandsomewomanmrscheveley~handsomewomanmrscheveley~34":"Lord Goring — Mulher bonita, a Sra. Cheveley!","ladybasildonstifflypleasedontpraiseother~oumightwaitforustodothat~83":"Lady Basildon — Com rigidez. Por favor, não elogie outras mulheres em nossa presença. O senhor poderia esperar que nós o fizéssemos!","lordgoringididwait~lordgoringididwait~18":"Lord Goring — Eu esperei.","mrsmarchmontwellwearenotgoingtopraiseher~adeupofdowdiesanddandies~173":"Sra. Marchmont — Pois bem, nós não vamos elogiá-la. Soube que ela foi à Ópera na segunda-feira à noite e disse a Tommy Rufford, durante a ceia, que, até onde podia ver, a Sociedade londrina era inteiramente composta de desleixados e de dândis.","lordgoringsheisquiterighttoothemenareall~enarealldandiesarentthey~80":"Lord Goring — E tem toda a razão. Os homens são todos desleixados e as mulheres são todas dândis, não são?","mrsmarchmontafterapauseohdoyoureallythin~atiswhatmrscheveleymeant~67":"Sra. Marchmont — Depois de uma pausa. Oh! o senhor acha mesmo que era isso que a Sra. Cheveley queria dizer?","lordgoringofcourseandaverysensibleremark~kformrscheveleytomaketoo~63":"Lord Goring — Claro. E uma observação muito sensata da parte da Sra. Cheveley, aliás.","entermabelchilternshejoinsthegroup~chilternshejoinsthegroup~34":"Entra Mabel Chiltern. Junta-se ao grupo.","mabelchilternwhyareyoutalkingaboutmrsche~daytimeandabeautyatnight~189":"Mabel Chiltern — Por que estão falando da Sra. Cheveley? Todo mundo está falando da Sra. Cheveley! Lord Goring diz — o que o senhor disse, Lord Goring, sobre a Sra. Cheveley? Ah! lembrei, que ela era um gênio de dia e uma beldade à noite.","ladybasildonwhatahorridcombinationsovery~mbinationsoveryunnatural~49":"Lady Basildon — Que combinação horrível! Tão pouco natural!","mrsmarchmontinhermostdreamymannerilikelo~steningtobeautifulpeople~84":"Sra. Marchmont — Em seu tom mais sonhador. Gosto de olhar para gênios e de ouvir pessoas bonitas.","lordgoringahthatismorbidofyoumrsmarchmon~smorbidofyoumrsmarchmont~41":"Lord Goring — Ah! isso é mórbido da sua parte, Sra. Marchmont!","mrsmarchmontbrighteningtoalookofrealplea~resopainfullyunobservant~175":"Sra. Marchmont — Iluminando-se num olhar de verdadeiro prazer. Fico tão contente de ouvi-lo dizer isso. Marchmont e eu estamos casados há sete anos e ele nunca me disse uma só vez que eu era mórbida. Os homens são tão dolorosamente desatentos!","ladybasildonturningtoherihavealwayssaidd~mostmorbidpersoninlondon~89":"Lady Basildon — Voltando-se para ela. Sempre disse, querida Margaret, que você era a pessoa mais mórbida de Londres.","mrsmarchmontahbutyouarealwayssympathetic~ealwayssympatheticolivia~46":"Sra. Marchmont — Ah! mas você é sempre compreensiva, Olivia!","mabelchilternisitmorbidtohaveadesireforf~gwillyougivemesomesupper~100":"Mabel Chiltern — É mórbido ter desejo de comer? Eu tenho grande desejo de comer. Lord Goring, quer me dar um pouco de ceia?","lordgoringwithpleasuremissmabelmovesaway~issmabelmovesawaywithher~47":"Lord Goring — Com prazer, Srta. Mabel. Afasta-se com ela.","mabelchilternhowhorridyouhavebeenyouhave~alkedtomethewholeevening~70":"Mabel Chiltern — Como o senhor foi horrível! Não falou comigo a noite inteira!","lordgoringhowcouldiyouwentawaywiththechi~ywiththechilddiplomatist~53":"Lord Goring — Como poderia? A senhorita saiu com o diplomata-criança.","mabelchilternyoumighthavefolloweduspursu~ilikeyouatallthisevening~99":"Mabel Chiltern — O senhor poderia ter nos seguido. Teria sido só educado. Não acho que gosto do senhor esta noite!","lordgoringilikeyouimmensely~dgoringilikeyouimmensely~27":"Lord Goring — Eu gosto imensamente da senhorita.","mabelchilternwelliwishyoudshowitinamorem~arkedwaytheygodownstairs~64":"Mabel Chiltern — Pois gostaria que o demonstrasse de maneira mais marcada! Descem as escadas.","mrsmarchmontoliviaihaveacuriousfeelingof~nowishouldlikesomesupper~118":"Sra. Marchmont — Olivia, tenho uma curiosa sensação de absoluto desfalecimento. Acho que gostaria muito de um pouco de ceia. Sei que gostaria de um pouco de ceia.","ladybasildoniampositivelydyingforsupperm~lydyingforsuppermargaret~47":"Lady Basildon — Estou positivamente morrendo de vontade de ceia, Margaret!","mrsmarchmontmenaresohorriblyselfishtheyn~yneverthinkofthesethings~62":"Sra. Marchmont — Os homens são horrivelmente egoístas, nunca pensam nessas coisas.","ladybasildonmenaregrosslymaterialgrossly~ymaterialgrosslymaterial~48":"Lady Basildon — Os homens são grosseiramente materiais, grosseiramente materiais!","thevicomtedenanjacentersfromthemusicroom~heapproachesladybasildon~130":"O Vicomte de Nanjac entra da sala de música com outros convidados. Depois de examinar cuidadosamente todas as pessoas presentes, aproxima-se de Lady Basildon.","vicomtedenanjacmayihavethehonouroftaking~gyoudowntosuppercomtesse~63":"Vicomte de Nanjac — Posso ter a honra de acompanhá-la à ceia, Comtesse?","ladybasildoncoldlyinevertakesupperthanky~edownwithyouwithpleasure~156":"Lady Basildon — Friamente. Nunca ceio, obrigada, Visconde. O Visconde está prestes a se retirar. Lady Basildon, vendo isso, levanta-se de imediato e toma-lhe o braço. Mas descerei com o senhor com prazer.","vicomtedenanjaciamsofondofeatingiamverye~veryenglishinallmytastes~59":"Vicomte de Nanjac — Gosto tanto de comer! Sou muito inglês em todos os meus gostos.","ladybasildonyoulookquiteenglishvicomtequ~glishvicomtequiteenglish~50":"Lady Basildon — O senhor parece bastante inglês, Visconde, bastante inglês.","theypassoutmrmontfordaperfectlygroomedyo~dyapproachesmrsmarchmont~70":"Saem. O Sr. Montford, um jovem dândi perfeitamente aprumado, aproxima-se da Sra. Marchmont.","mrmontfordlikesomesuppermrsmarchmont~kesomesuppermrsmarchmont~36":"Sr. Montford — Quer um pouco de ceia, Sra. Marchmont?","mrsmarchmontlanguidlythankyoumrmontfordi~lsitbesideyouandwatchyou~113":"Sra. Marchmont — Languidamente. Obrigada, Sr. Montford, nunca toco em ceia. Levanta-se apressada e toma-lhe o braço. Mas sentarei ao seu lado e ficarei olhando.","mrmontfordidontknowthatilikebeingwatched~eingwatchedwheniameating~53":"Sr. Montford — Não sei se gosto de ser olhado enquanto como!","mrsmarchmonttheniwillwatchsomeoneelse~heniwillwatchsomeoneelse~37":"Sra. Marchmont — Então olharei para outra pessoa.","mrmontfordidontknowthatishouldlikethatei~hatishouldlikethateither~44":"Sr. Montford — Não sei se gostaria disso também.","mrsmarchmontseverelypraymrmontforddonotm~scenesofjealousyinpublic~79":"Sra. Marchmont — Severamente. Por favor, Sr. Montford, não faça essas cenas penosas de ciúme em público!","theygodownstairswiththeotherguestspassin~ndmrscheveleywhonowenter~83":"Descem com os demais convidados, cruzando com Sir Robert Chiltern e a Sra. Cheveley, que agora entram.","sirrobertchilternandareyougoingtoanyofou~uleaveenglandmrscheveley~86":"Sir Robert Chiltern — E a senhora pretende visitar alguma de nossas casas de campo antes de deixar a Inglaterra, Sra. Cheveley?","mrscheveleyohnoicantstandyourenglishhous~rrobertsitsdownonthesofa~268":"Sra. Cheveley — Ah, não! Não suporto as suas temporadas inglesas no campo. Na Inglaterra as pessoas chegam a tentar ser brilhantes no café da manhã. Que horror da parte delas! Só gente maçante é brilhante no café da manhã. E depois o esqueleto da família está sempre lendo as orações familiares. Minha permanência na Inglaterra depende realmente do senhor, Sir Robert. Senta-se no sofá.","sirrobertchilterntakingaseatbesideherser~gaseatbesideherseriously~46":"Sir Robert Chiltern — Tomando assento ao lado dela. Seriamente?","mrscheveleyquiteseriouslyiwanttotalktoyo~entinecanalcompanyinfact~115":"Sra. Cheveley — Muito seriamente. Quero falar-lhe de um grande projeto político e financeiro, desta Companhia do Canal Argentino, para ser exata.","sirrobertchilternwhatatediouspracticalsu~outotalkaboutmrscheveley~73":"Sir Robert Chiltern — Que assunto tedioso e prático para a senhora tratar, Sra. Cheveley!","mrscheveleyohiliketediouspracticalsubjec~boughtthesuezcanalshares~234":"Sra. Cheveley — Ah, gosto de assuntos tediosos e práticos. O que não gosto é de pessoas tediosas e práticas. Há uma grande diferença. Além disso, sei que o senhor se interessa por projetos de canais internacionais. Foi secretário de Lord Radley, não foi, quando o Governo comprou as ações do Canal de Suez?","sirrobertchilternyesbutthesuezcanalwasav~lacestockexchangeswindle~207":"Sir Robert Chiltern — Sim. Mas o Canal de Suez foi um empreendimento grandioso e esplêndido. Deu-nos a rota direta para a Índia. Tinha valor imperial. Era necessário que tivéssemos controle. Este projeto argentino é uma vulgar fraude da Bolsa.","mrscheveleyaspeculationsirrobertabrillia~illiantdaringspeculation~59":"Sra. Cheveley — Uma especulação, Sir Robert! Uma especulação brilhante e ousada.","sirrobertchilternbelievememrscheveleyiti~rtooclevertohavedonethat~477":"Sir Robert Chiltern — Acredite, Sra. Cheveley, é uma fraude. Chamemos as coisas pelos seus devidos nomes. Isso simplifica as coisas. Temos todas as informações a respeito no Foreign Office. Na verdade, enviei uma Comissão especial para investigar a questão em caráter reservado, e ela informa que as obras mal começaram e, quanto ao dinheiro já subscrito, ninguém parece saber o que foi feito dele. A coisa toda é um segundo Panamá, e sem sequer um quarto da chance de êxito que aquele miserável caso teve. Espero que a senhora não tenha investido nisso. Tenho certeza de que é inteligente demais para ter feito isso.","mrscheveleyihaveinvestedverylargelyinit~einvestedverylargelyinit~39":"Sra. Cheveley — Investi muito nele.","sirrobertchilternwhocouldhaveadvisedyout~youtodosuchafoolishthing~60":"Sir Robert Chiltern — Quem poderia tê-la aconselhado a fazer tão tola coisa?","mrscheveleyyouroldfriendandmine~eleyyouroldfriendandmine~31":"Sra. Cheveley — Seu velho amigo — e meu.","sirrobertchilternwho~sirrobertchilternwho~20":"Sir Robert Chiltern — Quem?","mrscheveleybaronarnheim~mrscheveleybaronarnheim~23":"Sra. Cheveley — O Barão Arnheim.","sirrobertchilternfrowningahyesirememberh~nmixedupinthewholeaffair~101":"Sir Robert Chiltern — Franzindo o cenho. Ah! sim. Lembro-me de ter ouvido, na época de sua morte, que ele estivera envolvido em todo o caso.","mrscheveleyitwashislastromancehislastbut~lastbutonetodohimjustice~57":"Sra. Cheveley — Foi o seu último romance. O penúltimo, para ser justa com ele.","sirrobertchilternrisingbutyouhavenotseen~onttheymayishowthemtoyou~120":"Sir Robert Chiltern — Levantando-se. Mas a senhora ainda não viu os meus Corots. Estão na sala de música. Os Corots parecem combinar com a música, não é? Posso mostrá-los à senhora?","mrscheveleyshakingherheadiamnotinamoodto~ntositdownagainbesideher~142":"Sra. Cheveley — Balançando a cabeça. Não estou disposta esta noite para crepúsculos prateados ou auroras cor-de-rosa. Quero falar de negócios. Faz sinal com o leque para que ele se sente de novo ao seu lado.","sirrobertchilternifearihavenoadvicetogiv~orethehousetomorrownight~230":"Sir Robert Chiltern — Receio não ter nenhum conselho a lhe dar, Sra. Cheveley, a não ser que se interesse por algo menos perigoso. O sucesso do Canal depende, é claro, da atitude da Inglaterra, e vou apresentar o relatório dos Comissários à Câmara amanhã à noite.","mrscheveleythatyoumustnotdoinyourowninte~ngofmineyoumustnotdothat~88":"Sra. Cheveley — Isso o senhor não deve fazer. Em seu próprio interesse, Sir Robert, sem falar no meu, não deve fazê-lo.","sirrobertchilternlookingatherinwonderinm~youmeansitsdownbesideher~100":"Sir Robert Chiltern — Olhando-a com espanto. Em meu próprio interesse? Minha cara Sra. Cheveley, o que quer dizer? Senta-se ao lado dela.","mrscheveleysirrobertiwillbequitefrankwit~rldkinwillyoudothatforme~550":"Sra. Cheveley — Sir Robert, serei perfeitamente franca com o senhor. Quero que retire o relatório que pretendia apresentar à Câmara, alegando ter razões para crer que os Comissários foram influenciados ou mal informados, ou algo assim. Depois quero que diga algumas palavras no sentido de que o Governo vai reconsiderar a questão e que o senhor tem motivos para crer que o Canal, se concluído, será de grande valor internacional. O senhor sabe o tipo de coisa que os ministros dizem em casos como este. Algumas banalidades comuns bastarão. Na vida moderna nada produz tanto efeito quanto uma boa banalidade. Faz o mundo inteiro parente. Fará isso por mim?","sirrobertchilternmrscheveleyyoucannotbes~makingmesuchaproposition~72":"Sir Robert Chiltern — Sra. Cheveley, a senhora não pode estar falando sério ao me fazer tal proposta!","mrscheveleyiamquiteserious~scheveleyiamquiteserious~26":"Sra. Cheveley — Estou falando muito sério.","sirrobertchilterncoldlyprayallowmetobeli~metobelievethatyouarenot~56":"Sir Robert Chiltern — Friamente. Permita-me acreditar que não está.","mrscheveleyspeakingwithgreatdeliberation~willpayyouveryhandsomely~105":"Sra. Cheveley — Falando com grande ponderação e ênfase. Ah! mas estou. E se o senhor fizer o que lhe peço, eu… o pagarei regiamente!","sirrobertchilternpayme~sirrobertchilternpayme~22":"Sir Robert Chiltern — Pagar-me!","mrscheveleyyes~mrscheveleyyes~14":"Sra. Cheveley — Sim.","sirrobertchilterniamafraididontquiteunde~iteunderstandwhatyoumean~57":"Sir Robert Chiltern — Receio não entender bem o que quer dizer.","mrscheveleyleaningbackonthesofaandlookin~ldthoroughlyunderstandme~139":"Sra. Cheveley — Recostando-se no sofá e olhando para ele. Que decepcionante! E eu vim de Viena até aqui para que o senhor me compreendesse perfeitamente.","sirrobertchilternifearidont~robertchilternifearidont~27":"Sir Robert Chiltern — Temo que não compreenda.","mrscheveleyinhermostnonchalantmannermyde~orereasonableinyourterms~216":"Sra. Cheveley — Com a maior displicência. Meu caro Sir Robert, o senhor é um homem do mundo e tem o seu preço, suponho. Todo mundo tem hoje em dia. O inconveniente é que a maioria das pessoas é terrivelmente cara. Sei que eu sou. Espero que o senhor seja mais razoável em suas condições.","sirrobertchilternrisesindignantlyifyouwi~kingtoanenglishgentleman~178":"Sir Robert Chiltern — Levanta-se indignado. Se me permite, mandarei chamar a sua carruagem. A senhora viveu tanto tempo no estrangeiro, Sra. Cheveley, que parece incapaz de perceber que está falando com um cavalheiro inglês.","mrscheveleydetainshimbytouchinghisarmwit~speculatoracabinetsecret~190":"Sra. Cheveley — Detém-no tocando-lhe o braço com o leque e mantendo-o ali enquanto fala. Percebo que estou falando com um homem que lançou os alicerces de sua fortuna vendendo a um especulador da Bolsa um segredo de Gabinete.","sirrobertchilternbitinghislipwhatdoyoume~itinghislipwhatdoyoumean~42":"Sir Robert Chiltern — Mordendo o lábio. O que quer dizer?","mrscheveleyrisingandfacinghimimeanthatik~andihavegotyourlettertoo~105":"Sra. Cheveley — Levantando-se e encarando-o. Quero dizer que conheço a verdadeira origem da sua riqueza e da sua carreira, e que tenho também a sua carta.","sirrobertchilternwhatletter~robertchilternwhatletter~27":"Sir Robert Chiltern — Que carta?","mrscheveleycontemptuouslytheletteryouwro~tannounceditsownpurchase~187":"Sra. Cheveley — Com desprezo. A carta que o senhor escreveu ao Barão Arnheim, quando era secretário de Lord Radley, dizendo ao Barão que comprasse ações do Canal de Suez — uma carta escrita três dias antes de o Governo anunciar a sua própria compra.","sirrobertchilternhoarselyitisnottrue~lternhoarselyitisnottrue~36":"Sir Robert Chiltern — Roucamente. Não é verdade.","mrscheveleyyouthoughtthatletterhadbeende~hofyouitisinmypossession~80":"Sra. Cheveley — O senhor pensava que a carta tinha sido destruída. Que tolice a sua! Está em meu poder.","sirrobertchilterntheaffairtowhichyouallu~litmighthavebeenrejected~129":"Sir Robert Chiltern — O caso a que a senhora alude não passou de uma especulação. A Câmara dos Comuns ainda não havia aprovado o projeto; ele poderia ter sido rejeitado.","mrscheveleyitwasaswindlesirrobertletusca~eourfortunesoutofanother~270":"Sra. Cheveley — Foi uma fraude, Sir Robert. Chamemos as coisas pelos seus devidos nomes. Isso simplifica tudo. E agora vou lhe vender aquela carta, e o preço que peço por ela é o seu apoio público ao projeto argentino. O senhor fez sua própria fortuna com um canal. Deve ajudar a mim e a meus amigos a fazer a nossa com outro!","sirrobertchilternitisinfamouswhatyouprop~uswhatyouproposeinfamous~51":"Sir Robert Chiltern — É infame o que a senhora propõe — infame!","mrscheveleyohnothisisthegameoflifeasweal~itsirrobertsoonerorlater~75":"Sra. Cheveley — Oh, não! Este é o jogo da vida como todos temos de jogá-lo, Sir Robert, mais cedo ou mais tarde!","sirrobertchilternicannotdowhatyouaskme~ernicannotdowhatyouaskme~38":"Sir Robert Chiltern — Não posso fazer o que me pede.","mrscheveleyyoumeanyoucannothelpdoingityo~ptthemsupposingyourefuse~147":"Sra. Cheveley — Quer dizer que não pode deixar de fazê-lo. O senhor sabe que está à beira de um precipício. E não cabe ao senhor impor condições. Cabe-lhe aceitá-las. Suponhamos que recuse…","sirrobertchilternwhatthen~irrobertchilternwhatthen~25":"Sir Robert Chiltern — E então?","mrscheveleymydearsirrobertwhatthenyouare~ouseinfavourofthisscheme~1434":"Sra. Cheveley — Meu caro Sir Robert, e então? Está arruinado, só isso! Lembre-se a que ponto o seu Puritanismo na Inglaterra o conduziu. Antigamente ninguém fingia ser um pouco melhor que os vizinhos. Na verdade, ser um pouco melhor que o vizinho era considerado excessivamente vulgar e pequeno-burguês. Hoje, com a nossa moderna mania de moralidade, todos têm de posar de modelo de pureza, incorruptibilidade e todas as outras sete virtudes mortais — e qual é o resultado? Vocês caem todos como pinos de boliche — um após o outro. Não passa um ano na Inglaterra sem que alguém desapareça. Os escândalos costumavam conferir encanto, ou ao menos interesse, a um homem — agora o esmagam. E o seu é um escândalo muito desagradável. O senhor não sobreviveria a ele. Se se soubesse que, quando jovem, secretário de um grande e importante ministro, vendeu um segredo de Gabinete por uma grande soma de dinheiro, e que essa foi a origem de sua riqueza e de sua carreira, seria escorraçado da vida pública, desapareceria por completo. E afinal, Sir Robert, por que sacrificar todo o seu futuro em vez de negociar diplomaticamente com o seu inimigo? Por ora sou sua inimiga. Admito! E sou muito mais forte do que o senhor. Os grandes batalhões estão do meu lado. O senhor tem uma posição esplêndida, mas é justamente essa posição esplêndida que o torna tão vulnerável. Não pode defendê-la! E eu estou atacando. Claro que não lhe falei de moral. O senhor deve admitir, por justiça, que lhe poupei isso. Anos atrás o senhor fez uma coisa inteligente e inescrupulosa; resultou num grande sucesso. Deve-lhe sua fortuna e sua posição. E agora tem de pagar por isso. Mais cedo ou mais tarde todos temos de pagar pelo que fazemos. O senhor tem de pagar agora. Antes que eu o deixe esta noite, tem de me prometer suprimir o seu relatório e falar na Câmara a favor deste projeto.","sirrobertchilternwhatyouaskisimpossible~rnwhatyouaskisimpossible~39":"Sir Robert Chiltern — O que a senhora pede é impossível.","mrscheveleyyoumustmakeitpossibleyouarego~ulnessofthepublicplacard~409":"Sra. Cheveley — O senhor tem de tornar possível. Vai tornar possível. Sir Robert, o senhor sabe como são os seus jornais ingleses. Suponha que, ao sair desta casa, eu vá até a redação de algum jornal e lhes entregue este escândalo e as provas dele! Pense na alegria nojenta deles, no deleite que teriam em arrastá-lo para baixo, na lama e no lodaçal em que o mergulhariam. Pense no hipócrita, com seu sorriso gorduroso, redigindo o artigo de fundo e arranjando a imundície do cartaz público.","sirrobertchilternstopyouwantmetowithdraw~possibilitiesinthescheme~121":"Sir Robert Chiltern — Pare! A senhora quer que eu retire o relatório e faça um breve discurso declarando que acredito haver possibilidades no projeto?","mrscheveleysittingdownonthesofathosearem~onthesofathosearemyterms~46":"Sra. Cheveley — Sentando-se no sofá. Essas são as minhas condições.","sirrobertchilterninalowvoiceiwillgiveyou~eyouanysumofmoneyyouwant~60":"Sir Robert Chiltern — Em voz baixa. Dar-lhe-ei qualquer quantia de dinheiro que quiser.","mrscheveleyevenyouarenotrichenoughsirrob~tobuybackyourpastnomanis~67":"Sra. Cheveley — Nem mesmo o senhor é rico o bastante, Sir Robert, para comprar de volta o seu passado. Nenhum homem é.","sirrobertchilterniwillnotdowhatyouaskmei~otdowhatyouaskmeiwillnot~47":"Sir Robert Chiltern — Não farei o que me pede. Não farei.","mrscheveleyyouhavetoifyoudontrisesfromth~fyoudontrisesfromthesofa~45":"Sra. Cheveley — O senhor tem de fazer. Se não… Levanta-se do sofá.","sirrobertchilternbewilderedandunnervedwa~vemebackmyletterdidntyou~111":"Sir Robert Chiltern — Perturbado e abalado. Espere um momento! O que a senhora propôs? Disse que me devolveria a minha carta, não foi?","mrscheveleyyesthatisagreediwillbeinthela~methatamongstotherthings~402":"Sra. Cheveley — Sim. Está combinado. Estarei na Galeria das Damas amanhã à noite, às onze e meia. Se até lá — e o senhor terá tido muitíssimas oportunidades — tiver feito à Câmara um anúncio nos termos que desejo, devolver-lhe-ei a carta com os mais belos agradecimentos e o melhor, ou ao menos o mais adequado, cumprimento que eu conseguir imaginar. Pretendo jogar de modo bastante limpo com o senhor. Deve-se sempre jogar limpo… quando se têm as cartas vencedoras. O Barão me ensinou isso… entre outras coisas.","sirrobertchilternyoumustletmehavetimetoc~metoconsideryourproposal~59":"Sir Robert Chiltern — A senhora precisa me dar tempo para considerar a sua proposta.","mrscheveleynoyoumustsettlenow~eveleynoyoumustsettlenow~29":"Sra. Cheveley — Não; o senhor deve decidir agora!","sirrobertchilterngivemeaweekthreedays~terngivemeaweekthreedays~37":"Sir Robert Chiltern — Dê-me uma semana — três dias!","mrscheveleyimpossibleihavegottotelegraph~telegraphtoviennatonight~55":"Sra. Cheveley — Impossível! Tenho de telegrafar a Viena esta noite.","sirrobertchilternmygodwhatbroughtyouinto~whatbroughtyouintomylife~46":"Sir Robert Chiltern — Meu Deus! que a trouxe à minha vida?","mrscheveleycircumstancesmovestowardsthed~ancesmovestowardsthedoor~43":"Sra. Cheveley — As circunstâncias. Dirige-se à porta.","sirrobertchilterndontgoiconsentthereport~ntobeputtomeonthesubject~103":"Sir Robert Chiltern — Não se vá. Eu consinto. O relatório será retirado. Providenciarei para que me seja feita uma pergunta sobre o assunto.","mrscheveleythankyouiknewweshouldcometoan~llyexitsirrobertchiltern~279":"Sra. Cheveley — Obrigada. Eu sabia que chegaríamos a um acordo amigável. Compreendi a sua natureza desde o primeiro momento. Analisei-o, embora o senhor não me adorasse. E agora o senhor pode mandar buscar a minha carruagem, Sir Robert. Vejo as pessoas subindo da ceia, e os ingleses sempre ficam românticos depois de uma refeição, e isso me aborrece terrivelmente. Sai Sir Robert Chiltern.","enterguestsladychilternladymarkbylordcav~icomtedenanjacmrmontford~95":"Entram os Convidados, Lady Chiltern, Lady Markby, Lord Caversham, Lady Basildon, a Sra. Marchmont, o Visconde de Nanjac, o Sr. Montford.","ladymarkbywelldearmrscheveleyihopeyouhav~sveryentertainingishenot~90":"Lady Markby — Pois bem, querida Sra. Cheveley, espero que tenha se divertido. Sir Robert é muito divertido, não é?","mrscheveleymostentertainingihaveenjoyedm~edmytalkwithhimimmensely~61":"Sra. Cheveley — Divertidíssimo! Apreciei imensamente a minha conversa com ele.","ladymarkbyhehashadaveryinterestingandbri~shallicallforyoutomorrow~387":"Lady Markby — Ele teve uma carreira muito interessante e brilhante. E casou-se com uma esposa admirável. Lady Chiltern é uma mulher dos mais elevados princípios, folgo em dizer. Eu mesma já estou velha demais para me preocupar em dar bom exemplo, mas sempre admiro quem o faz. E Lady Chiltern tem um efeito muito enobrecedor sobre a vida, embora os seus jantares sejam às vezes bastante maçantes. Mas não se pode ter tudo, não é mesmo? E agora preciso ir, querida. Passo para buscá-la amanhã?","ladymarkbywemightdriveintheparkatfiveeve~lookssofreshintheparknow~71":"Lady Markby — Poderíamos passear de carruagem no Parque às cinco. Tudo parece tão fresco no Parque agora!","mrscheveleyexceptthepeople~scheveleyexceptthepeople~26":"Sra. Cheveley — Exceto as pessoas!","ladymarkbyperhapsthepeoplearealittlejade~esoutonlordcavershamsarm~389":"Lady Markby — Talvez as pessoas estejam um pouco fatigadas. Tenho observado muitas vezes que a Temporada, à medida que avança, produz uma espécie de amolecimento do cérebro. Seja como for, acho que qualquer coisa é melhor do que a alta pressão intelectual. É a coisa mais desfavorecedora que existe. Deixa o nariz das moças particularmente grande. E não há nada tão difícil de casar quanto um nariz grande; os homens não gostam. Boa noite, querida! A Lady Chiltern. Boa noite, Gertrude! Sai de braço dado com Lord Caversham.","mrscheveleywhatacharminghouseyouhavelady~gettingtoknowyourhusband~122":"Sra. Cheveley — Que casa encantadora a sua, Lady Chiltern! Passei uma noite deliciosa. Foi tão interessante conhecer o seu marido.","ladychilternwhydidyouwishtomeetmyhusband~meetmyhusbandmrscheveley~51":"Lady Chiltern — Por que desejava conhecer meu marido, Sra. Cheveley?","mrscheveleyohiwilltellyouiwantedtointere~imitwillbeagreatoccasion~310":"Sra. Cheveley — Ah, eu lhe digo. Queria interessá-lo neste projeto do Canal Argentino, de que ouso dizer que já ouviu falar. E o achei sumamente suscetível... suscetível à razão, quero dizer. Coisa rara num homem. Convenci-o em dez minutos. Amanhã à noite ele vai fazer um discurso na Câmara a favor da ideia. Devemos ir à Galeria das Senhoras ouvi-lo! Será uma grande ocasião!","ladychilterntheremustbesomemistakethatsc~verhavemyhusbandssupport~75":"Lady Chiltern — Deve haver algum engano. Esse projeto jamais poderia contar com o apoio de meu marido.","mrscheveleyohiassureyouitsallsettledidon~ewholethingisadeadsecret~160":"Sra. Cheveley — Oh, garanto-lhe que está tudo combinado. Já não lamento a minha tediosa viagem desde Viena. Foi um grande sucesso. Mas, é claro, nas próximas vinte e quatro horas tudo isso é segredo absoluto.","ladychilterngentlyasecretbetweenwhom~gentlyasecretbetweenwhom~36":"Lady Chiltern — Suavemente. Um segredo? Entre quem?","mrscheveleywithaflashofamusementinhereye~weenyourhusbandandmyself~68":"Sra. Cheveley — Com um lampejo de divertimento nos olhos. Entre o seu marido e eu.","sirrobertchilternenteringyourcarriageish~arriageisheremrscheveley~54":"Sir Robert Chiltern — Entrando. Sua carruagem chegou, Sra. Cheveley!","mrscheveleythanksgoodeveningladychiltern~uthinkyoumightleaveacard~103":"Sra. Cheveley — Obrigada! Boa noite, Lady Chiltern! Boa noite, Lord Goring! Estou no Claridge’s. Não acha que poderia deixar um cartão?","lordgoringifyouwishitmrscheveley~ngifyouwishitmrscheveley~32":"Lord Goring — Se a senhora o deseja, Sra. Cheveley!","mrscheveleyohdontbesosolemnaboutitorisha~shallbegreatfriendsihope~234":"Sra. Cheveley — Oh, não seja tão solene a respeito, ou serei obrigada a deixar um cartão em sua casa. Na Inglaterra suponho que isso dificilmente seria considerado en règle. No estrangeiro somos mais civilizados. Acompanha-me até lá embaixo, Sir Robert? Agora que ambos temos os mesmos interesses a peito, seremos grandes amigos, espero!","sailsoutonsirrobertchilternsarmladychilt~intoanotherreceptionroom~208":"Sai majestosamente de braço dado com Sir Robert Chiltern. Lady Chiltern vai até o alto da escadaria e os observa descerem. Sua expressão é perturbada. Passado algum tempo, alguns convidados juntam-se a ela, e passa com eles a outro salão de recepção.","mabelchilternwhatahorridwoman~chilternwhatahorridwoman~29":"Mabel Chiltern — Que mulher horrível!","lordgoringyoushouldgotobedmissmabel~oushouldgotobedmissmabel~35":"Lord Goring — A senhorita devia ir para a cama, Srta. Mabel.","mabelchilternlordgoring~mabelchilternlordgoring~23":"Mabel Chiltern — Lord Goring!","lordgoringmyfathertoldmetogotobedanhoura~isneverofanyusetooneself~157":"Lord Goring — Meu pai mandou-me para a cama há uma hora. Não vejo por que não lhe daria o mesmo conselho. Eu sempre transmito os bons conselhos. É a única coisa que se pode fazer com eles. Nunca têm utilidade para nós mesmos.","mabelchilternlordgoringyouarealwaysorder~erwhomthebroochbelongsto~573":"Mabel Chiltern — Lord Goring, o senhor está sempre me mandando sair da sala. Acho de sua parte muito corajoso. Principalmente porque não vou para a cama nas próximas horas. Vai até o sofá. Pode vir sentar-se, se quiser, e conversar sobre qualquer assunto do mundo, exceto a Royal Academy, a Sra. Cheveley ou romances em dialeto escocês. Não são assuntos edificantes. Avista algo que jaz no sofá, meio escondido pela almofada. O que é isto? Alguém deixou cair um broche de diamantes! Lindíssimo, não é? Mostra-o a ele. Queria que fosse meu, mas Gertrude só me deixa usar pérolas, e já estou absolutamente farta de pérolas. Fazem a gente parecer tão sem graça, tão boa e tão intelectual. Quem será o dono do broche?","lordgoringiwonderwhodroppedit~oringiwonderwhodroppedit~29":"Lord Goring — Eu me pergunto quem o deixou cair.","mabelchilternitisabeautifulbrooch~ternitisabeautifulbrooch~33":"Mabel Chiltern — É um broche lindo.","lordgoringitisahandsomebracelet~ingitisahandsomebracelet~31":"Lord Goring — É uma pulseira elegante.","mabelchilternitisntabraceletitsabrooch~tisntabraceletitsabrooch~38":"Mabel Chiltern — Não é uma pulseira. É um broche.","lordgoringitcanbeusedasabracelettakesitf~hthemostperfectsangfroid~171":"Lord Goring — Pode ser usado como pulseira. Toma-o dela e, tirando uma carteira verde, guarda cuidadosamente nela o ornamento e recoloca tudo no bolso do peito com o mais perfeito sangue-frio.","mabelchilternwhatareyoudoing~lchilternwhatareyoudoing~28":"Mabel Chiltern — O que está fazendo?","lordgoringmissmabeliamgoingtomakearather~atherstrangerequesttoyou~59":"Lord Goring — Srta. Mabel, vou lhe fazer um pedido bastante estranho.","mabelchilterneagerlyohpraydoihavebeenwai~aitingforitalltheevening~62":"Mabel Chiltern — Com ansiedade. Oh, por favor, faça! Estive esperando por isso a noite inteira.","lordgoringisalittletakenabackbutrecovers~ndclaimitletmeknowatonce~141":"Lord Goring — Fica um pouco desconcertado, mas se recompõe. Não mencione a ninguém que fiquei com este broche. Se alguém escrever reclamando-o, avise-me imediatamente.","mabelchilternthatisastrangerequest~ernthatisastrangerequest~34":"Mabel Chiltern — Que pedido estranho.","lordgoringwellyouseeigavethisbroochtosom~chtosomebodyonceyearsago~57":"Lord Goring — Bem, veja, eu dei este broche a alguém, anos atrás.","mabelchilternyoudid~mabelchilternyoudid~19":"Mabel Chiltern — Deu?","lordgoringyes~lordgoringyes~13":"Lord Goring — Sim.","ladychilternentersalonetheotherguestshav~netheotherguestshavegone~45":"Lady Chiltern entra sozinha. Os outros convidados já se foram.","mabelchilternthenishallcertainlybidyougo~ghtgoodnightgertrudeexit~68":"Mabel Chiltern — Então certamente lhe desejo boa noite. Boa noite, Gertrude! Sai.","ladychilterngoodnightdeartolordgoringyou~markbybroughtheretonight~75":"Lady Chiltern — Boa noite, querida! A Lord Goring. Viu quem Lady Markby trouxe aqui esta noite?","lordgoringyesitwasanunpleasantsurprisewh~isewhatdidshecomeherefor~59":"Lord Goring — Vi. Foi uma surpresa desagradável. Para que ela veio?","ladychilternapparentlytotryandlurerobert~dtheargentinecanalinfact~113":"Lady Chiltern — Aparentemente para tentar atrair Robert a apoiar algum projeto fraudulento em que ela tem interesse. O Canal Argentino, na verdade.","lordgoringshehasmistakenhermanhasntshe~asmistakenhermanhasntshe~38":"Lord Goring — Enganou-se de homem, não é?","ladychilternsheisincapableofunderstandin~ightnaturelikemyhusbands~70":"Lady Chiltern — Ela é incapaz de compreender uma natureza íntegra como a de meu marido!","lordgoringyesishouldfancyshecametogriefi~gmistakescleverwomenmake~126":"Lord Goring — Sim. Imagino que se daria mal se tentasse prender Robert em suas redes. É extraordinário os erros espantosos que as mulheres inteligentes cometem.","ladychilternidontcallwomenofthatkindclev~indclevericallthemstupid~57":"Lady Chiltern — Não chamo de inteligentes as mulheres desse tipo. Chamo-as de estúpidas!","lordgoringsamethingoftengoodnightladychi~tengoodnightladychiltern~45":"Lord Goring — Muitas vezes é a mesma coisa. Boa noite, Lady Chiltern!","ladychilterngoodnight~ladychilterngoodnight~21":"Lady Chiltern — Boa noite!","entersirrobertchiltern~entersirrobertchiltern~22":"Entra Sir Robert Chiltern.","sirrobertchilternmydeararthuryouarenotgo~arenotgoingdostopalittle~56":"Sir Robert Chiltern — Meu caro Arthur, você não vai embora? Fique mais um pouco!","lordgoringafraidicantthanksihavepromised~anmusicseeyousoongoodbye~145":"Lord Goring — Receio que não posso, obrigado. Prometi passar na casa dos Hartlock. Parece que têm uma orquestra húngara malva que toca música húngara malva. Até breve. Adeus!","exit~exit~4":"Sai.","sirrobertchilternhowbeautifulyoulooktoni~ulyoulooktonightgertrude~51":"Sir Robert Chiltern — Como você está linda esta noite, Gertrude!","ladychilternrobertitisnottrueisityouaren~inespeculationyoucouldnt~100":"Lady Chiltern — Robert, não é verdade, é? Você não vai dar o seu apoio a essa especulação argentina? Não poderia!","sirrobertchilternstartingwhotoldyouiinte~hotoldyouiintendedtodoso~50":"Sir Robert Chiltern — Sobressaltando-se. Quem lhe disse que eu pretendia fazê-lo?","ladychilternthatwomanwhohasjustgoneoutmr~ydoyouletherinfluenceyou~323":"Lady Chiltern — Aquela mulher que acaba de sair, a Sra. Cheveley, como agora se chama. Pareceu-me zombar de mim com isso. Robert, eu conheço essa mulher. Você não. Fomos colegas de colégio. Era mentirosa, desonesta, uma influência nociva sobre todos cuja confiança ou amizade conseguia conquistar. Eu a odiava, eu a desprezava. Ela roubava coisas, era uma ladra. Foi mandada embora por ser ladra. Por que você se deixa influenciar por ela?","sirrobertchilterngertrudewhatyoutellmema~ntirelyjudgedbytheirpast~161":"Sir Robert Chiltern — Gertrude, o que você me diz pode ser verdade, mas aconteceu há muitos anos. O melhor é esquecer! A Sra. Cheveley pode ter mudado desde então. Ninguém deve ser julgado inteiramente pelo seu passado.","ladychilternsadlyonespastiswhatoneisitis~hichpeopleshouldbejudged~77":"Lady Chiltern — Tristemente. O passado de cada um é o que cada um é. É a única maneira pela qual as pessoas deveriam ser julgadas.","sirrobertchilternthatisahardsayinggertru~hatisahardsayinggertrude~42":"Sir Robert Chiltern — Isso é uma sentença dura, Gertrude!","ladychilternitisatruesayingrobertandwhat~severbeeninpoliticallife~198":"Lady Chiltern — É uma sentença verdadeira, Robert. E o que quis ela dizer ao gabar-se de que conseguiu levá-lo a emprestar o seu apoio, o seu nome, a algo que ouvi você descrever como o projeto mais desonesto e fraudulento que já houve na vida política?","sirrobertchilternbitinghislipiwasmistake~tookweallmaymakemistakes~75":"Sir Robert Chiltern — Mordendo o lábio. Enganei-me na opinião que formei. Todos podemos cometer erros.","ladychilternbutyoutoldmeyesterdaythatyou~lycondemnedthewholething~116":"Lady Chiltern — Mas você me disse ontem que tinha recebido o relatório da Comissão, e que ele condenava inteiramente o negócio.","sirrobertchilternwalkingupanddownihavere~sandmoveondifferentlines~206":"Sir Robert Chiltern — Andando de um lado para outro. Tenho agora razões para crer que a Comissão era parcial ou, em todo caso, mal informada. Além disso, Gertrude, vida pública e vida privada são coisas diferentes. Têm leis diferentes e seguem rumos diferentes.","ladychilterntheyshouldbothrepresentmanat~enodifferencebetweenthem~77":"Lady Chiltern — Ambas deveriam representar o homem no que ele tem de mais elevado. Não vejo diferença entre elas.","sirrobertchilternstoppinginthepresentcas~vechangedmymindthatisall~96":"Sir Robert Chiltern — Detendo-se. No presente caso, numa questão de política prática, mudei de opinião. É só isso.","ladychilternall~ladychilternall~15":"Lady Chiltern — Só isso!","sirrobertchilternsternlyyes~robertchilternsternlyyes~27":"Sir Robert Chiltern — Severamente. Sim!","ladychilternrobertohitishorriblethatisho~outellingmethewholetruth~102":"Lady Chiltern — Robert! Oh! é horrível que eu tenha de lhe fazer tal pergunta... Robert, você está me dizendo toda a verdade?","sirrobertchilternwhydoyouaskmesuchaquest~ydoyouaskmesuchaquestion~43":"Sir Robert Chiltern — Por que me faz tal pergunta?","ladychilternafterapausewhydoyounotanswer~pausewhydoyounotanswerit~42":"Lady Chiltern — Após uma pausa. Por que não a responde?","sirrobertchilternsittingdowngertrudetrut~tocompromiseeveryonedoes~230":"Sir Robert Chiltern — Sentando-se. Gertrude, a verdade é uma coisa muito complexa, e a política é um negócio muito complexo. Há engrenagens dentro de engrenagens. Podemos ter certas obrigações para com certas pessoas, que precisamos pagar. Mais cedo ou mais tarde, na vida política, é preciso fazer concessões. Todos fazem.","ladychilterncompromiserobertwhydoyoutalk~dyoutalkwhyareyouchanged~109":"Lady Chiltern — Concessões? Robert, por que fala esta noite de modo tão diferente de como sempre o ouvi falar? Por que está mudado?","sirrobertchilterniamnotchangedbutcircums~circumstancesalterthings~57":"Sir Robert Chiltern — Não estou mudado. Mas as circunstâncias alteram as coisas.","ladychilterncircumstancesshouldneveralte~ouldneveralterprinciples~51":"Lady Chiltern — As circunstâncias nunca deveriam alterar princípios!","sirrobertchilternbutifitoldyou~ertchilternbutifitoldyou~30":"Sir Robert Chiltern — Mas se eu lhe dissesse...","ladychilternwhat~ladychilternwhat~16":"Lady Chiltern — O quê?","sirrobertchilternthatitwasnecessaryvital~ecessaryvitallynecessary~51":"Sir Robert Chiltern — Que era necessário, vitalmente necessário?","ladychilternitcanneverbenecessarytodowha~dothisdishonourablething~368":"Lady Chiltern — Nunca pode ser necessário fazer o que não é honroso. Ou, se for necessário, então o que foi que eu amei! Mas não é, Robert; diga-me que não é. Por que seria? Que ganho você teria? Dinheiro? Não precisamos disso! E dinheiro que vem de fonte manchada é uma degradação. Poder? Mas o poder nada é em si mesmo. O que é belo é o poder de fazer o bem... isso, e somente isso. O que é, então? Robert, diga-me por que vai fazer essa coisa desonrosa!","sirrobertchilterngertrudeyouhavenorightt~romiseitisnomorethanthat~112":"Sir Robert Chiltern — Gertrude, você não tem o direito de usar essa palavra. Eu lhe disse que era uma questão de concessão razoável. Não é mais do que isso.","ladychilternrobertthatisallverywellforot~myloveforyoudontkillthat~484":"Lady Chiltern — Robert, isso está muito bem para outros homens, para homens que tratam a vida simplesmente como uma sórdida especulação; mas não para você, Robert, não para você. Você é diferente. Toda a sua vida você se manteve à parte dos outros. Nunca deixou que o mundo o sujasse. Para o mundo, como para mim, você sempre foi um ideal. Oh! continue a ser esse ideal. Essa grande herança não a desperdice... essa torre de marfim não a destrua. Robert, os homens podem amar o que lhes é inferior... coisas indignas, manchadas, desonradas. Nós, mulheres, adoramos quando amamos; e quando perdemos a nossa adoração, perdemos tudo. Oh! não mate o meu amor por você, não mate isso!","sirrobertchilterngertrude~irrobertchilterngertrude~25":"Sir Robert Chiltern — Gertrude!","ladychilterniknowthattherearemenwithhorr~cetellmetellmeatoncethat~264":"Lady Chiltern — Sei que há homens com segredos horríveis em suas vidas... homens que fizeram alguma coisa vergonhosa e que, em algum momento crítico, têm de pagar por isso cometendo outro ato de vergonha... oh! não me diga que você é como eles! Robert, há em sua vida alguma desonra ou desgraça secreta? Diga-me, diga-me já, que...","sirrobertchilternthatwhat~irrobertchilternthatwhat~25":"Sir Robert Chiltern — Que o quê?","ladychilternspeakingveryslowlythatourliv~hatourlivesmaydriftapart~55":"Lady Chiltern — Falando muito devagar. Que as nossas vidas podem separar-se à deriva.","sirrobertchilterndriftapart~robertchilterndriftapart~27":"Sir Robert Chiltern — Separar-se à deriva?","ladychilternthattheymaybeentirelyseparat~itwouldbebetterforusboth~65":"Lady Chiltern — Que podem ser inteiramente separadas. Seria melhor para ambos.","sirrobertchilterngertrudethereisnothingi~tlifethatyoumightnotknow~70":"Sir Robert Chiltern — Gertrude, não há nada em minha vida passada que você não possa saber.","ladychilterniwassureofitrobertiwassureof~umusttakeitbackthatisall~280":"Lady Chiltern — Eu tinha certeza, Robert, tinha certeza. Mas por que disse aquelas coisas terríveis, tão diferentes do seu verdadeiro eu? Nunca mais falemos sobre o assunto. Você vai escrever, não vai, à Sra. Cheveley, dizendo-lhe que não pode apoiar esse projeto escandaloso dela? Se lhe deu alguma promessa, tem de retirá-la, só isso!","sirrobertchilternmustiwriteandtellhertha~mustiwriteandtellherthat~41":"Sir Robert Chiltern — Preciso escrever e dizer-lhe isso?","ladychilternsurelyrobertwhatelseistheret~obertwhatelseistheretodo~43":"Lady Chiltern — Certamente, Robert! O que mais há a fazer?","sirrobertchilternimightseeherpersonallyi~ersonallyitwouldbebetter~54":"Sir Robert Chiltern — Eu poderia vê-la pessoalmente. Seria melhor.","ladychilternyoumustneverseeheragainrober~cisionisquiteirrevocable~203":"Lady Chiltern — Você nunca mais deve vê-la, Robert. Não é uma mulher com quem você deva jamais falar. Não é digna de conversar com um homem como você. Não; você deve escrever-lhe já, agora, neste instante, e sua carta deve mostrar-lhe que a sua decisão é absolutamente irrevogável!","sirrobertchilternwritethismoment~tchilternwritethismoment~32":"Sir Robert Chiltern — Escrever neste instante!","ladychilternyes~ladychilternyes~15":"Lady Chiltern — Sim.","sirrobertchilternbutitissolateitiscloseo~ssolateitiscloseontwelve~47":"Sir Robert Chiltern — Mas é tão tarde. Está perto da meia-noite.","ladychilternthatmakesnomattershemustknow~andforthatiloveyourobert~896":"Lady Chiltern — Não importa. Ela deve saber imediatamente que se enganou a seu respeito... e que você não é homem de fazer nada vil, dissimulado ou desonroso. Escreva aqui, Robert. Escreva que você se recusa a apoiar esse projeto dela, por considerá-lo um projeto desonesto. Sim... escreva a palavra desonesto. Ela sabe o que essa palavra significa. Sir Robert Chiltern senta-se e escreve uma carta. A esposa a toma e a lê. Sim; assim está bem. Toca a campainha. E agora o envelope. Ele escreve o envelope lentamente. Entra Mason. Mande esta carta imediatamente ao Hotel Claridge’s. Não há resposta. Sai Mason. Lady Chiltern ajoelha-se ao lado do marido e o abraça. Robert, o amor dá à gente um instinto para as coisas. Sinto esta noite que o salvei de algo que poderia ter sido um perigo para você, de algo que poderia ter feito os homens honrá-lo menos do que o honram. Não creio que você perceba o bastante, Robert, que trouxe à vida política do nosso tempo uma atmosfera mais nobre, uma atitude mais fina diante da vida, um ar mais livre de propósitos mais puros e ideais mais elevados... eu sei disso, e por isso o amo, Robert.","sirrobertchilternohlovemealwaysgertrudel~waysgertrudelovemealways~51":"Sir Robert Chiltern — Oh, ame-me sempre, Gertrude, ame-me sempre!","ladychilterniwillloveyoualwaysbecauseyou~seshimandrisesandgoesout~127":"Lady Chiltern — Amarei você sempre, porque você será sempre digno de amor. Temos de amar o que há de mais alto quando o vemos! Beija-o, levanta-se e sai.","sirrobertchilternwalksupanddownforamomen~sirrobertchilternlooksup~147":"Sir Robert Chiltern anda de um lado para outro por um momento; depois senta-se e enterra o rosto nas mãos. O criado entra e começa a apagar as luzes. Sir Robert Chiltern ergue os olhos.","sirrobertchilternputoutthelightsmasonput~ghtsmasonputoutthelights~52":"Sir Robert Chiltern — Apague as luzes, Mason, apague as luzes!","theservantputsoutthelightstheroombecomes~pestryofthetriumphoflove~162":"O criado apaga as luzes. A sala fica quase às escuras. A única luz vem do grande lustre que pende sobre a escadaria e ilumina a tapeçaria do Triunfo do Amor.","morningroomatsirrobertchilternshouse~tsirrobertchilternshouse~36":"Sala matinal na casa de Sir Robert Chiltern.","lordgoringdressedintheheightoffashionisl~ervouslyupanddowntheroom~214":"Lord Goring, vestido na última moda, está refestelado numa poltrona. Sir Robert Chiltern está de pé diante da lareira. Encontra-se evidentemente num estado de grande agitação e aflição mental. À medida que a cena avança, caminha nervosamente de um lado para outro da sala.","lordgoringmydearrobertitsaveryawkwardbus~erythingexcepttheobvious~367":"Lord Goring — Meu caro Robert, é um negócio muito embaraçoso, embaraçoso de fato. Você devia ter contado tudo à sua esposa. Segredos diante das esposas alheias são um luxo necessário na vida moderna. Pelo menos é o que me dizem sempre no clube pessoas calvas o bastante para saberem melhor. Mas nenhum homem deve ter um segredo diante da própria esposa. Ela invariavelmente descobre. As mulheres têm um instinto maravilhoso para as coisas. Descobrem tudo, exceto o óbvio.","sirrobertchilternarthuricouldnttellmywif~rorinhorrorandincontempt~307":"Sir Robert Chiltern — Arthur, eu não podia contar à minha esposa. Quando poderia ter contado? Ontem à noite não. Teria feito uma separação para toda a vida entre nós, e eu teria perdido o amor da única mulher do mundo que venero, da única mulher que já despertou amor em mim. Ontem à noite teria sido de todo impossível. Ela teria se afastado de mim com horror … com horror e com desprezo.","lordgoringisladychilternasperfectasallth~ilternasperfectasallthat~42":"Lord Goring — Lady Chiltern é perfeita a esse ponto?","sirrobertchilternyesmywifeisasperfectasa~wifeisasperfectasallthat~46":"Sir Robert Chiltern — Sim; minha esposa é perfeita a esse ponto.","lordgoringtakingoffhislefthandglovewhata~boutlifewithladychiltern~167":"Lord Goring — Tirando a luva da mão esquerda. Que pena! Perdão, meu caro, não quis dizer exatamente isso. Mas, se o que me conta é verdade, gostaria de ter uma conversa séria sobre a vida com Lady Chiltern.","sirrobertchilternitwouldbequiteuseless~ernitwouldbequiteuseless~38":"Sir Robert Chiltern — Seria inteiramente inútil.","lordgoringmayitry~lordgoringmayitry~17":"Lord Goring — Posso tentar?","sirrobertchilternyesbutnothingcouldmakeh~ouldmakeheralterherviews~55":"Sir Robert Chiltern — Pode; mas nada a faria alterar suas opiniões.","lordgoringwellattheworstitwouldsimplybea~apsychologicalexperiment~63":"Lord Goring — Bem, na pior das hipóteses seria apenas uma experiência psicológica.","sirrobertchilternallsuchexperimentsarete~entsareterriblydangerous~55":"Sir Robert Chiltern — Todas essas experiências são terrivelmente perigosas.","lordgoringeverythingisdangerousmydearfel~houldhavetoldheryearsago~133":"Lord Goring — Tudo é perigoso, meu caro. Se não fosse assim, a vida não valeria a pena ser vivida. … Bem, devo dizer que acho que você deveria ter contado a ela anos atrás.","sirrobertchilternwhenwhenwewereengageddo~shamefulanddishonourable~219":"Sir Robert Chiltern — Quando? Quando ficamos noivos? Acha que ela teria se casado comigo se soubesse que a origem de minha fortuna é o que é, que a base de minha carreira é o que é, e que eu havia feito uma coisa que suponho que a maioria dos homens chamaria de vergonhosa e desonrosa?","lordgoringslowlyyesmostmenwouldcallitugl~amesthereisnodoubtofthat~66":"Lord Goring — Lentamente. Sim; a maioria dos homens lhe daria nomes feios. Disso não há dúvida.","sirrobertchilternbitterlymenwhoeverydayd~sesecretsintheirownlives~123":"Sir Robert Chiltern — Com amargura. Homens que todos os dias fazem eles mesmos algo do mesmo gênero. Homens que, cada um deles, têm segredos piores em suas próprias vidas.","lordgoringthatisthereasontheyaresoplease~licattentionfromtheirown~107":"Lord Goring — É por isso que ficam tão satisfeitos em descobrir os segredos alheios. Desvia a atenção pública dos seus próprios.","sirrobertchilternandafterallwhomdidiwron~didiwrongbywhatididnoone~56":"Sir Robert Chiltern — E, afinal, a quem prejudiquei com o que fiz? A ninguém.","lordgoringlookingathimsteadilyexceptyour~dilyexceptyourselfrobert~50":"Lord Goring — Olhando-o fixamente. A não ser a si mesmo, Robert.","sirrobertchilternafterapauseofcourseihad~feverylargemodernfortune~195":"Sir Robert Chiltern — Após uma pausa. É claro que eu possuía informação privada sobre certa transação planejada pelo governo da época, e agi com base nela. A informação privada é praticamente a fonte de toda grande fortuna moderna.","lordgoringtappinghisbootwithhiscaneandpu~andalinvariablytheresult~70":"Lord Goring — Batendo na bota com a bengala. E o escândalo público, invariavelmente, o resultado.","sirrobertchilternpacingupanddowntherooma~avebuiltupisitfairarthur~476":"Sir Robert Chiltern — Andando de um lado para outro da sala. Arthur, acha que o que fiz há quase dezoito anos deve ser trazido contra mim agora? Acha justo que toda a carreira de um homem seja arruinada por uma falta cometida quase na meninice? Eu tinha vinte e dois anos na época e tinha a dupla infelicidade de ser bem-nascido e pobre, duas coisas imperdoáveis nos dias de hoje. É justo que a loucura, o pecado da juventude, se os homens quiserem chamá-lo de pecado, destrua uma vida como a minha, me ponha no pelourinho, despedace tudo por que trabalhei, tudo que construí? É justo, Arthur?","lordgoringlifeisneverfairrobertandperhap~ngformostofusthatitisnot~77":"Lord Goring — A vida nunca é justa, Robert. E talvez seja bom para a maioria de nós que não seja.","sirrobertchilterneverymanofambitionhasto~llcostsonemusthavewealth~183":"Sir Robert Chiltern — Todo homem de ambição tem de combater o seu século com as armas do próprio século. O que este século adora é a riqueza. O Deus deste século é a riqueza. Para vencer, é preciso ter riqueza. A qualquer preço, é preciso ter riqueza.","lordgoringyouunderrateyourselfrobertbeli~dhavesucceededjustaswell~89":"Lord Goring — Você se subestima, Robert. Acredite, sem riqueza você teria tido o mesmo sucesso.","sirrobertchilternwheniwasoldperhapswheni~meforsuccessicouldntwait~176":"Sir Robert Chiltern — Quando fosse velho, talvez. Quando eu tivesse perdido a paixão pelo poder, ou não pudesse usá-lo. Quando estivesse cansado, gasto, desiludido. Eu queria o meu sucesso quando era jovem. A juventude é o tempo do sucesso. Eu não podia esperar.","lordgoringwellyoucertainlyhavehadyoursuc~ughforanyoneishouldthink~187":"Lord Goring — Bem, você certamente teve o seu sucesso ainda jovem. Ninguém em nossos dias teve sucesso tão brilhante. Subsecretário de Negócios Estrangeiros aos quarenta anos... isso é bom o bastante para qualquer um, creio eu.","sirrobertchilternandifitisalltakenawayfr~iamhoundedfrompubliclife~110":"Sir Robert Chiltern — E se tudo isso me for tirado agora? Se eu perder tudo por causa de um escândalo horrível? Se for expulso da vida pública?","lordgoringroberthowcouldyouhavesoldyours~havesoldyourselfformoney~51":"Lord Goring — Robert, como você pôde vender-se por dinheiro?","sirrobertchilternexcitedlyididnotsellmys~ssatagreatpricethatisall~87":"Sir Robert Chiltern — Exaltado. Eu não me vendi por dinheiro. Comprei o sucesso a um grande preço. Só isso.","lordgoringgravelyyesyoucertainlypaidagre~outhinkofdoingsuchathing~93":"Lord Goring — Gravemente. Sim; você certamente pagou um grande preço por ele. Mas o que primeiro lhe fez pensar em tal coisa?","sirrobertchilternbaronarnheim~bertchilternbaronarnheim~29":"Sir Robert Chiltern — O barão Arnheim.","lordgoringdamnedscoundrel~ordgoringdamnedscoundrel~25":"Lord Goring — Maldito canalha!","sirrobertchilternnohewasamanofamostsubtl~tintellectualmenievermet~127":"Sir Robert Chiltern — Não; era um homem de intelecto sutilíssimo e refinado. Um homem de cultura, de encanto e de distinção. Um dos homens mais intelectuais que já conheci.","lordgoringahipreferagentlemanlyfoolanyda~edoittellmethewholething~198":"Lord Goring — Ah! Prefiro um tolo cavalheiresco em qualquer ocasião. Há mais a dizer em favor da estupidez do que as pessoas imaginam. Pessoalmente, tenho grande admiração pela estupidez. É uma espécie de solidariedade, suponho. Mas como ele fez? Conte-me tudo.","sirrobertchilternthrowshimselfintoanarmc~ryonlytherichpossessedit~951":"Sir Robert Chiltern — Atira-se numa poltrona junto à escrivaninha. Certa noite, depois de um jantar na casa de Lord Radley, o barão começou a falar do sucesso na vida moderna como algo que se poderia reduzir a uma ciência absolutamente definida. Com aquela sua voz tranquila e maravilhosamente fascinante, expôs-nos a mais terrível de todas as filosofias, a filosofia do poder, pregou-nos o mais maravilhoso de todos os evangelhos, o evangelho do ouro. Creio que viu o efeito que havia produzido em mim, pois alguns dias depois escreveu-me pedindo que o visitasse. Morava então em Park Lane, na casa que agora pertence a Lord Woolcomb. Lembro-me tão bem de como, com um estranho sorriso nos lábios pálidos e curvos, ele me conduziu pela sua maravilhosa galeria de quadros, mostrou-me suas tapeçarias, seus esmaltes, suas joias, seus marfins esculpidos, fez-me pasmar com a estranha beleza do luxo em que vivia; e depois me disse que o luxo nada era senão um cenário, uma cena pintada numa peça, e que o poder, o poder sobre os outros homens, o poder sobre o mundo, era a única coisa que valia a pena ter, o único prazer supremo que valia a pena conhecer, a única alegria da qual nunca nos cansamos, e que em nosso século só os ricos o possuíam.","lordgoringwithgreatdeliberationathorough~nathoroughlyshallowcreed~54":"Lord Goring — Com grande ponderação. Um credo inteiramente superficial.","sirrobertchilternrisingididntthinksothen~mesuchachanceasfewmenget~266":"Sir Robert Chiltern — Levantando-se. Eu não pensava assim então. Não penso assim agora. A riqueza deu-me enorme poder. Deu-me, no começo mesmo de minha vida, liberdade, e liberdade é tudo. Você nunca foi pobre e nunca soube o que é ambição. Não pode compreender que oportunidade maravilhosa o barão me deu. Uma oportunidade como poucos homens têm.","lordgoringfortunatelyforthemifoneistojud~eyoutowelltodowhatyoudid~122":"Lord Goring — Felizmente para eles, a julgar pelos resultados. Mas diga-me com precisão: como o barão acabou por persuadi-lo a... bem, a fazer o que fez?","sirrobertchilternwheniwasgoingawayhesaid~entspassedthroughmyhands~270":"Sir Robert Chiltern — Quando eu ia embora, ele me disse que, se algum dia eu pudesse lhe dar alguma informação privada de real valor, ele me faria um homem muito rico. Fiquei aturdido com a perspectiva que me abria, e minha ambição e meu desejo de poder eram então ilimitados. Seis semanas depois, certos documentos privados passaram por minhas mãos.","lordgoringkeepinghiseyessteadilyfixedont~nthecarpetstatedocuments~62":"Lord Goring — Mantendo os olhos fixos no tapete. Documentos de Estado?","sirrobertchilternyeslordgoringsighsthenp~osshisforeheadandlooksup~79":"Sir Robert Chiltern — Sim. Lord Goring suspira, depois passa a mão pela testa e ergue os olhos.","lordgoringihadnoideathatyouofallmeninthe~baronarnheimheldouttoyou~122":"Lord Goring — Eu não fazia ideia de que você, entre todos os homens do mundo, pudesse ter sido tão fraco, Robert, a ponto de ceder a uma tentação como a que o barão Arnheim lhe ofereceu.","sirrobertchilternweakohiamsickofhearingt~illionoverthetransaction~511":"Sir Robert Chiltern — Fraco? Oh, estou farto de ouvir essa expressão. Farto de usá-la a respeito dos outros. Fraco? Acha realmente, Arthur, que é fraqueza ceder à tentação? Digo-lhe que há tentações terríveis às quais é preciso força, força e coragem, para ceder. Apostar toda a vida num único momento, arriscar tudo num só lance, seja a aposta poder ou prazer, pouco me importa... nisso não há fraqueza. Há uma coragem horrível, terrível. Eu tive essa coragem. Sentei-me naquela mesma tarde e escrevi ao barão Arnheim a carta que esta mulher agora possui. Ele ganhou três quartos de milhão com a transação.","lordgoringandyou~lordgoringandyou~16":"Lord Goring — E você?","sirrobertchilternireceivedfromthebaron11~ceivedfromthebaron110000~44":"Sir Robert Chiltern — Recebi do barão £110.000.","lordgoringyouwereworthmorerobert~ngyouwereworthmorerobert~32":"Lord Goring — Você valia mais, Robert.","sirrobertchilternnothatmoneygavemeexactl~shustheyanswerourprayers~418":"Sir Robert Chiltern — Não; esse dinheiro me deu exatamente o que eu queria, poder sobre os outros. Entrei para a Câmara imediatamente. O barão me aconselhava em finanças de tempos em tempos. Antes de cinco anos eu quase triplicara a minha fortuna. Desde então, tudo em que toquei foi um sucesso. Em todas as coisas ligadas a dinheiro tive uma sorte tão extraordinária que às vezes me deixou quase com medo. Lembro-me de ter lido em algum lugar, em algum livro estranho, que quando os deuses querem nos punir, atendem às nossas preces.","lordgoringbuttellmerobertdidyouneversuff~yregretforwhatyouhaddone~68":"Lord Goring — Mas diga-me, Robert, nunca sentiu qualquer arrependimento pelo que havia feito?","sirrobertchilternnoifeltthatihadfoughtth~ywithitsownweaponsandwon~71":"Sir Robert Chiltern — Não. Senti que havia combatido o século com as suas próprias armas, e vencido.","lordgoringsadlyyouthoughtyouhadwon~sadlyyouthoughtyouhadwon~34":"Lord Goring — Tristemente. Pensou que tinha vencido.","sirrobertchilternithoughtsoafteralongpau~isemeforwhatihavetoldyou~81":"Sir Robert Chiltern — Pensei. Após uma longa pausa. Arthur, você me despreza pelo que lhe contei?","lordgoringwithdeepfeelinginhisvoiceiamve~yourobertverysorryindeed~74":"Lord Goring — Com profunda emoção na voz. Tenho muita pena de você, Robert, muitíssima pena.","sirrobertchilternidontsaythatisufferedan~publiccharitiessincethen~249":"Sir Robert Chiltern — Não digo que tenha sofrido algum remorso. Não sofri. Remorso no sentido comum e algo tolo da palavra, não. Mas paguei dinheiro de consciência muitas vezes. Tinha uma esperança louca de poder desarmar o destino. A soma que o barão Arnheim me deu, distribuí-a duas vezes em obras de caridade públicas desde então.","lordgoringlookingupinpubliccharitiesdear~armyoumusthavedonerobert~77":"Lord Goring — Erguendo os olhos. Em obras de caridade públicas? Santo Deus! Quanto mal você deve ter feito, Robert!","sirrobertchilternohdontsaythatarthurdont~atarthurdonttalklikethat~52":"Sir Robert Chiltern — Oh, não diga isso, Arthur; não fale assim!","lordgoringnevermindwhatisayrobertiamalwa~yicanofcourseyouknowthat~230":"Lord Goring — Não ligue para o que digo, Robert! Estou sempre dizendo o que não devia dizer. Na verdade, geralmente digo o que realmente penso. Um grande erro nos dias de hoje. Torna a gente tão sujeito a ser mal compreendido. Quanto a este negócio terrível, vou ajudá-lo da maneira que puder. É claro que você sabe disso.","sirrobertchilternthankyouarthurthankyoub~tistobedonewhatcanbedone~69":"Sir Robert Chiltern — Obrigado, Arthur, obrigado. Mas o que fazer? O que se pode fazer?","lordgoringleaningbackwithhishandsinhispo~dbeofnouseitwouldruinyou~566":"Lord Goring — Recostando-se com as mãos nos bolsos. Bem, os ingleses não suportam um homem que está sempre dizendo que tem razão, mas gostam muito de um homem que admite ter estado errado. É uma das melhores coisas neles. Contudo, no seu caso, Robert, uma confissão não serviria. O dinheiro, se me permite dizê-lo, é... embaraçoso. Além disso, se fizesse uma confissão completa de todo o caso, você nunca mais poderia falar de moral. E na Inglaterra um homem que não pode falar de moral duas vezes por semana a um público numeroso, popular e imoral está acabado como político sério. Nada lhe restaria como profissão senão a Botânica ou a Igreja. Uma confissão não teria utilidade. Arruinaria você.","sirrobertchilternitwouldruinmearthurtheo~onowistofightthethingout~80":"Sir Robert Chiltern — Arruinaria. Arthur, a única coisa que me resta fazer agora é lutar até o fim.","lordgoringrisingfromhischairiwaswaitingf~ingyourwifethewholestory~128":"Lord Goring — Levantando-se da cadeira. Eu esperava que dissesse isso, Robert. É a única coisa a fazer agora. E você deve começar contando toda a história à sua esposa.","sirrobertchilternthatiwillnotdo~rtchilternthatiwillnotdo~31":"Sir Robert Chiltern — Isso não farei.","lordgoringrobertbelievemeyouarewrong~bertbelievemeyouarewrong~36":"Lord Goring — Robert, acredite, você está errado.","sirrobertchilternicouldntdoititwouldkill~erbeforearthurapparently~148":"Sir Robert Chiltern — Eu não conseguiria. Mataria o amor dela por mim. E agora, quanto a esta mulher, esta Sra. Cheveley. Como posso me defender dela? Você a conhecia antes, Arthur, pelo visto.","sirrobertchilterndidyouknowherwell~hilterndidyouknowherwell~34":"Sir Robert Chiltern — Conhecia-a bem?","lordgoringarranginghisnecktiesolittletha~lastedforthreedaysnearly~131":"Lord Goring — Ajeitando a gravata. Tão pouco que fiquei noivo dela uma vez, quando estava hospedado em casa dos Tenby. O caso durou três dias … quase.","sirrobertchilternwhywasitbrokenoff~hilternwhywasitbrokenoff~34":"Sir Robert Chiltern — Por que foi rompido?","lordgoringairilyohiforgetatleastitmakesn~econfoundedlyfondofmoney~113":"Lord Goring — Com leveza. Oh, esqueci. Pelo menos, não importa. A propósito, você já tentou dinheiro com ela? Era terrivelmente apegada a dinheiro.","sirrobertchilterniofferedheranysumshewan~nysumshewantedsherefused~53":"Sir Robert Chiltern — Ofereci-lhe qualquer soma que quisesse. Ela recusou.","lordgoringthenthemarvellousgospelofgoldb~cantdoeverythingafterall~89":"Lord Goring — Então o maravilhoso evangelho do ouro às vezes falha. Os ricos não podem tudo, afinal.","sirrobertchilternnoteverythingisupposeyo~todeathinsomeemptyhollow~244":"Sir Robert Chiltern — Tudo não. Suponho que tem razão. Arthur, sinto que a desgraça pública me aguarda. Tenho certeza disso. Nunca soube o que era o terror antes. Sei agora. É como se uma mão de gelo fosse pousada no coração da gente. É como se o coração batesse até a morte em algum oco vazio.","lordgoringstrikingthetablerobertyoumustf~tfightheryoumustfighther~62":"Lord Goring — Batendo na mesa. Robert, você deve combatê-la. Deve combatê-la.","sirrobertchilternbuthow~sirrobertchilternbuthow~23":"Sir Robert Chiltern — Mas como?","lordgoringicanttellyouhowatpresentihaven~ltsperhapsihaveidontknow~215":"Lord Goring — Não posso lhe dizer como por ora. Não tenho a menor ideia. Mas todo mundo tem algum ponto fraco. Há alguma falha em cada um de nós. Vai passeando até a lareira e se olha no espelho. Meu pai me diz que até eu tenho defeitos. Talvez tenha. Não sei.","sirrobertchilternindefendingmyselfagains~nyweaponicanfindhaveinot~93":"Sir Robert Chiltern — Ao me defender da Sra. Cheveley, tenho o direito de usar qualquer arma que encontrar, não tenho?","lordgoringstilllookingintheglassinyourpl~labletotakecareofherself~133":"Lord Goring — Ainda olhando-se no espelho. Em seu lugar, não creio que teria o menor escrúpulo em fazê-lo. Ela é perfeitamente capaz de cuidar de si mesma.","sirrobertchilternsitsdownatthetableandta~candalshemightbeafraidof~191":"Sir Robert Chiltern — Senta-se à mesa e toma uma pena na mão. Pois bem, enviarei um telegrama cifrado à Embaixada em Viena, para perguntar se há algo conhecido contra ela. Pode haver algum escândalo secreto de que ela tenha medo.","lordgoringsettlinghisbuttonholeohishould~managetohaveenoughofthem~276":"Lord Goring — Ajeitando a flor da lapela. Oh, imagino que a Sra. Cheveley seja uma dessas mulheres muito modernas do nosso tempo que acham um novo escândalo tão favorecedor quanto um novo chapéu, e exibem ambos no Parque todas as tardes às cinco e meia. Tenho certeza de que adora escândalos, e que a tristeza de sua vida no momento é não conseguir ter o bastante deles.","sirrobertchilternwritingwhydoyousaythat~rnwritingwhydoyousaythat~39":"Sir Robert Chiltern — Escrevendo. Por que diz isso?","lordgoringturningroundwellsheworefartoom~ysasignofdespairinawoman~115":"Lord Goring — Virando-se. Bem, ela usava ruge demais ontem à noite, e roupa de menos. É sempre sinal de desespero numa mulher.","sirrobertchilternstrikingabellbutitiswor~emywiringtoviennaisitnot~70":"Sir Robert Chiltern — Tocando uma campainha. Mas vale a pena telegrafar a Viena, não vale?","lordgoringitisalwaysworthwhileaskingaque~ysworthwhileansweringone~86":"Lord Goring — Vale sempre a pena fazer uma pergunta, embora nem sempre valha a pena responder a uma.","entermason~entermason~10":"Entra Mason.","sirrobertchilternismrtraffordinhisroom~ernismrtraffordinhisroom~38":"Sir Robert Chiltern — O Sr. Trafford está em seu quarto?","masonyessirrobert~masonyessirrobert~17":"Mason — Sim, Sir Robert.","sirrobertchilternputswhathehaswrittenint~remustnotbeamomentsdelay~142":"Sir Robert Chiltern — Coloca o que escreveu num envelope, que fecha cuidadosamente. Diga-lhe que mande isto em cifra imediatamente. Não pode haver um instante de atraso.","sirrobertchilternohjustgivethatbacktomea~ustgivethatbacktomeagain~44":"Sir Robert Chiltern — Oh! devolva-me isso um instante.","writessomethingontheenvelopemasonthengoe~thengoesoutwiththeletter~57":"Escreve algo no envelope. Mason sai então com a carta.","sirrobertchilternshemusthavehadsomecurio~narnheimiwonderwhatitwas~78":"Sir Robert Chiltern — Ela deve ter tido alguma curiosa influência sobre o barão Arnheim. Pergunto-me qual era.","lordgoringsmilingiwonder~lordgoringsmilingiwonder~24":"Lord Goring — Sorrindo. Eu também me pergunto.","sirrobertchilterniwillfighthertothedeath~longasmywifeknowsnothing~66":"Sir Robert Chiltern — Vou combatê-la até a morte, desde que minha esposa nada saiba.","lordgoringstronglyohfightinanycaseinanyc~hfightinanycaseinanycase~43":"Lord Goring — Com veemência. Oh, lute de qualquer maneira... de qualquer maneira.","sirrobertchilternwithagestureofdespairif~awomanwithapastdoesntshe~288":"Sir Robert Chiltern — Com um gesto de desespero. Se minha esposa descobrisse, pouco restaria por que lutar. Bem, assim que eu tiver notícias de Viena, avisarei você do resultado. É uma chance, apenas uma chance, mas acredito nela. E como combati a época com as suas próprias armas, combaterei esta mulher com as dela. É apenas justo, e ela parece uma mulher com passado, não parece?","lordgoringmostprettywomendobutthereisafa~swonderfulpresenceofmind~362":"Lord Goring — A maioria das mulheres bonitas parece. Mas há moda para passados assim como há moda para vestidos. Talvez o passado da Sra. Cheveley seja apenas um passado ligeiramente decotado, e esses são excessivamente populares hoje em dia. Além disso, meu caro Robert, eu não depositaria esperanças demasiado altas em assustar a Sra. Cheveley. Não creio que seja uma mulher que se assuste facilmente. Sobreviveu a todos os seus credores e mostra uma maravilhosa presença de espírito.","sirrobertchilternohiliveonhopesnowiclutc~ormhushihearmywifesvoice~159":"Sir Robert Chiltern — Oh! Vivo de esperanças agora. Agarro-me a cada chance. Sinto-me como um homem num navio que afunda. A água já me banha os pés, e o próprio ar é amargo de tempestade. Silêncio! Ouço a voz de minha esposa.","enterladychilterninwalkingdress~dychilterninwalkingdress~31":"Entra Lady Chiltern em traje de passeio.","ladychilterngoodafternoonlordgoring~ngoodafternoonlordgoring~35":"Lady Chiltern — Boa tarde, Lord Goring!","lordgoringgoodafternoonladychilternhavey~ternhaveyoubeeninthepark~55":"Lord Goring — Boa tarde, Lady Chiltern! Esteve no Parque?","ladychilternnoihavejustcomefromthewomans~aitandhavesometeawontyou~184":"Lady Chiltern — Não; venho agora da Associação Liberal das Mulheres, onde, aliás, Robert, o seu nome foi recebido com fortes aplausos, e agora entrei para tomar o meu chá. A Lord Goring. O senhor vai esperar e tomar um pouco de chá, não vai?","lordgoringillwaitforashorttimethanks~lwaitforashorttimethanks~36":"Lord Goring — Esperarei um pouco, obrigado.","ladychilterniwillbebackinamomentiamonlyg~monlygoingtotakemyhatoff~58":"Lady Chiltern — Volto num instante. Só vou tirar o chapéu.","lordgoringinhismostearnestmannerohplease~ceiveditwithloudapplause~143":"Lord Goring — Em seu tom mais sério. Oh! por favor, não. É tão bonito. Um dos chapéus mais bonitos que já vi. Espero que a Associação Liberal das Mulheres o tenha recebido com fortes aplausos.","ladychilternwithasmilewehavemuchmoreimpo~hothersbonnetslordgoring~90":"Lady Chiltern — Com um sorriso. Temos trabalho muito mais importante a fazer do que olhar os chapéus umas das outras, Lord Goring.","lordgoringreallywhatsortofwork~ringreallywhatsortofwork~30":"Lord Goring — Verdade? Que espécie de trabalho?","ladychilternohdullusefuldelightfulthings~dthoroughlyuninteresting~164":"Lady Chiltern — Oh! coisas aborrecidas, úteis, deliciosas: as Leis das Fábricas, as Inspetoras, o Projeto das Oito Horas, o Direito de Voto Parlamentar. … Tudo, enfim, que o senhor acharia completamente desinteressante.","lordgoringandneverbonnets~ordgoringandneverbonnets~25":"Lord Goring — E nunca chapéus?","ladychilternwithmockindignationneverbonn~gnationneverbonnetsnever~48":"Lady Chiltern — Com fingida indignação. Nunca chapéus, nunca!","ladychilterngoesoutthroughthedoorleading~edoorleadingtoherboudoir~52":"Lady Chiltern sai pela porta que leva ao seu toucador.","sirrobertchilterntakeslordgoringshandyou~hurathoroughlygoodfriend~90":"Sir Robert Chiltern — Toma a mão de Lord Goring. Você tem sido um bom amigo para mim, Arthur, um amigo excelente.","lordgoringidontknowthatihavebeenabletodo~lydisappointedwithmyself~150":"Lord Goring — Não sei se consegui fazer muito por você, Robert, até agora. Na verdade, não consegui fazer nada por você, até onde vejo. Estou inteiramente desapontado comigo mesmo.","sirrobertchilternyouhaveenabledmetotelly~etruthhasalwaysstifledme~91":"Sir Robert Chiltern — Você me permitiu contar-lhe a verdade. Isso é alguma coisa. A verdade sempre me sufocou.","lordgoringahthetruthisathingigetridofass~eingconceitedperhapsitis~153":"Lord Goring — Ah! a verdade é coisa de que me livro o mais depressa possível! Mau hábito, aliás. Deixa a gente muito impopular no clube … entre os sócios mais velhos. Dizem que é presunção. Talvez seja.","sirrobertchilterniwouldtogodthatihadbeen~yousoonagainarthurshanti~169":"Sir Robert Chiltern — Queira Deus que eu tivesse podido dizer a verdade … viver a verdade. Ah! essa é a grande coisa na vida, viver a verdade. Suspira e vai em direção à porta. Vejo você em breve de novo, Arthur, não é?","lordgoringcertainlywheneveryoulikeimgoin~roundanotetocurzonstreet~197":"Lord Goring — Certamente. Quando quiser. Esta noite vou dar uma passada no Baile dos Solteiros, a não ser que encontre algo melhor para fazer. Mas amanhã de manhã passo por aqui. Se por acaso precisar de mim esta noite, mande um bilhete à Curzon Street.","sirrobertchilternthankyou~irrobertchilternthankyou~25":"Sir Robert Chiltern — Obrigado.","ashereachesthedoorladychilternentersfrom~ternentersfromherboudoir~50":"Quando ele chega à porta, Lady Chiltern entra vinda do toucador.","ladychilternyouarenotgoingrobert~ternyouarenotgoingrobert~32":"Lady Chiltern — Você não vai embora, Robert?","sirrobertchilternihavesomeletterstowrite~vesomeletterstowritedear~44":"Sir Robert Chiltern — Tenho algumas cartas a escrever, querida.","ladychilterngoingtohimyouworktoohardrobe~fandyouarelookingsotired~94":"Lady Chiltern — Indo até ele. Você trabalha demais, Robert. Parece nunca pensar em si mesmo, e está com um ar tão cansado.","sirrobertchilternitisnothingdearnothing~rnitisnothingdearnothing~39":"Sir Robert Chiltern — Não é nada, querida, nada.","hekissesherandgoesout~hekissesherandgoesout~21":"Ele a beija e sai.","ladychilterntolordgoringdositdowniamsogl~tnearlyenoughinthesecond~195":"Lady Chiltern — A Lord Goring. Sente-se, por favor. Fico tão contente que tenha vindo. Quero falar-lhe sobre … bem, não sobre chapéus, nem sobre a Associação Liberal das Mulheres. O senhor se interessa demais pelo primeiro assunto e muito pouco pelo segundo.","lordgoringyouwanttotalktomeaboutmrscheve~talktomeaboutmrscheveley~43":"Lord Goring — Quer falar comigo sobre a Sra. Cheveley?","ladychilternyesyouhaveguesseditafteryoul~ncewithdrawinghispromise~153":"Lady Chiltern — Sim. O senhor adivinhou. Depois que o senhor saiu ontem à noite, descobri que o que ela havia dito era realmente verdade. É claro que fiz Robert escrever-lhe uma carta imediatamente, retirando a promessa.","lordgoringsohegavemetounderstand~ngsohegavemetounderstand~32":"Lord Goring — Foi o que ele me deu a entender.","ladychilterntohavekeptitwouldhavebeenthe~dontthinkhehasanyfromyou~366":"Lady Chiltern — Mantê-la teria sido a primeira mancha numa carreira que sempre foi imaculada. Robert deve estar acima de qualquer censura. Ele não é como os outros homens. Não pode dar-se ao luxo de fazer o que os outros homens fazem. Olha para Lord Goring, que permanece em silêncio. Não concorda comigo? O senhor é o maior amigo de Robert. É o nosso maior amigo, Lord Goring. Ninguém, exceto eu, conhece Robert melhor do que o senhor. Ele não tem segredos para mim, e não creio que tenha algum para o senhor.","lordgoringhecertainlyhasnosecretsfrommea~rommeatleastidontthinkso~58":"Lord Goring — Certamente não tem segredos para mim. Pelo menos não creio.","ladychilternthenaminotrightinmyestimateo~rightbutspeaktomefrankly~76":"Lady Chiltern — Então não estou certa na minha avaliação dele? Sei que estou certa. Mas fale-me com franqueza.","lordgoringlookingstraightatherquitefrank~traightatherquitefrankly~42":"Lord Goring — Olhando-a diretamente. Com toda a franqueza?","ladychilternsurelyyouhavenothingtoconcea~enothingtoconcealhaveyou~48":"Lady Chiltern — Claro. O senhor não tem nada a ocultar, tem?","lordgoringnothingbutmydearladychilternit~saysothatinpracticallife~86":"Lord Goring — Nada. Mas, minha cara Lady Chiltern, penso, se me permite dizê-lo, que na vida prática...","ladychilternsmilingofwhichyouknowsolittl~ouknowsolittlelordgoring~51":"Lady Chiltern — Sorrindo. Da qual o senhor sabe tão pouco, Lord Goring...","lordgoringofwhichiknownothingbyexperienc~agifhehastowalkinthemire~322":"Lord Goring — Da qual nada sei por experiência, embora saiba algo por observação. Penso que na vida prática há algo no sucesso, no sucesso efetivo, que é um tanto inescrupuloso, algo na ambição que é sempre inescrupuloso. Uma vez que um homem pôs coração e alma em chegar a certo ponto, se tem de escalar o penhasco, escala o penhasco; se tem de andar na lama...","ladychilternwell~ladychilternwell~16":"Lady Chiltern — E então?","lordgoringhewalksinthemireofcourseiamonl~alkinggenerallyaboutlife~66":"Lord Goring — Anda na lama. Claro que falo apenas da vida em geral.","ladychilterngravelyihopesowhydoyoulookat~tmesostrangelylordgoring~63":"Lady Chiltern — Gravemente. Assim espero. Por que me olha de modo tão estranho, Lord Goring?","lordgoringladychilternihavesometimesthou~mefoolishlettertosomeone~313":"Lord Goring — Lady Chiltern, pensei às vezes que … talvez a senhora seja um tanto dura em algumas de suas opiniões sobre a vida. Penso que … muitas vezes não faz concessões suficientes. Em toda natureza há elementos de fraqueza, ou pior que fraqueza. Suponha, por exemplo, que... que algum homem público, meu pai, ou Lord Merton, ou Robert, digamos, tivesse, anos atrás, escrito alguma carta insensata a alguém …","ladychilternwhatdoyoumeanbyafoolishlette~oyoumeanbyafoolishletter~41":"Lady Chiltern — O que o senhor entende por carta insensata?","lordgoringalettergravelycompromisingones~lyputtinganimaginarycase~77":"Lord Goring — Uma carta que comprometa gravemente a posição de alguém. Estou apenas propondo um caso imaginário.","ladychilternrobertisasincapableofdoingaf~asheisofdoingawrongthing~75":"Lady Chiltern — Robert é tão incapaz de fazer uma coisa insensata quanto de fazer uma coisa errada.","lordgoringafteralongpausenobodyisincapab~apableofdoingawrongthing~97":"Lord Goring — Após uma longa pausa. Ninguém é incapaz de fazer uma coisa insensata. Ninguém é incapaz de fazer uma coisa errada.","ladychilternareyouapessimistwhatwilltheo~lallhavetogointomourning~85":"Lady Chiltern — O senhor é pessimista? O que dirão os outros dândis? Todos terão de entrar de luto.","lordgoringrisingnoladychilterniamnotapes~hallhaveitcomeatoncetome~439":"Lord Goring — Levantando-se. Não, Lady Chiltern, não sou pessimista. Na verdade, não tenho certeza de que sei bem o que o Pessimismo realmente significa. Tudo o que sei é que a vida não pode ser compreendida sem muita caridade, não pode ser vivida sem muita caridade. É o amor, e não a filosofia alemã, a verdadeira explicação deste mundo, seja qual for a explicação do próximo. E se algum dia a senhora estiver em apuros, Lady Chiltern, confie em mim absolutamente, e eu a ajudarei de todas as maneiras que puder. Se algum dia precisar de mim, venha a mim pedir auxílio, e o terá. Venha imediatamente a mim.","ladychilternlookingathiminsurpriselordgo~rdyoutalkseriouslybefore~113":"Lady Chiltern — Olhando-o com surpresa. Lord Goring, o senhor está falando bem a sério. Não creio que já o tenha ouvido falar a sério antes.","lordgoringlaughingyoumustexcusemeladychi~ntoccuragainificanhelpit~73":"Lord Goring — Rindo. A senhora há de me desculpar, Lady Chiltern. Não tornará a ocorrer, se eu puder evitar.","ladychilternbutilikeyoutobeserious~rnbutilikeyoutobeserious~34":"Lady Chiltern — Mas eu gosto de vê-lo sério.","entermabelchilterninthemostravishingfroc~ninthemostravishingfrock~41":"Entra Mabel Chiltern, no mais arrebatador vestido.","mabelchilterndeargertrudedontsaysuchadre~gpraybeastrivialasyoucan~145":"Mabel Chiltern — Querida Gertrude, não diga uma coisa tão terrível a Lord Goring. A seriedade lhe cairia muito mal. Boa tarde, Lord Goring! Por favor, seja o mais fútil que puder.","lordgoringishouldliketomissmabelbutiamaf~besidesihavetobegoingnow~105":"Lord Goring — Eu gostaria, Srta. Mabel, mas receio estar … um pouco destreinado esta manhã; e, além disso, tenho de ir embora agora.","mabelchilternjustwhenihavecomeinwhatdrea~ouwereverybadlybroughtup~90":"Mabel Chiltern — Justo quando acabo de entrar! Que modos horríveis o senhor tem! Tenho certeza de que foi muito mal educado.","lordgoringiwas~lordgoringiwas~14":"Lord Goring — Fui.","mabelchilterniwishihadbroughtyouup~erniwishihadbroughtyouup~34":"Mabel Chiltern — Quem me dera ter sido eu a educá-lo!","lordgoringiamsosorryyoudidnt~goringiamsosorryyoudidnt~28":"Lord Goring — Sinto tanto que não tenha sido.","mabelchilternitistoolatenowisuppose~rnitistoolatenowisuppose~35":"Mabel Chiltern — Agora é tarde demais, suponho?","lordgoringsmilingiamnotsosure~oringsmilingiamnotsosure~29":"Lord Goring — Sorrindo. Não tenho tanta certeza.","mabelchilternwillyouridetomorrowmorning~llyouridetomorrowmorning~39":"Mabel Chiltern — Vai cavalgar amanhã de manhã?","lordgoringyesatten~lordgoringyesatten~18":"Lord Goring — Vou, às dez.","mabelchilterndontforget~mabelchilterndontforget~23":"Mabel Chiltern — Não se esqueça.","lordgoringofcourseishantbythewayladychil~icularreasonforaskingyou~241":"Lord Goring — Claro que não. A propósito, Lady Chiltern, não há lista dos seus convidados no The Morning Post de hoje. Aparentemente foi expulsa pelo Conselho do Condado, ou pela Conferência de Lambeth, ou algo igualmente maçante. Poderia me dar uma lista? Tenho uma razão particular para pedir.","ladychilterniamsuremrtraffordwillbeablet~rdwillbeabletogiveyouone~51":"Lady Chiltern — Tenho certeza de que o Sr. Trafford poderá lhe dar uma.","lordgoringthankssomuch~lordgoringthankssomuch~22":"Lord Goring — Muito obrigado.","mabelchilterntommyisthemostusefulpersoni~mostusefulpersoninlondon~47":"Mabel Chiltern — Tommy é a pessoa mais útil de Londres.","lordgoringturningtoherandwhoisthemostorn~ndwhoisthemostornamental~47":"Lord Goring — Voltando-se para ela. E quem é a mais ornamental?","mabelchilterntriumphantlyiam~lchilterntriumphantlyiam~28":"Mabel Chiltern — Triunfante. Eu.","lordgoringhowcleverofyoutoguessittakesup~berwhatisaidtoyouwontyou~108":"Lord Goring — Que esperteza a sua adivinhar! Pega o chapéu e a bengala. Adeus, Lady Chiltern! A senhora vai se lembrar do que lhe disse, não vai?","ladychilternyesbutidontknowwhyyousaiditt~dontknowwhyyousaidittome~43":"Lady Chiltern — Vou; mas não sei por que o senhor me disse aquilo.","lordgoringihardlyknowmyselfgoodbyemissma~owmyselfgoodbyemissmabel~43":"Lord Goring — Eu mesmo mal sei. Adeus, Srta. Mabel!","mabelchilternwithalittlemoueofdisappoint~topandlistentosomeofthem~157":"Mabel Chiltern — Com um biquinho de desapontamento. Queria que o senhor não fosse. Tive quatro aventuras maravilhosas esta manhã; quatro e meia, na verdade. Podia ficar e ouvir algumas delas.","lordgoringhowveryselfishofyoutohavefoura~ftherewontbeanyleftforme~70":"Lord Goring — Que egoísmo o seu ter quatro e meia! Não restará nenhuma para mim.","mabelchilternidontwantyoutohaveanytheywo~theywouldnotbegoodforyou~58":"Mabel Chiltern — Não quero que o senhor tenha nenhuma. Não lhe fariam bem.","lordgoringthatisthefirstunkindthingyouha~nglyyousaidittentomorrow~87":"Lord Goring — Essa é a primeira coisa cruel que já me disse. Com que encanto a disse! Dez horas amanhã.","mabelchilternsharp~mabelchilternsharp~18":"Mabel Chiltern — Em ponto.","lordgoringquitesharpbutdontbringmrtraffo~rpbutdontbringmrtrafford~42":"Lord Goring — Em ponto. Mas não traga o Sr. Trafford.","mabelchilternwithalittletossoftheheadofc~raffordisingreatdisgrace~99":"Mabel Chiltern — Com um pequeno movimento de cabeça. Claro que não trarei Tommy Trafford. Tommy Trafford está em grande desgraça.","lordgoringiamdelightedtohearitbowsandgoe~edtohearitbowsandgoesout~44":"Lord Goring — Fico encantado em saber. Inclina-se e sai.","mabelchilterngertrudeiwishyouwouldspeakt~ouldspeaktotommytrafford~54":"Mabel Chiltern — Gertrude, gostaria que você falasse com Tommy Trafford.","ladychilternwhathaspoormrtrafforddonethi~estsecretaryhehaseverhad~87":"Lady Chiltern — O que fez o pobre Sr. Trafford desta vez? Robert diz que é o melhor secretário que já teve.","mabelchilternwelltommyhasproposedtomeaga~hatattractssomeattention~1238":"Mabel Chiltern — Pois bem, Tommy me pediu em casamento de novo. Tommy realmente não faz outra coisa senão me pedir em casamento. Pediu-me ontem à noite na sala de música, quando eu estava completamente desprotegida, pois havia um elaborado trio em andamento. Não ousei dar a menor resposta, nem preciso dizer. Se tivesse dado, teria parado a música de uma vez. Gente musical é tão absurdamente irracional. Sempre quer que a gente fique perfeitamente muda justo no momento em que a gente anseia por ficar absolutamente surda. Depois me pediu em plena luz do dia esta manhã, diante daquela horrível estátua de Aquiles. Realmente, as coisas que se passam diante daquela obra de arte são completamente espantosas. A polícia devia intervir. No almoço vi pelo brilho de seu olhar que ia pedir de novo, e consegui detê-lo a tempo garantindo-lhe que eu era bimetalista. Felizmente não sei o que significa bimetalismo. E não creio que ninguém mais saiba. Mas a observação esmagou Tommy por dez minutos. Ele ficou bastante chocado. E além disso Tommy é tão irritante no modo como pede. Se pedisse a plenos pulmões, eu não me importaria tanto. Isso poderia produzir algum efeito no público. Mas ele o faz de um jeito horrível, confidencial. Quando Tommy quer ser romântico, fala com a gente exatamente como um médico. Gosto muito de Tommy, mas os seus métodos de pedir em casamento estão completamente fora de moda. Queria, Gertrude, que você falasse com ele e dissesse que uma vez por semana é mais que suficiente para pedir alguém em casamento, e que deve ser sempre feito de maneira a atrair alguma atenção.","ladychilterndearmabeldonttalklikethatbes~brilliantfuturebeforehim~118":"Lady Chiltern — Querida Mabel, não fale assim. Além disso, Robert tem Tommy Trafford em alta conta. Acredita que ele tem um futuro brilhante pela frente.","mabelchilternohiwouldntmarryamanwithafut~imforanythingunderthesun~74":"Mabel Chiltern — Oh! Eu não me casaria com um homem que tem um futuro pela frente por nada neste mundo.","ladychilternmabel~ladychilternmabel~17":"Lady Chiltern — Mabel!","mabelchilterniknowdearyoumarriedamanwith~stlovelygowndidyouaskher~656":"Mabel Chiltern — Eu sei, querida. Você se casou com um homem com futuro, não foi? Mas Robert era um gênio, e você tem um caráter nobre e abnegado. Você aguenta gênios. Eu não tenho caráter nenhum, e Robert é o único gênio que eu poderia suportar. Em geral, acho-os completamente impossíveis. Os gênios falam tanto, não é? Que mau hábito! E estão sempre pensando em si mesmos, quando eu quero que pensem em mim. Preciso ir agora ao ensaio na casa de Lady Basildon. Você se lembra, vamos ter quadros vivos, não se lembra? O Triunfo de alguma coisa, não sei de quê! Espero que seja o triunfo de mim. O único triunfo que realmente me interessa no momento. Beija Lady Chiltern e sai; depois volta correndo. Oh, Gertrude, sabe quem vem visitar você? Aquela horrível Sra. Cheveley, num vestido lindíssimo. Foi você que a convidou?","ladychilternrisingmrscheveleycomingtosee~ycomingtoseemeimpossible~52":"Lady Chiltern — Levantando-se. A Sra. Cheveley! Vindo me visitar? Impossível!","mabelchilterniassureyousheiscomingupstai~ifeandnotnearlysonatural~76":"Mabel Chiltern — Garanto que está subindo a escada, em tamanho natural e nem de longe tão natural.","ladychilternyouneednotwaitmabelrememberl~dybasildonisexpectingyou~65":"Lady Chiltern — Não precisa esperar, Mabel. Lembre-se, Lady Basildon a está esperando.","mabelchilternohimustshakehandswithladyma~ulilovebeingscoldedbyher~81":"Mabel Chiltern — Oh! Preciso cumprimentar Lady Markby. É deliciosa. Adoro ser repreendida por ela.","masonladymarkbymrscheveley~sonladymarkbymrscheveley~26":"Mason — Lady Markby. Sra. Cheveley.","enterladymarkbyandmrscheveley~ladymarkbyandmrscheveley~29":"Entram Lady Markby e a Sra. Cheveley.","ladychilternadvancingtomeetthemdearladym~ontyousitdownmrscheveley~151":"Lady Chiltern — Avançando ao encontro delas. Querida Lady Markby, que gentileza a sua vir me ver! Aperta-lhe a mão e cumprimenta a Sra. Cheveley com certa frieza. Não quer sentar-se, Sra. Cheveley?","mrscheveleythanksisntthatmisschilternish~houldlikesomuchtoknowher~63":"Sra. Cheveley — Obrigada. Aquela não é a Srta. Chiltern? Gostaria tanto de conhecê-la.","ladychilternmabelmrscheveleywishestoknow~scheveleywishestoknowyou~43":"Lady Chiltern — Mabel, a Sra. Cheveley deseja conhecê-la.","mabelchilterngivesalittlenod~lchilterngivesalittlenod~28":"Mabel Chiltern faz um pequeno aceno de cabeça.","mrscheveleysittingdownithoughtyourfrocks~lternsosimpleandsuitable~89":"Sra. Cheveley — Sentando-se. Achei o seu vestido tão encantador ontem à noite, Srta. Chiltern. Tão simples e … adequado.","mabelchilternreallyimusttellmydressmaker~setohergoodbyeladymarkby~83":"Mabel Chiltern — Verdade? Preciso contar à minha costureira. Será uma grande surpresa para ela. Adeus, Lady Markby!","ladymarkbygoingalready~ladymarkbygoingalready~22":"Lady Markby — Já vai?","mabelchilterniamsosorrybutiamobligedtoia~ndonmyheadinsometableaux~96":"Mabel Chiltern — Sinto muito, mas sou obrigada. Estou de saída para o ensaio. Tenho de ficar de cabeça para baixo em alguns quadros vivos.","ladymarkbyonyourheadchildohihopenotibeli~nthesofanextladychiltern~95":"Lady Markby — De cabeça para baixo, menina? Oh! espero que não. Dizem que faz muito mal à saúde. Senta-se no sofá ao lado de Lady Chiltern.","mabelchilternbutitisforanexcellentcharit~tommytraffordistreasurer~138":"Mabel Chiltern — Mas é para uma excelente obra de caridade: em auxílio dos Indignos, as únicas pessoas que realmente me interessam. Sou a secretária, e Tommy Trafford é o tesoureiro.","mrscheveleyandwhatislordgoring~veleyandwhatislordgoring~30":"Sra. Cheveley — E o que é Lord Goring?","mabelchilternohlordgoringispresident~nohlordgoringispresident~36":"Mabel Chiltern — Oh! Lord Goring é o presidente.","mrscheveleythepostshouldsuithimadmirably~oratedsinceiknewhimfirst~81":"Sra. Cheveley — O cargo deve lhe convir admiravelmente, a menos que tenha se deteriorado desde que o conheci.","ladymarkbyreflectingyouareremarkablymode~veknownmanyinstancesofit~172":"Lady Markby — Refletindo. Você é notavelmente moderna, Mabel. Um pouco moderna demais, talvez. Nada é tão perigoso quanto ser moderna demais. A gente corre o risco de ficar fora de moda de repente. Conheci muitos casos.","mabelchilternwhatadreadfulprospect~ernwhatadreadfulprospect~34":"Mabel Chiltern — Que perspectiva terrível!","ladymarkbyahmydearyouneednotbenervousyou~englandsucceedsinsetting~142":"Lady Markby — Ah! minha querida, não precisa ficar nervosa. Você será sempre tão bonita quanto possível. Essa é a melhor moda que existe, e a única moda que a Inglaterra consegue lançar.","mabelchilternwithacurtseythankyousomuchl~renglandandmyselfgoesout~75":"Mabel Chiltern — Fazendo uma reverência. Muito obrigada, Lady Markby, pela Inglaterra … e por mim. Sai.","ladymarkbyturningtoladychilterndeargertr~iamondbroochhasbeenfound~100":"Lady Markby — Voltando-se para Lady Chiltern. Querida Gertrude, passamos apenas para saber se o broche de diamantes da Sra. Cheveley foi encontrado.","ladychilternhere~ladychilternhere~16":"Lady Chiltern — Aqui?","mrscheveleyyesimisseditwhenigotbacktocla~ossiblyhavedroppedithere~88":"Sra. Cheveley — Sim. Senti falta dele ao voltar ao Claridge’s e pensei que poderia tê-lo deixado cair aqui.","ladychilternihaveheardnothingaboutitbuti~tlerandasktouchesthebell~80":"Lady Chiltern — Não ouvi nada a respeito. Mas mandarei chamar o mordomo e perguntarei. Toca a campainha.","mrscheveleyohpraydonttroubleladychiltern~eoperabeforewecameonhere~83":"Sra. Cheveley — Oh, por favor, não se incomode, Lady Chiltern. Ouso dizer que o perdi na Ópera, antes de virmos para cá.","ladymarkbyahyesisupposeitmusthavebeenatt~twoulddoagreatdealofgood~484":"Lady Markby — Ah sim, suponho que deve ter sido na Ópera. O fato é que nos empurramos e acotovelamos tanto hoje em dia que me admira que nos reste alguma coisa no corpo ao final de uma noite. Sei por mim mesma que, ao voltar da Corte, sinto sempre como se não tivesse um fiapo sobre mim, exceto um pequeno fiapo de reputação decente, justo o suficiente para impedir que as classes baixas façam observações dolorosas pelas janelas da carruagem. O fato é que a nossa Sociedade está terrivelmente superpovoada. Realmente, alguém deveria organizar um plano adequado de emigração assistida. Faria muito bem.","mrscheveleyiquiteagreewithyouladymarkbyi~heoddestpeopleeverywhere~165":"Sra. Cheveley — Concordo inteiramente com a senhora, Lady Markby. Há quase seis anos não venho a Londres para a Temporada, e devo dizer que a Sociedade se tornou terrivelmente misturada. Veem-se as pessoas mais esquisitas por toda parte.","ladymarkbythatisquitetruedearbutoneneedn~mallihearishouldntliketo~126":"Lady Markby — É bem verdade, querida. Mas não é preciso conhecê-las. Tenho certeza de que não conheço metade das pessoas que frequentam minha casa. Aliás, pelo que ouço, não gostaria de conhecer.","ladychilternwhatsortofabroochwasitthatyo~itthatyoulostmrscheveley~56":"Lady Chiltern — Que espécie de broche foi o que a senhora perdeu, Sra. Cheveley?","mrscheveleyadiamondsnakebroochwitharubya~itharubyaratherlargeruby~55":"Sra. Cheveley — Um broche de diamantes em forma de serpente, com um rubi, um rubi bastante grande.","ladymarkbyithoughtyousaidtherewasasapphi~asasapphireontheheaddear~55":"Lady Markby — Pensei que você tivesse dito que havia uma safira na cabeça, querida.","mrscheveleysmilingnoladymarkbyaruby~smilingnoladymarkbyaruby~35":"Sra. Cheveley — Sorrindo. Não, Lady Markby... um rubi.","ladymarkbynoddingherheadandverybecomingi~verybecomingiamquitesure~51":"Lady Markby — Acenando com a cabeça. E muito favorecedor, tenho certeza.","ladychilternhasarubyanddiamondbroochbeen~theroomsthismorningmason~76":"Lady Chiltern — Algum broche de rubi e diamantes foi encontrado em algum dos aposentos esta manhã, Mason?","masonnomylady~masonnomylady~13":"Mason — Não, minha senhora.","mrscheveleyitreallyisofnoconsequencelady~putyoutoanyinconvenience~88":"Sra. Cheveley — Realmente não tem importância, Lady Chiltern. Sinto tanto tê-la incomodado.","ladychilterncoldlyohithasbeennoinconveni~illdomasonyoucanbringtea~73":"Lady Chiltern — Friamente. Oh, não foi incômodo algum. Pode retirar-se, Mason. Traga o chá.","exitmason~exitmason~9":"Sai Mason.","ladymarkbywellimustsayitismostannoyingto~cationofwomenwasinvented~420":"Lady Markby — Bem, devo dizer que é muitíssimo aborrecido perder qualquer coisa. Lembro-me de uma vez, em Bath, anos atrás, ter perdido na Pump Room uma pulseira de camafeu extremamente bonita que Sir John me havia dado. Não creio que ele tenha me dado nada desde então, lamento dizer. Degenerou tristemente. Realmente, esta horrível Câmara dos Comuns arruína por completo os nossos maridos. Acho a Câmara Baixa de longe o maior golpe na felicidade conjugal desde que inventaram aquela coisa terrível chamada Educação Superior das Mulheres.","ladychilternahitisheresytosaythatinthish~ofwomenandsoiamafraidami~120":"Lady Chiltern — Ah! é heresia dizer isso nesta casa, Lady Markby. Robert é grande defensor da Educação Superior das Mulheres, e eu, receio, também.","mrscheveleythehighereducationofmeniswhat~iketoseemenneeditsosadly~72":"Sra. Cheveley — A educação superior dos homens é o que eu gostaria de ver. Os homens precisam tanto dela.","ladymarkbytheydodearbutiamafraidsuchasch~erstandeverythingiamtold~487":"Lady Markby — Precisam, querida. Mas receio que tal plano seria inteiramente impraticável. Não creio que o homem tenha grande capacidade de desenvolvimento. Foi tão longe quanto pôde, e não foi longe, foi? Quanto às mulheres, bem, querida Gertrude, você pertence à geração mais jovem, e tenho certeza de que está tudo bem se você aprova. No meu tempo, é claro, ensinavam-nos a não compreender coisa alguma. Era o sistema antigo, e maravilhosamente interessante. Garanto-lhe que a quantidade de coisas que eu e minha pobre querida irmã aprendemos a não compreender era extraordinária. Mas as mulheres modernas compreendem tudo, dizem-me.","mrscheveleyexcepttheirhusbandsthatistheo~ernwomanneverunderstands~77":"Sra. Cheveley — Exceto seus maridos. Essa é a única coisa que a mulher moderna nunca compreende.","ladymarkbyandaverygoodthingtoodearidares~atsirrobertisnotlikethat~1132":"Lady Markby — E uma ótima coisa também, querida, ouso dizer. Poderia desfazer muito lar feliz se compreendessem. O seu não, nem preciso dizer, Gertrude. Você se casou com um marido-modelo. Quem me dera poder dizer o mesmo de mim. Mas desde que Sir John deu para frequentar os debates regularmente, o que nunca fazia nos bons velhos tempos, sua linguagem se tornou completamente impossível. Parece pensar sempre que está se dirigindo à Câmara e, por conseguinte, sempre que discute a situação do trabalhador agrícola, ou a Igreja galesa, ou algo bastante impróprio desse gênero, sou obrigada a mandar todos os criados saírem da sala. Não é agradável ver o próprio mordomo, que está conosco há vinte e três anos, realmente corando junto ao aparador, e os lacaios fazendo contorções nos cantos como gente de circo. Garanto-lhe que minha vida estará de todo arruinada a menos que mandem John imediatamente para a Câmara Alta. Ele não terá interesse pela política então, terá? A Câmara dos Lordes é tão sensata. Uma assembleia de cavalheiros. Mas no estado atual, Sir John é realmente uma grande provação. Ora, esta manhã, antes de o desjejum ir pela metade, ele se pôs de pé sobre o tapete da lareira, meteu as mãos nos bolsos e apelou ao país a plenos pulmões. Deixei a mesa assim que tomei a segunda xícara de chá, nem preciso dizer. Mas a sua linguagem violenta podia ser ouvida por toda a casa! Confio, Gertrude, em que Sir Robert não seja assim.","ladychilternbutiamverymuchinterestedinpo~ohearroberttalkaboutthem~86":"Lady Chiltern — Mas eu me interesso muito por política, Lady Markby. Adoro ouvir Robert falar sobre ela.","ladymarkbywellihopeheisnotasdevotedtoblu~mprovingreadingforanyone~106":"Lady Markby — Bem, espero que ele não seja tão devoto dos Livros Azuis quanto Sir John. Não creio que possam ser uma leitura edificante para ninguém.","mrscheveleylanguidlyihaveneverreadablueb~referbooksinyellowcovers~69":"Sra. Cheveley — Languidamente. Nunca li um Livro Azul. Prefiro livros … de capa amarela.","ladymarkbygeniallyunconsciousyellowisaga~salwaysridiculousishenot~213":"Lady Markby — Cordialmente inconsciente. O amarelo é uma cor mais alegre, não é? Eu usava muito amarelo nos meus primeiros tempos, e o usaria agora se Sir John não fosse tão dolorosamente pessoal em suas observações, e um homem, em questão de vestuário, é sempre ridículo, não é?","mrscheveleyohnoithinkmenaretheonlyauthor~heonlyauthoritiesondress~52":"Sra. Cheveley — Oh, não! Acho que os homens são as únicas autoridades em vestuário.","ladymarkbyreallyonewouldntsaysofromtheso~rtofhatstheywearwouldone~64":"Lady Markby — Verdade? Não se diria, pelo tipo de chapéus que usam, diria?","thebutlerentersfollowedbythefootmanteais~tableclosetoladychiltern~75":"O mordomo entra, seguido do lacaio. O chá é posto numa mesinha junto a Lady Chiltern.","ladychilternmayigiveyousometeamrschevele~iveyousometeamrscheveley~41":"Lady Chiltern — Posso servir-lhe um pouco de chá, Sra. Cheveley?","mrscheveleythanksthebutlerhandsmrschevel~eveleyacupofteaonasalver~60":"Sra. Cheveley — Obrigada. O mordomo oferece à Sra. Cheveley uma xícara de chá numa salva.","ladychilternsometealadymarkby~hilternsometealadymarkby~29":"Lady Chiltern — Um pouco de chá, Lady Markby?","ladymarkbynothanksdeartheservantsgooutth~tisverymuchtoberegretted~875":"Lady Markby — Não, obrigada, querida. Os criados saem. O fato é que prometi passar dez minutos para ver a pobre Lady Brancaster, que está em grande aflição. A filha dela, uma moça muito bem-educada, aliás, ficou realmente noiva de um cura em Shropshire. É muito triste, tristíssimo. Não consigo compreender esta mania moderna pelos curas. No meu tempo, nós, moças, os víamos, é claro, correndo pelo lugar como coelhos. Mas nunca lhes dávamos atenção, nem preciso dizer. Mas dizem-me que hoje em dia a sociedade do campo está completamente minada por eles. Acho irreligiosíssimo. E depois o filho mais velho brigou com o pai, e dizem que, quando se encontram no clube, Lord Brancaster se esconde sempre atrás do artigo financeiro do The Times. Aliás, creio que isso é bastante comum hoje em dia, e que eles têm de receber exemplares extras do The Times em todos os clubes da St. James’s Street; há tantos filhos que não querem saber dos pais, e tantos pais que não falam com os filhos. Eu mesma acho muito de lamentar.","mrscheveleysodoifathershavesomuchtolearn~arnfromtheirsonsnowadays~61":"Sra. Cheveley — Eu também. Os pais têm tanto a aprender com os filhos hoje em dia.","ladymarkbyreallydearwhat~ladymarkbyreallydearwhat~24":"Lady Markby — Verdade, querida? O quê?","mrscheveleytheartoflivingtheonlyreallyfi~aveproducedinmoderntimes~72":"Sra. Cheveley — A arte de viver. A única Bela Arte realmente produzida nos tempos modernos.","ladymarkbyshakingherheadahiamafraidlordb~adybrancasterdontyoudear~150":"Lady Markby — Balançando a cabeça. Ah! receio que Lord Brancaster soubesse bastante a esse respeito. Mais do que a pobre esposa jamais soube. Voltando-se para Lady Chiltern. Você conhece Lady Brancaster, não conhece, querida?","ladychilternjustslightlyshewasstayingatl~astautumnwhenwewerethere~71":"Lady Chiltern — Apenas de leve. Esteve hospedada em Langton no outono passado, quando estávamos lá.","ladymarkbywelllikeallstoutwomenshelookst~condolenceishantstaylong~629":"Lady Markby — Bem, como todas as mulheres gordas, parece o retrato mesmo da felicidade, como sem dúvida você notou. Mas há muitas tragédias em sua família, além deste caso do cura. A própria irmã, a Sra. Jekyll, teve uma vida infelicíssima; sem culpa alguma de sua parte, lamento dizer. Acabou tão desgostosa que entrou para um convento, ou foi para o palco da ópera, esqueci qual. Não; creio que o que ela tomou foi o bordado artístico decorativo. Sei que havia perdido todo o senso de prazer na vida. Levantando-se. E agora, Gertrude, se me permite, deixarei a Sra. Cheveley aos seus cuidados e voltarei para buscá-la em um quarto de hora. Ou talvez, querida Sra. Cheveley, a senhora não se importasse de esperar na carruagem enquanto estou com Lady Brancaster. Como pretendo que seja uma visita de pêsames, não ficarei muito tempo.","mrscheveleyrisingidontmindwaitingintheca~ereissomebodytolookatone~85":"Sra. Cheveley — Levantando-se. Não me importo nada de esperar na carruagem, contanto que haja alguém para olhar.","ladymarkbywellihearthecurateisalwaysprow~aysprowlingaboutthehouse~57":"Lady Markby — Bem, ouço dizer que o cura está sempre rondando a casa.","mrscheveleyiamafraidiamnotfondofgirlfrie~diamnotfondofgirlfriends~43":"Sra. Cheveley — Receio não ser aficionada por amigas moças.","ladychilternrisingohihopemrscheveleywill~nutesconversationwithher~102":"Lady Chiltern — Levantando-se. Oh, espero que a Sra. Cheveley fique aqui um pouco. Gostaria de ter alguns minutos de conversa com ela.","mrscheveleyhowverykindofyouladychilternb~uldgivemegreaterpleasure~81":"Sra. Cheveley — Que gentileza a sua, Lady Chiltern! Acredite, nada me daria maior prazer.","ladymarkbyahnodoubtyoubothhavemanypleasa~atisagreatcomfortisitnot~226":"Lady Markby — Ah! sem dúvida as duas têm muitas reminiscências agradáveis dos tempos de colégio para conversar. Adeus, querida Gertrude! Vejo você na casa de Lady Bonar esta noite? Ela descobriu um maravilhoso gênio novo. Ele não faz … absolutamente nada, creio. É um grande conforto, não é?","ladychilternrobertandiarediningathomebyo~reisnothinginterestingon~160":"Lady Chiltern — Robert e eu jantamos em casa, sozinhos, esta noite, e não creio que irei a lugar algum depois. Robert, é claro, terá de estar na Câmara. Mas não há nada de interessante em pauta.","ladymarkbydiningathomebyyourselvesisthat~eneralruleexitladymarkby~177":"Lady Markby — Jantando em casa, sozinhos? Isso é prudente? Ah, esqueci, seu marido é uma exceção. O meu é a regra geral, e nada envelhece tão depressa uma mulher quanto ter se casado com a regra geral. Sai Lady Markby.","mrscheveleywonderfulwomanladymarkbyisnts~aysdullandusuallyviolent~187":"Sra. Cheveley — Mulher maravilhosa, Lady Markby, não é? Fala mais e diz menos do que qualquer pessoa que já conheci. Nasceu para oradora pública. Muito mais do que o marido, embora ele seja um inglês típico, sempre maçante e geralmente violento.","ladychilternmakesnoanswerbutremainsstand~tedyoutomyhouselastnight~258":"Lady Chiltern — Não responde, mas permanece de pé. Há uma pausa. Então os olhos das duas mulheres se encontram. Lady Chiltern parece severa e pálida. A Sra. Cheveley parece bastante divertida. Sra. Cheveley, creio ser correto dizer-lhe com toda a franqueza que, se eu soubesse quem a senhora realmente era, não a teria convidado à minha casa ontem à noite.","mrscheveleywithanimpertinentsmilereally~animpertinentsmilereally~39":"Sra. Cheveley — Com um sorriso impertinente. Verdade?","ladychilternicouldnothavedoneso~lternicouldnothavedoneso~31":"Lady Chiltern — Não poderia tê-lo feito.","mrscheveleyiseethatafteralltheseyearsyou~venotchangedabitgertrude~66":"Sra. Cheveley — Vejo que, depois de todos estes anos, você não mudou nada, Gertrude.","ladychilternineverchange~ladychilternineverchange~24":"Lady Chiltern — Nunca mudo.","mrscheveleyelevatinghereyebrowsthenlifeh~nlifehastaughtyounothing~58":"Sra. Cheveley — Erguendo as sobrancelhas. Então a vida não lhe ensinou nada?","ladychilternithastaughtmethatapersonwhoh~ndtimeandshouldbeshunned~134":"Lady Chiltern — Ensinou-me que uma pessoa que uma vez se tornou culpada de uma ação desonesta e desonrosa pode tornar-se culpada dela uma segunda vez, e deve ser evitada.","mrscheveleywouldyouapplythatruletoeveryo~uapplythatruletoeveryone~42":"Sra. Cheveley — Você aplicaria essa regra a todos?","ladychilternyestoeveryonewithoutexceptio~everyonewithoutexception~41":"Lady Chiltern — Sim, a todos, sem exceção.","mrscheveleytheniamsorryforyougertrudever~ugertrudeverysorryforyou~52":"Sra. Cheveley — Então tenho pena de você, Gertrude, muita pena.","ladychilternyouseenowiwassurethatformany~nlondonisquiteimpossible~117":"Lady Chiltern — Vê agora, tenho certeza, que, por muitas razões, qualquer outro trato entre nós durante a sua estada em Londres é inteiramente impossível?","mrscheveleyleaningbackinherchairdoyoukno~ecomeheretodoyouaservice~241":"Sra. Cheveley — Recostando-se na cadeira. Sabe, Gertrude, não me importo nem um pouco que você fale de moralidade. A moralidade é simplesmente a atitude que adotamos para com as pessoas de quem pessoalmente não gostamos. Você não gosta de mim. Estou perfeitamente ciente disso. E eu sempre a detestei. E, no entanto, vim aqui para lhe prestar um serviço.","ladychilterncontemptuouslyliketheservice~kheavenisavedhimfromthat~111":"Lady Chiltern — Com desprezo. Como o serviço que desejava prestar a meu marido ontem à noite, suponho. Graças aos céus, eu o salvei disso.","mrscheveleystartingtoherfeetitwasyouwhom~homadehimbreakhispromise~106":"Sra. Cheveley — Pondo-se de pé num salto. Foi você quem o fez escrever aquela carta insolente para mim? Foi você quem o fez quebrar a promessa?","mrscheveleythenyoumustmakehimkeepitigive~hemeinwhichiaminterested~162":"Sra. Cheveley — Então você deve fazê-lo cumpri-la. Dou-lhe até amanhã de manhã... nem mais. Se até lá seu marido não se obrigar solenemente a me ajudar neste grande projeto em que tenho interesse...","ladychilternthisfraudulentspeculation~hisfraudulentspeculation~37":"Lady Chiltern — Esta especulação fraudulenta...","mrscheveleycallitwhatyouchooseiholdyourh~illmakehimdowhatitellhim~108":"Sra. Cheveley — Chame como quiser. Tenho seu marido na palma da mão, e, se for sensata, você o fará fazer o que eu lhe disser.","ladychilternrisingandgoingtowardsheryoua~withyouwithawomanlikeyou~97":"Lady Chiltern — Levantando-se e indo até ela. Você é impertinente. O que tem meu marido a ver com você? Com uma mulher como você?","mrscheveleywithabitterlaughinthisworldli~ogetherthesamesinbindsus~231":"Sra. Cheveley — Com uma risada amarga. Neste mundo os iguais se encontram. É porque seu marido é ele próprio fraudulento e desonesto que combinamos tão bem. Entre você e ele há abismos. Ele e eu somos mais que amigos. Somos inimigos ligados um ao outro. O mesmo pecado nos une.","ladychilternhowdareyouclassmyhusbandwith~ouseyouareunfittoenterit~105":"Lady Chiltern — Como ousa classificar meu marido junto de si mesma? Como ousa ameaçá-lo, ou a mim? Saia da minha casa. Você não é digna de entrar nela.","sirrobertchilternentersfrombehindhehears~dressedhegrowsdeadlypale~103":"Sir Robert Chiltern entra por trás. Ouve as últimas palavras da esposa e vê a quem são dirigidas. Fica mortalmente pálido.","mrscheveleyyourhouseahouseboughtwiththep~towhatyouoweyourposition~254":"Sra. Cheveley — Sua casa! Uma casa comprada com o preço da desonra. Uma casa em que tudo foi pago com fraude. Volta-se e vê Sir Robert Chiltern. Pergunte a ele qual é a origem de sua fortuna! Faça-o contar como vendeu a um corretor da Bolsa um segredo do Gabinete. Aprenda com ele a que deve a sua posição.","ladychilternitisnottruerobertitisnottrue~nottruerobertitisnottrue~40":"Lady Chiltern — Não é verdade! Robert! Não é verdade!","mrscheveleypointingathimwithoutstretched~mcanhedenyitdoeshedareto~78":"Sra. Cheveley — Apontando-o com o dedo estendido. Olhe para ele! Pode negar? Ousa negar?","sirrobertchilterngogoatonceyouhavedoneyo~eyouhavedoneyourworstnow~50":"Sir Robert Chiltern — Vá! Vá imediatamente. Você já fez o pior que podia.","mrscheveleymyworstihavenotyetfinishedwit~heoriginofrobertchiltern~168":"Sra. Cheveley — O pior? Ainda não terminei com você, com nenhum dos dois. Dou a ambos até amanhã ao meio-dia. Se até lá não fizerem o que mando, o mundo inteiro saberá a origem de Robert Chiltern.","sirrobertchilternstrikesthebellentermaso~strikesthebellentermason~41":"Sir Robert Chiltern toca a campainha. Entra Mason.","sirrobertchilternshowmrscheveleyout~ilternshowmrscheveleyout~35":"Sir Robert Chiltern — Acompanhe a Sra. Cheveley até a saída.","mrscheveleystartsthenbowswithsomewhatexa~seeinghimforthefirsttime~436":"A Sra. Cheveley estremece; depois faz uma reverência de polidez um tanto exagerada a Lady Chiltern, que não dá sinal de resposta. Ao passar por Sir Robert Chiltern, que está de pé junto à porta, detém-se um instante e o olha direto no rosto. Em seguida sai, seguida do criado, que fecha a porta atrás de si. Marido e mulher ficam a sós. Lady Chiltern permanece como alguém num sonho terrível. Depois se volta e olha o marido. Olha-o com olhos estranhos, como se o visse pela primeira vez.","ladychilternyousoldacabinetsecretformone~lietometellmeitisnottrue~147":"Lady Chiltern — Você vendeu um segredo do Gabinete por dinheiro! Você começou a vida com fraude! Construiu a sua carreira sobre a desonra! Oh, diga-me que não é verdade! Minta para mim! Minta para mim! Diga-me que não é verdade!","sirrobertchilternwhatthiswomansaidisquit~wholethinggoestowardsher~133":"Sir Robert Chiltern — O que essa mulher disse é inteiramente verdade. Mas, Gertrude, ouça-me. Você não imagina como fui tentado. Deixe-me contar-lhe tudo. Vai em direção a ela.","ladychilterndontcomenearmedonttouchmeife~dandyetyouwillnotlietome~285":"Lady Chiltern — Não se aproxime de mim. Não me toque. Sinto como se você me tivesse manchado para sempre. Oh! que máscara você usou todos estes anos! Uma máscara horrível, pintada! Você se vendeu por dinheiro. Oh! um ladrão comum seria melhor. Você se pôs à venda ao maior lance! Foi comprado no mercado. Mentiu a todo o mundo. E, no entanto, não quer mentir para mim.","sirrobertchilternrushingtowardshergertru~wardshergertrudegertrude~50":"Sir Robert Chiltern — Precipitando-se para ela. Gertrude! Gertrude!","ladychilternthrustinghimbackwithoutstret~umyidealtheidealofmylife~425":"Lady Chiltern — Repelindo-o com as mãos estendidas. Não, não fale! Não diga nada! Sua voz desperta recordações terríveis... recordações de coisas que me fizeram amá-lo... recordações de palavras que me fizeram amá-lo... recordações que agora me são horríveis. E como eu o adorava! Você era para mim algo à parte da vida comum, algo puro, nobre, honesto, sem mácula. O mundo me parecia mais belo porque você estava nele, e a bondade mais real porque você vivia. E agora... oh, quando penso que fiz de um homem como você o meu ideal! o ideal da minha vida!","sirrobertchilterntherewasyourmistakether~ildlylovedhaveruinedmine~1452":"Sir Robert Chiltern — Aí esteve o seu engano. Aí esteve o seu erro. O erro que todas as mulheres cometem. Por que vocês, mulheres, não podem nos amar com todas as nossas faltas? Por que nos põem em monstruosos pedestais? Todos temos pés de barro, mulheres tanto quanto homens; mas quando nós, homens, amamos as mulheres, amamo-las conhecendo suas fraquezas, suas loucuras, suas imperfeições, amamo-las tanto mais, talvez, por essa razão. Não é o perfeito, mas o imperfeito, que precisa de amor. É quando somos feridos por nossas próprias mãos, ou pelas mãos de outros, que o amor deve vir nos curar... senão, de que serve o amor? Todos os pecados, exceto o pecado contra si mesmo, o Amor deve perdoar. Todas as vidas, salvo as vidas sem amor, o verdadeiro Amor deve perdoar. O amor de um homem é assim. É mais amplo, maior, mais humano que o de uma mulher. As mulheres pensam que fazem ideais dos homens. O que fazem de nós são meros ídolos falsos. Você fez de mim o seu ídolo falso, e eu não tive a coragem de descer, mostrar-lhe minhas feridas, contar-lhe minhas fraquezas. Tive medo de perder o seu amor, como o perdi agora. E assim, ontem à noite você arruinou a minha vida... sim, arruinou! O que essa mulher me pedia nada era comparado ao que me oferecia. Oferecia segurança, paz, estabilidade. O pecado da minha juventude, que eu julgara enterrado, ergueu-se diante de mim, hediondo, horrível, com as mãos em minha garganta. Eu poderia tê-lo matado para sempre, mandado de volta ao túmulo, destruído o seu registro, queimado a única testemunha contra mim. Você me impediu. Ninguém além de você, bem sabe. E agora o que há diante de mim senão a desgraça pública, a ruína, a vergonha terrível, a zombaria do mundo, uma vida solitária e desonrada, uma morte solitária e desonrada, talvez, algum dia? Que as mulheres não façam mais ideais dos homens! que não os ponham em altares nem se curvem diante deles, ou poderão arruinar outras vidas tão completamente como você... você a quem amei tão loucamente... arruinou a minha!","hepassesfromtheroomladychilternrushestow~bsarelikethesobsofachild~284":"Ele sai da sala. Lady Chiltern precipita-se atrás dele, mas a porta está fechada quando chega a ela. Pálida de angústia, desnorteada, desamparada, oscila como uma planta n’água. Suas mãos, estendidas, parecem tremer no ar como flores ao vento. Depois ela se atira ao lado de um sofá e esconde o rosto. Seus soluços são como os de uma criança.","thelibraryinlordgoringshouseanadamroomon~esentsthedominanceofform~437":"A biblioteca na casa de Lord Goring. Uma sala estilo Adam. À direita, a porta que dá para o vestíbulo. À esquerda, a porta do fumoir. Uma porta dupla de correr ao fundo abre para a sala de visitas. O fogo está aceso. Phipps, o mordomo, arruma alguns jornais sobre a escrivaninha. A distinção de Phipps é sua impassibilidade. Entusiastas chamaram-no de o Mordomo Ideal. A Esfinge não é tão incomunicável. É uma máscara com maneiras. De sua vida intelectual ou emocional, a história nada sabe. Representa o domínio da forma.","enterlordgoringineveningdresswithabutton~herinthehistoryofthought~284":"Entra Lord Goring em traje de noite, com uma flor na lapela. Usa cartola de seda e capa Inverness. De luvas brancas, leva uma bengala Luís XVI. São seus todos os delicados refinamentos da Moda. Vê-se que ele está em relação imediata com a vida moderna, faz dela na verdade, e assim a domina. É o primeiro filósofo bem-vestido da história do pensamento.","lordgoringgotmysecondbuttonholeformephip~ondbuttonholeformephipps~42":"Lord Goring — Trouxe a minha segunda flor de lapela, Phipps?","phippsyesmylordtakeshishatcaneandcapeand~ntsnewbuttonholeonsalver~69":"Phipps — Sim, milorde. Toma-lhe o chapéu, a bengala e a capa, e apresenta a nova flor numa salva.","lordgoringratherdistinguishedthingphipps~esentwhowearsabuttonhole~115":"Lord Goring — Coisa bastante distinta, Phipps. Sou a única pessoa da menor importância em Londres no momento que usa uma flor na lapela.","phippsyesmylordihaveobservedthat~smylordihaveobservedthat~32":"Phipps — Sim, milorde. Tenho observado isso.","lordgoringtakingoutoldbuttonholeyouseeph~bleiswhatotherpeoplewear~112":"Lord Goring — Tirando a flor velha. Veja, Phipps, a Moda é o que a gente mesmo usa. O que está fora de moda é o que os outros usam.","phippsyesmylord~phippsyesmylord~15":"Phipps — Sim, milorde.","lordgoringjustasvulgarityissimplythecond~ytheconductofotherpeople~56":"Lord Goring — Assim como a vulgaridade é simplesmente a conduta dos outros.","lordgoringputtinginanewbuttonholeandfals~dsthetruthsofotherpeople~68":"Lord Goring — Pondo a nova flor. E as mentiras, as verdades dos outros.","lordgoringotherpeoplearequitedreadfulthe~possiblesocietyisoneself~68":"Lord Goring — Os outros são absolutamente terríveis. A única sociedade possível é a de si mesmo.","lordgoringtoloveoneselfisthebeginningofa~ofalifelongromancephipps~61":"Lord Goring — Amar a si mesmo é o começo de um romance para toda a vida, Phipps.","lordgoringlookingathimselfintheglassdont~intheprimeoflifeehphipps~136":"Lord Goring — Olhando-se no espelho. Não creio que goste muito desta flor, Phipps. Faz-me parecer um pouco velho demais. Deixa-me quase na flor da idade, hein, Phipps?","phippsidontobserveanyalterationinyourlor~nyourlordshipsappearance~56":"Phipps — Não observo nenhuma alteração na aparência de Vossa Senhoria.","lordgoringyoudontphipps~lordgoringyoudontphipps~23":"Lord Goring — Não observa, Phipps?","phippsnomylord~phippsnomylord~14":"Phipps — Não, milorde.","lordgoringiamnotquitesureforthefutureamo~phippsonthursdayevenings~83":"Lord Goring — Não tenho muita certeza. Para o futuro, uma flor mais frívola, Phipps, nas noites de quinta-feira.","phippsiwillspeaktothefloristmylordshehas~mplainsofinthebuttonhole~145":"Phipps — Falarei com a florista, milorde. Ela teve uma perda na família recentemente, o que talvez explique a falta de frivolidade de que Vossa Senhoria se queixa na flor.","lordgoringextraordinarythingaboutthelowe~wayslosingtheirrelations~90":"Lord Goring — Coisa extraordinária nas classes baixas da Inglaterra... estão sempre perdendo os parentes.","phippsyesmylordtheyareextremelyfortunate~lyfortunateinthatrespect~53":"Phipps — Sim, milorde! São extremamente afortunadas a esse respeito.","lordgoringturnsroundandlooksathimphippsr~ssivehumanylettersphipps~74":"Lord Goring — Volta-se e o olha. Phipps permanece impassível. Hum! Há cartas, Phipps?","phippsthreemylordhandslettersonasalver~ordhandslettersonasalver~38":"Phipps — Três, milorde. Entrega as cartas numa salva.","lordgoringtakesletterswantmycabroundintw~ycabroundintwentyminutes~51":"Lord Goring — Toma as cartas. Quero meu cabriolé na porta em vinte minutos.","phippsyesmylordgoestowardsdoor~yesmylordgoestowardsdoor~30":"Phipps — Sim, milorde. Vai em direção à porta.","lordgoringholdsupletterinpinkenvelopeahe~swhendidthisletterarrive~70":"Lord Goring — Ergue uma carta em envelope cor-de-rosa. Hã-hã! Phipps, quando chegou esta carta?","phippsitwasbroughtbyhandjustafteryourlor~ourlordshipwenttotheclub~58":"Phipps — Foi trazida em mãos logo depois que Vossa Senhoria saiu para o clube.","lordgoringthatwilldoexitphippsladychilte~nyoneelsegoestowardsbell~825":"Lord Goring — Isso é tudo. Sai Phipps. A letra de Lady Chiltern no papel de carta cor-de-rosa de Lady Chiltern. Isso é bastante curioso. Pensei que Robert fosse escrever. Pergunto-me o que Lady Chiltern terá a me dizer. Senta-se à escrivaninha, abre a carta e a lê. “Preciso do senhor. Confio no senhor. Estou indo ter com o senhor. Gertrude.” Pousa a carta com ar intrigado. Depois a toma e a lê de novo, lentamente. “Preciso do senhor. Confio no senhor. Estou indo ter com o senhor.” Então ela descobriu tudo! Pobre mulher! Pobre mulher! Tira o relógio e o olha. Mas que hora para uma visita! Dez horas! Terei de abrir mão de ir a Berkshire. Contudo, é sempre agradável ser esperado e não chegar. Não sou esperado no Bachelors’, de modo que certamente irei para lá. Bem, vou fazê-la ficar ao lado do marido. É a única coisa que ela deve fazer. É a única coisa que qualquer mulher deve fazer. É o crescimento do senso moral nas mulheres que torna o casamento uma instituição tão desesperada e unilateral. Dez horas. Ela deve chegar logo. Preciso dizer a Phipps que não estou para mais ninguém. Vai em direção à campainha.","enterphipps~enterphipps~11":"Entra Phipps.","phippslordcaversham~phippslordcaversham~19":"Phipps — Lord Caversham.","lordgoringohwhywillparentsalwaysappearat~ydearfathergoestomeethim~152":"Lord Goring — Oh, por que os pais sempre aparecem na hora errada? Algum extraordinário erro da natureza, suponho. Entra Lord Caversham. Encantado em vê-lo, meu caro pai. Vai ao seu encontro.","lordcavershamtakemycloakoff~dcavershamtakemycloakoff~27":"Lord Caversham — Tire-me a capa.","lordgoringisitworthwhilefather~ringisitworthwhilefather~30":"Lord Goring — Vale a pena, pai?","lordcavershamofcourseitisworthwhilesirwh~sthemostcomfortablechair~68":"Lord Caversham — Claro que vale a pena, senhor. Qual é a poltrona mais confortável?","lordgoringthisonefatheritisthechairiusem~emyselfwhenihavevisitors~62":"Lord Goring — Esta, pai. É a poltrona que eu mesmo uso quando tenho visitas.","lordcavershamthankyenodraughtihopeinthis~nodraughtihopeinthisroom~44":"Lord Caversham — Obrigado. Não há corrente de ar nesta sala, espero?","lordgoringnofather~lordgoringnofather~18":"Lord Goring — Não, pai.","lordcavershamsittingdowngladtohearitcant~draughtsnodraughtsathome~69":"Lord Caversham — Sentando-se. Fico contente em saber. Não suporto correntes de ar. Em casa não há correntes de ar.","lordgoringgoodmanybreezesfather~inggoodmanybreezesfather~31":"Lord Goring — Há muitas brisas, pai.","lordcavershamehehdontunderstandwhatyoume~usconversationwithyousir~82":"Lord Caversham — Hein? Hein? Não entendo o que quer dizer. Quero ter uma conversa séria com o senhor.","lordgoringmydearfatheratthishour~ngmydearfatheratthishour~32":"Lord Goring — Meu caro pai! A esta hora?","lordcavershamwellsiritisonlytenoclockwha~thehourisanadmirablehour~95":"Lord Caversham — Ora, senhor, são apenas dez horas. Que objeção tem à hora? Acho a hora admirável!","lordgoringwellthefactisfatherthisisnotmy~verysorrybutitisnotmyday~89":"Lord Goring — Bem, o fato é, pai, que este não é o meu dia de falar a sério. Sinto muito, mas não é o meu dia.","lordcavershamwhatdoyoumeansir~avershamwhatdoyoumeansir~29":"Lord Caversham — Que quer dizer, senhor?","lordgoringduringtheseasonfatherionlytalk~verymonthfromfourtoseven~93":"Lord Goring — Durante a Temporada, pai, só falo a sério na primeira terça-feira de cada mês, das quatro às sete.","lordcavershamwellmakeittuesdaysirmakeitt~ttuesdaysirmakeittuesday~46":"Lord Caversham — Pois então faça-o numa terça-feira, senhor, faça-o numa terça-feira.","lordgoringbutitisaftersevenfatherandmydo~enitmakesmetalkinmysleep~114":"Lord Goring — Mas já passa das sete, pai, e meu médico diz que não devo ter nenhuma conversa séria depois das sete. Faz-me falar dormindo.","lordcavershamtalkinyoursleepsirwhatdoest~atmatteryouarenotmarried~65":"Lord Caversham — Falar dormindo, senhor? Que importa isso? O senhor não é casado.","lordgoringnofatheriamnotmarried~ingnofatheriamnotmarried~31":"Lord Goring — Não, pai, não sou casado.","lordcavershamhumthatiswhatihavecometotal~ntyoutakehimforyourmodel~535":"Lord Caversham — Hum! É disso que vim falar com o senhor. Tem de se casar, e já. Ora, quando eu tinha a sua idade, senhor, já fora viúvo inconsolável durante três meses e já cortejava a sua admirável mãe. Com os diabos, senhor, é seu dever casar-se. Não pode viver sempre para o prazer. Todo homem de posição é casado hoje em dia. Os solteiros não estão mais na moda. São uma turma estragada. Sabe-se demais sobre eles. O senhor precisa arranjar uma esposa. Veja aonde o seu amigo Robert Chiltern chegou com probidade, trabalho árduo e um casamento sensato com uma boa mulher. Por que não o imita, senhor? Por que não o toma por modelo?","lordgoringithinkishallfather~goringithinkishallfather~28":"Lord Goring — Acho que tomarei, pai.","lordcavershamiwishyouwouldsirthenishould~artlesssirquiteheartless~130":"Lord Caversham — Quisera que o fizesse, senhor. Então eu seria feliz. No momento torno a vida de sua mãe miserável por sua causa. O senhor é sem coração, senhor, completamente sem coração.","lordgoringihopenotfather~lordgoringihopenotfather~24":"Lord Goring — Espero que não, pai.","lordcavershamanditishightimeforyoutogetm~ethirtyfouryearsofagesir~75":"Lord Caversham — E já é mais que hora de se casar. O senhor tem trinta e quatro anos de idade.","lordgoringyesfatherbutionlyadmittothirty~onholeisnottrivialenough~122":"Lord Goring — Sim, pai, mas só admito trinta e dois... trinta e um e meio quando tenho uma flor de lapela realmente boa. Esta flor não é … frívola o bastante.","lordcavershamitellyouyouarethirtyfoursir~ughtsirifeelitdistinctly~169":"Lord Caversham — Digo-lhe que tem trinta e quatro anos, senhor. E há além disso uma corrente de ar em seu quarto, o que torna sua conduta pior. Por que me disse que não havia corrente de ar, senhor? Sinto uma corrente de ar, senhor, sinto-a distintamente.","lordgoringsodoifatheritisadreadfuldraugh~youonwithyourcloakfather~134":"Lord Goring — Eu também, pai. É uma corrente de ar terrível. Irei vê-lo amanhã, pai. Podemos conversar sobre o que quiser. Deixe-me ajudá-lo a pôr a capa, pai.","lordcavershamnosirihavecalledthisevening~oryoursputdownmycloaksir~128":"Lord Caversham — Não, senhor; vim esta noite com um propósito definido, e vou levá-lo até o fim a todo custo para a minha saúde ou a sua. Largue a minha capa, senhor.","lordgoringcertainlyfatherbutletusgointoa~goodfireinthesmokingroom~135":"Lord Goring — Certamente, pai. Mas vamos para outra sala. Toca a campainha. Há aqui uma corrente de ar terrível. Entra Phipps. Phipps, há bom fogo no fumoir?","lordgoringcomeintherefatheryoursneezesar~ezesarequiteheartrending~58":"Lord Goring — Venha para lá, pai. Seus espirros são de cortar o coração.","lordcavershamwellsirisupposeihavearightt~righttosneezewhenichoose~58":"Lord Caversham — Ora, senhor, suponho que tenho o direito de espirrar quando bem entender?","lordgoringapologeticallyquitesofatheriwa~merelyexpressingsympathy~65":"Lord Goring — Desculpando-se. Perfeitamente, pai. Eu estava apenas expressando solidariedade.","lordcavershamohdamnsympathythereisagreat~rtofthinggoingonnowadays~83":"Lord Caversham — Oh, ao diabo com a solidariedade. Há demasiado desse tipo de coisa hoje em dia.","lordgoringiquiteagreewithyoufatherifther~dbelesstroubleintheworld~99":"Lord Goring — Concordo plenamente, pai. Se houvesse menos solidariedade no mundo, haveria menos problemas no mundo.","lordcavershamgoingtowardsthesmokingroomt~paradoxsirihateparadoxes~70":"Lord Caversham — Indo em direção ao fumoir. Isso é um paradoxo, senhor. Odeio paradoxos.","lordgoringsodoifathereverybodyonemeetsis~eitmakessocietysoobvious~93":"Lord Goring — Eu também, pai. Todo mundo que a gente encontra é um paradoxo hoje em dia. É um grande aborrecimento. Torna a sociedade tão óbvia.","lordcavershamturningroundandlookingathis~yunderstandwhatyousaysir~106":"Lord Caversham — Voltando-se e olhando o filho por baixo das sobrancelhas espessas. O senhor sempre entende de fato o que diz?","lordgoringaftersomehesitationyesfatherif~therifilistenattentively~58":"Lord Goring — Após alguma hesitação. Sim, pai, se escuto com atenção.","lordcavershamindignantlyifyoulistenatten~ivelyconceitedyoungpuppy~65":"Lord Caversham — Indignado. Se escuta com atenção! … Jovem cachorro presunçoso!","goesoffgrumblingintothesmokingroomphipps~esmokingroomphippsenters~46":"Sai resmungando para o fumoir. Entra Phipps.","lordgoringphippsthereisaladycomingtoseem~nshearrivesyouunderstand~124":"Lord Goring — Phipps, uma dama virá me ver esta noite para tratar de assunto particular. Conduza-a à sala de visitas quando chegar. Entendeu?","lordgoringitisamatterofthegravestimporta~egravestimportancephipps~49":"Lord Goring — É um assunto da mais grave importância, Phipps.","phippsiunderstandmylord~phippsiunderstandmylord~23":"Phipps — Compreendo, milorde.","lordgoringnooneelseistobeadmittedunderan~tedunderanycircumstances~54":"Lord Goring — Ninguém mais deve ser admitido, sob nenhuma circunstância.","phippsiunderstandmylordbellrings~nderstandmylordbellrings~32":"Phipps — Compreendo, milorde. A campainha toca.","lordgoringahthatisprobablytheladyishalls~heladyishallseehermyself~51":"Lord Goring — Ah! provavelmente é a dama. Eu mesmo a receberei.","justasheisgoingtowardsthedoorlordcaversh~entersfromthesmokingroom~66":"Justo quando ele se dirige à porta, Lord Caversham entra vindo do fumoir.","lordcavershamwellsiramitowaitattendanceo~amitowaitattendanceonyou~44":"Lord Caversham — Pois então, senhor? Devo ficar esperando por seu serviço?","lordgoringconsiderablyperplexedinamoment~ctionsphippsintothatroom~121":"Lord Goring — Consideravelmente perplexo. Num instante, pai. Peço que me desculpe. Lord Caversham volta. Bem, lembre-se das minhas instruções, Phipps... para aquela sala.","lordgoringgoesintothesmokingroomharoldth~inedwithdeadroseleafsilk~145":"Lord Goring entra no fumoir. Harold, o lacaio, introduz a Sra. Cheveley. Semelhante a uma lâmia, está de verde e prata. Traz uma capa de cetim negro, forrada de seda cor de pétala de rosa seca.","haroldwhatnamemadam~haroldwhatnamemadam~19":"Harold — Que nome, senhora?","mrscheveleytophippswhoadvancestowardsher~thereiwastoldhewasathome~78":"Sra. Cheveley — A Phipps, que avança em sua direção. Lord Goring não está? Disseram-me que estava em casa.","phippshislordshipisengagedatpresentwithl~ntwithlordcavershammadam~57":"Phipps — Sua Senhoria está no momento ocupado com Lord Caversham, senhora.","turnsacoldglassyeyeonharoldwhoatoncereti~onharoldwhoatonceretires~43":"Volta um olhar frio e vítreo para Harold, que se retira imediatamente.","mrscheveleytoherselfhowveryfilial~eytoherselfhowveryfilial~33":"Sra. Cheveley — Para si. Que filial!","phippshislordshiptoldmetoaskyoumadamtobe~rdshipwillcometoyouthere~107":"Phipps — Sua Senhoria me disse para pedir à senhora que tenha a bondade de aguardá-lo na sala de visitas. Sua Senhoria irá ter com a senhora lá.","mrscheveleywithalookofsurpriselordgoring~priselordgoringexpectsme~49":"Sra. Cheveley — Com ar de surpresa. Lord Goring me espera?","phippsyesmadam~phippsyesmadam~14":"Phipps — Sim, senhora.","mrscheveleyareyouquitesure~scheveleyareyouquitesure~26":"Sra. Cheveley — Tem certeza?","phippshislordshiptoldmethatifaladycalled~hesubjectwereveryprecise~162":"Phipps — Sua Senhoria me disse que, se uma dama viesse, eu deveria pedir-lhe que esperasse na sala de visitas. Vai até a porta da sala de visitas e a abre. As instruções de Sua Senhoria sobre o assunto foram muito precisas.","mrscheveleytoherselfhowthoughtfulofhimto~oglaringlightsomecandles~286":"Sra. Cheveley — Para si. Que atencioso da parte dele! Esperar o inesperado mostra um intelecto inteiramente moderno. Vai em direção à sala de visitas e espia dentro. Ugh! Como é sempre lúgubre a sala de visitas de um solteiro. Terei de mudar tudo isto. Phipps traz a lamparina da escrivaninha. Não, não gosto dessa lamparina. É clara demais. Acenda algumas velas.","phippsreplaceslampcertainlymadam~placeslampcertainlymadam~32":"Phipps — Recoloca a lamparina. Certamente, senhora.","mrscheveleyihopethecandleshaveverybecomi~eshaveverybecomingshades~48":"Sra. Cheveley — Espero que as velas tenham abajures muito favorecedores.","phippswehavehadnocomplaintsaboutthemmada~aintsaboutthemmadamasyet~46":"Phipps — Não tivemos queixas a respeito deles, senhora, até agora.","passesintothedrawingroomandbeginstolight~dbeginstolightthecandles~50":"Passa à sala de visitas e começa a acender as velas.","mrscheveleytoherselfiwonderwhatwomanheis~ouiwantyouiamcomingtoyou~864":"Sra. Cheveley — Para si. Pergunto-me que mulher ele espera esta noite. Será delicioso apanhá-lo. Os homens sempre parecem tão tolos quando são apanhados. E estão sempre sendo apanhados. Olha em volta da sala e se aproxima da escrivaninha. Que sala interessantíssima! Que quadro interessantíssimo! Pergunto-me como será a correspondência dele. Pega as cartas. Oh, que correspondência desinteressantíssima! Contas e cartões, dívidas e viúvas! Quem diabos lhe escreve em papel cor-de-rosa? Que tolice escrever em papel cor-de-rosa! Parece o começo de um romance de classe média. O romance nunca deveria começar com sentimento. Deveria começar com ciência e terminar com um contrato. Pousa a carta, depois a toma de novo. Conheço essa letra. É a de Gertrude Chiltern. Lembro-me perfeitamente. Os dez mandamentos em cada traço da pena, e a lei moral por toda a página. Pergunto-me o que Gertrude lhe escreve. Algo horrível sobre mim, suponho. Como detesto essa mulher! Lê. “Confio no senhor. Preciso do senhor. Estou indo ter com o senhor. Gertrude.” “Confio no senhor. Preciso do senhor. Estou indo ter com o senhor.”","alookoftriumphcomesoverherfacesheisjusta~eletterwhenphippscomesin~77":"Uma expressão de triunfo lhe toma o rosto. Ela está a ponto de furtar a carta quando Phipps entra.","phippsthecandlesinthedrawingroomarelitma~arelitmadamasyoudirected~56":"Phipps — As velas da sala de visitas estão acesas, senhora, conforme a senhora ordenou.","mrscheveleythankyouriseshastilyandslipst~ookthatislyingonthetable~103":"Sra. Cheveley — Obrigada. Levanta-se depressa e desliza a carta sob um grande mata-borrão com capa de prata que está sobre a mesa.","phippsitrusttheshadeswillbetoyourlikingm~henheisdressingfordinner~135":"Phipps — Confio em que os abajures serão do agrado da senhora. São os mais favorecedores que temos. São os mesmos que Sua Senhoria usa quando se veste para o jantar.","mrscheveleywithasmiletheniamsuretheywill~theywillbeperfectlyright~56":"Sra. Cheveley — Com um sorriso. Então tenho certeza de que serão perfeitos.","phippsgravelythankyoumadam~ippsgravelythankyoumadam~26":"Phipps — Gravemente. Obrigado, senhora.","mrscheveleygoesintothedrawingroomphippsc~edrawingroombitingherlip~281":"A Sra. Cheveley vai para a sala de visitas. Phipps fecha a porta e se retira. A porta é então lentamente aberta, e a Sra. Cheveley sai e avança furtivamente em direção à escrivaninha. De repente ouvem-se vozes vindas do fumoir. A Sra. Cheveley empalidece e para. As vozes aumentam, e ela volta à sala de visitas, mordendo o lábio.","enterlordgoringandlordcaversham~rdgoringandlordcaversham~31":"Entram Lord Goring e Lord Caversham.","lordgoringexpostulatingmydearfatherifiam~sonparticularlytheperson~122":"Lord Goring — Protestando. Meu caro pai, se tenho de me casar, certamente o senhor me permitirá escolher o momento, o lugar e a pessoa? Particularmente a pessoa.","lordcavershamtestilythatisamatterformesi~omeslateroninmarriedlife~189":"Lord Caversham — Irritado. Isso é assunto para mim, senhor. O senhor provavelmente faria uma escolha muito ruim. Sou eu quem deve ser consultado, não o senhor. Há propriedades em jogo. Não é uma questão de afeição. A afeição vem depois, na vida conjugal.","lordgoringyesinmarriedlifeaffectioncomes~ordcavershamscloakforhim~121":"Lord Goring — Sim. Na vida conjugal a afeição vem quando as pessoas se detestam completamente, pai, não é? Põe a capa em Lord Caversham.","lordcavershamcertainlysirimeancertainlyn~eisamatterforcommonsense~123":"Lord Caversham — Certamente, senhor. Quero dizer, certamente não, senhor. Está falando muito tolamente esta noite. O que digo é que o casamento é questão de bom senso.","lordgoringbutwomenwhohavecommonsenseares~rseionlyspeakfromhearsay~99":"Lord Goring — Mas as mulheres que têm bom senso são tão curiosamente sem graça, pai, não são? Claro que falo apenas de ouvir dizer.","lordcavershamnowomanplainorprettyhasanyc~seistheprivilegeofoursex~91":"Lord Caversham — Nenhuma mulher, sem graça ou bonita, tem qualquer bom senso, senhor. O bom senso é privilégio do nosso sexo.","lordgoringquitesoandwemenaresoselfsacrif~atweneveruseitdowefather~71":"Lord Goring — Perfeitamente. E nós, homens, somos tão abnegados que nunca o usamos, não é, pai?","lordcavershamiuseitsiriusenothingelse~iuseitsiriusenothingelse~37":"Lord Caversham — Eu o uso, senhor. Não uso outra coisa.","lordgoringsomymothertellsme~dgoringsomymothertellsme~27":"Lord Goring — É o que minha mãe me diz.","lordcavershamitisthesecretofyourmothersh~eartlesssirveryheartless~83":"Lord Caversham — É o segredo da felicidade de sua mãe. O senhor é muito sem coração, senhor, muito sem coração.","goesoutforamomentthenreturnslookingrathe~outwithsirrobertchiltern~68":"Sai por um momento. Depois volta, parecendo bastante contrariado, com Sir Robert Chiltern.","sirrobertchilternmydeararthurwhatapieceo~otathomehowextraordinary~128":"Sir Robert Chiltern — Meu caro Arthur, que golpe de sorte encontrá-lo à porta! Seu criado acabava de me dizer que você não estava em casa. Que extraordinário!","lordgoringthefactisiamhorriblybusytonigh~edofadraughtthewholetime~158":"Lord Goring — O fato é que estou horrivelmente ocupado esta noite, Robert, e dei ordem de que não estava em casa para ninguém. Até meu pai teve uma recepção comparativamente fria. Queixou-se de uma corrente de ar o tempo todo.","sirrobertchilternahyoumustbeathometomear~ehasdiscoveredeverything~129":"Sir Robert Chiltern — Ah! para mim você tem de estar em casa, Arthur. Você é meu melhor amigo. Talvez amanhã seja meu único amigo. Minha esposa descobriu tudo.","lordgoringahiguessedasmuch~rdgoringahiguessedasmuch~26":"Lord Goring — Ah! eu adivinhara!","sirrobertchilternlookingathimreallyhow~ernlookingathimreallyhow~38":"Sir Robert Chiltern — Olhando-o. Verdade! Como?","lordgoringaftersomehesitationohmerelybys~aceasyoucameinwhotoldher~94":"Lord Goring — Após alguma hesitação. Oh, apenas por algo na expressão de seu rosto ao entrar. Quem lhe contou?","sirrobertchilternmrscheveleyherselfandth~buryinghisfaceinhishands~357":"Sir Robert Chiltern — A própria Sra. Cheveley. E a mulher que amo sabe que comecei a minha carreira com um ato de baixa desonestidade, que construí minha vida sobre areias de vergonha... que vendi, como um mascate qualquer, o segredo que me fora confiado como a um homem de honra. Agradeço ao céu que o pobre Lord Radley tenha morrido sem saber que o traí. Queira Deus que eu tivesse morrido antes de ter sido tão horrivelmente tentado, ou de ter caído tão baixo. Escondendo o rosto nas mãos.","lordgoringafterapauseyouhaveheardnothing~nnayetinanswertoyourwire~71":"Lord Goring — Após uma pausa. Não teve ainda notícia de Viena, em resposta ao seu telegrama?","sirrobertchilternlookingupyesigotatelegr~taryateightoclocktonight~83":"Sir Robert Chiltern — Erguendo os olhos. Tive; recebi um telegrama do primeiro-secretário às oito horas desta noite.","lordgoringwell~lordgoringwell~14":"Lord Goring — Então?","sirrobertchilternnothingisabsolutelyknow~yondthaticanlearnnothing~209":"Sir Robert Chiltern — Nada de absolutamente conhecido contra ela. Pelo contrário, ocupa uma posição bastante elevada na sociedade. É uma espécie de segredo aberto que o barão Arnheim lhe deixou a maior parte de sua imensa fortuna. Além disso nada consigo saber.","lordgoringshedoesntturnouttobeaspythen~oesntturnouttobeaspythen~38":"Lord Goring — Então ela não se revela uma espiã?","sirrobertchilternohspiesareofnousenowada~papersdotheirworkinstead~94":"Sir Robert Chiltern — Oh! espiões não têm serventia hoje em dia. A profissão deles acabou. Os jornais fazem o trabalho deles.","lordgoringandthunderinglywelltheydoit~thunderinglywelltheydoit~37":"Lord Goring — E o fazem tremendamente bem.","sirrobertchilternarthuriamparchedwiththi~ethingsomehockandseltzer~81":"Sir Robert Chiltern — Arthur, estou morto de sede. Posso tocar para pedir alguma coisa? Um pouco de vinho do Reno com água gasosa?","lordgoringcertainlyletmeringsthebell~rtainlyletmeringsthebell~36":"Lord Goring — Certamente. Deixe que eu o faça. Toca a campainha.","sirrobertchilternthanksidontknowwhattodo~ntrustyouabsolutelycanti~152":"Sir Robert Chiltern — Obrigado! Não sei o que fazer, Arthur, não sei o que fazer, e você é meu único amigo. Mas que amigo você é... o único amigo em quem posso confiar. Posso confiar em você absolutamente, não posso?","lordgoringmydearrobertofcourseohtophipps~sbringsomehockandseltzer~63":"Lord Goring — Meu caro Robert, é claro. Oh! A Phipps. Traga vinho do Reno com água gasosa.","lordgoringandphipps~lordgoringandphipps~19":"Lord Goring — E Phipps!","lordgoringwillyouexcusemeforamomentrober~omedirectionstomyservant~77":"Lord Goring — Dá-me licença um momento, Robert? Quero dar algumas instruções ao meu criado.","sirrobertchilterncertainly~rrobertchilterncertainly~26":"Sir Robert Chiltern — Certamente.","lordgoringwhenthatladycallstellherthatia~edoutoftownyouunderstand~123":"Lord Goring — Quando aquela dama chegar, diga-lhe que não sou esperado em casa esta noite. Diga-lhe que fui chamado subitamente para fora da cidade. Entendeu?","phippstheladyisinthatroommylordyoutoldme~howherintothatroommylord~67":"Phipps — A dama está naquela sala, milorde. Vossa Senhoria mandou que eu a conduzisse àquela sala, milorde.","lordgoringyoudidperfectlyrightexitphipps~kwardthingtomanagethough~138":"Lord Goring — Fez perfeitamente bem. Sai Phipps. Em que embrulhada me meti. Não; penso que vou me safar. Darei a ela um sermão através da porta. Coisa difícil de manejar, no entanto.","sirrobertchilternarthurtellmewhatishould~dderinanightwithoutastar~116":"Sir Robert Chiltern — Arthur, diga-me o que devo fazer. Minha vida parece ter desmoronado em torno de mim. Sou um navio sem leme numa noite sem estrela.","lordgoringrobertyouloveyourwifedontyou~rtyouloveyourwifedontyou~38":"Lord Goring — Robert, você ama a sua esposa, não ama?","sirrobertchilternilovehermorethananythin~utarthurshehasfoundmeout~259":"Sir Robert Chiltern — Amo-a mais que a qualquer coisa no mundo. Eu costumava pensar que a ambição era a grande coisa. Não é. O amor é a grande coisa do mundo. Nada existe senão o amor, e eu a amo. Mas estou difamado aos olhos dela. Sou ignóbil aos olhos dela. Há agora um largo abismo entre nós. Ela me descobriu, Arthur, ela me descobriu.","lordgoringhassheneverinherlifedonesomefo~eshouldnotforgiveyoursin~89":"Lord Goring — Ela nunca na vida cometeu alguma loucura... alguma indiscrição... que a faça não perdoar o seu pecado?","sirrobertchilternmywifenevershedoesnotkn~enbutdontletustalkofthat~545":"Sir Robert Chiltern — Minha esposa! Nunca! Ela não sabe o que é fraqueza ou tentação. Sou de barro como os outros homens. Ela se mantém à parte como as mulheres boas... impiedosa em sua perfeição... fria e severa e sem misericórdia. Mas eu a amo, Arthur. Não temos filhos, e não tenho mais ninguém a quem amar, mais ninguém que me ame. Talvez, se Deus nos tivesse mandado filhos, ela fosse mais bondosa comigo. Mas Deus nos deu uma casa solitária. E ela partiu meu coração em dois. Não falemos disso. Fui brutal com ela esta noite. Mas suponho que quando pecadores falam com santas são sempre brutais. Disse-lhe coisas hediondamente verdadeiras, do meu lado, do meu ponto de vista, do ponto de vista dos homens. Mas não falemos disso.","lordgoringyourwifewillforgiveyouperhapsa~rtwhyshouldshenotforgive~107":"Lord Goring — Sua esposa o perdoará. Talvez neste momento esteja perdoando. Ela o ama, Robert. Por que não perdoaria?","sirrobertchilterngodgrantitgodgrantitbur~moreihavetotellyouarthur~103":"Sir Robert Chiltern — Queira Deus! Queira Deus! Esconde o rosto nas mãos. Mas há algo mais que preciso lhe contar, Arthur.","enterphippswithdrinks~enterphippswithdrinks~21":"Entra Phipps com as bebidas.","phippshandshockandseltzertosirrobertchil~hilternhockandseltzersir~61":"Phipps — Entrega vinho do Reno com água gasosa a Sir Robert Chiltern. Vinho do Reno com água gasosa, senhor.","lordgoringisyourcarriagehererobert~isyourcarriagehererobert~34":"Lord Goring — Sua carruagem está aqui, Robert?","sirrobertchilternnoiwalkedfromtheclub~ternnoiwalkedfromtheclub~37":"Sir Robert Chiltern — Não; vim a pé do clube.","lordgoringsirrobertwilltakemycabphipps~obertwilltakemycabphipps~38":"Lord Goring — Sir Robert levará o meu cabriolé, Phipps.","phippsyesmylordexit~phippsyesmylordexit~19":"Phipps — Sim, milorde. Sai.","lordgoringrobertyoudontmindmysendingyoua~dontmindmysendingyouaway~43":"Lord Goring — Robert, não se importa que eu o despeça?","sirrobertchilternarthuryoumustletmestayf~thedrawingroomwhatisthat~185":"Sir Robert Chiltern — Arthur, você tem de me deixar ficar cinco minutos. Decidi o que vou fazer esta noite na Câmara. O debate sobre o Canal Argentino vai começar às onze. Uma cadeira cai na sala de visitas. O que foi isso?","lordgoringnothing~lordgoringnothing~17":"Lord Goring — Nada.","sirrobertchilterniheardachairfallinthene~msomeonehasbeenlistening~69":"Sir Robert Chiltern — Ouvi uma cadeira cair na sala ao lado. Alguém esteve escutando.","lordgoringnonothereisnoonethere~ingnonothereisnoonethere~31":"Lord Goring — Não, não; não há ninguém lá.","sirrobertchilternthereissomeonetherearel~fearthurwhatdoesthismean~136":"Sir Robert Chiltern — Há alguém. Há luzes na sala, e a porta está entreaberta. Alguém esteve escutando cada segredo de minha vida. Arthur, o que significa isto?","lordgoringrobertyouareexcitedunnervedite~einthatroomsitdownrobert~80":"Lord Goring — Robert, você está exaltado, abalado. Digo-lhe que não há ninguém naquela sala. Sente-se, Robert.","sirrobertchilterndoyougivemeyourwordthat~ordthatthereisnoonethere~57":"Sir Robert Chiltern — Dá-me a sua palavra de que não há ninguém lá?","sirrobertchilternyourwordofhonoursitsdow~yourwordofhonoursitsdown~41":"Sir Robert Chiltern — Sua palavra de honra? Senta-se.","sirrobertchilternrisesarthurletmeseeform~sarthurletmeseeformyself~45":"Sir Robert Chiltern — Levanta-se. Arthur, deixe-me ver por mim mesmo.","lordgoringnono~lordgoringnono~14":"Lord Goring — Não, não.","sirrobertchilternifthereisnoonetherewhys~alisewhatiamgoingthrough~198":"Sir Robert Chiltern — Se não há ninguém lá, por que eu não olharia naquela sala? Arthur, você tem de me deixar entrar naquela sala e me certificar. Deixe-me saber que nenhum espião ouviu o segredo da minha vida. Arthur, você não percebe o que estou passando.","lordgoringrobertthismuststopihavetoldyou~neinthatroomthatisenough~78":"Lord Goring — Robert, isto tem de parar. Já lhe disse que não há ninguém naquela sala... isso basta.","sirrobertchilternrushestothedooroftheroo~ncanyouhaveforrefusingme~145":"Sir Robert Chiltern — Precipita-se para a porta da sala. Não basta. Insisto em entrar nesta sala. Você me disse que não há ninguém lá, então que razão pode ter para me recusar?","lordgoringforgodssakedontthereissomeonet~someonewhomyoumustnotsee~68":"Lord Goring — Pelo amor de Deus, não! Há alguém lá. Alguém a quem você não deve ver.","sirrobertchilternahithoughtso~bertchilternahithoughtso~29":"Sir Robert Chiltern — Ah, eu pensava!","lordgoringiforbidyoutoenterthatroom~forbidyoutoenterthatroom~35":"Lord Goring — Proíbo-o de entrar naquela sala.","sirrobertchilternstandbackmylifeisatstak~cretandmyshameentersroom~122":"Sir Robert Chiltern — Afaste-se. Minha vida está em jogo. E não me importa quem esteja lá. Saberei quem é a pessoa a quem contei meu segredo e minha vergonha. Entra na sala.","lordgoringgreatheavenshisownwife~nggreatheavenshisownwife~32":"Lord Goring — Santo Deus! a própria esposa dele!","sirrobertchilterncomesbackwithalookofsco~ofscornandangeronhisface~59":"Sir Robert Chiltern volta, com uma expressão de desdém e de cólera no rosto.","sirrobertchilternwhatexplanationhaveyout~epresenceofthatwomanhere~76":"Sir Robert Chiltern — Que explicação tem a me dar pela presença daquela mulher aqui?","lordgoringrobertisweartoyouonmyhonourtha~ssofalloffencetowardsyou~94":"Lord Goring — Robert, juro-lhe por minha honra que aquela dama é imaculada e inocente de qualquer ofensa contra você.","sirrobertchilternsheisavileaninfamousthi~heisavileaninfamousthing~42":"Sir Robert Chiltern — É uma coisa vil, infame!","lordgoringdontsaythatrobertitwasforyours~eshelovesyouandnooneelse~108":"Lord Goring — Não diga isso, Robert! Foi por sua causa que ela veio aqui. Foi para tentar salvá-lo que veio aqui. Ela ama você e mais ninguém.","sirrobertchilternyouaremadwhathaveitodow~treacherousasanenemyeven~175":"Sir Robert Chiltern — Você está louco. Que tenho eu a ver com as intrigas dela com você? Que continue sendo a sua amante! Combinam muito bem. Ela, corrupta e vergonhosa... você, falso como amigo, traiçoeiro até como inimigo...","lordgoringitisnottruerobertbeforeheaveni~ndinyoursiwillexplainall~88":"Lord Goring — Não é verdade, Robert. Perante o céu, não é verdade. Na presença dela e na sua explicarei tudo.","sirrobertchilternletmepasssiryouhavelied~oughuponyourwordofhonour~66":"Sir Robert Chiltern — Deixe-me passar, senhor. Você já mentiu bastante sob a sua palavra de honra.","sirrobertchilterngoesoutlordgoringrushes~kingradiantandmuchamused~115":"Sir Robert Chiltern sai. Lord Goring precipita-se para a porta da sala de visitas, quando a Sra. Cheveley sai, radiante e muito divertida.","mrscheveleywithamockcurtseygoodeveninglo~seygoodeveninglordgoring~48":"Sra. Cheveley — Com uma reverência zombeteira. Boa noite, Lord Goring!","lordgoringmrscheveleygreatheavensmayiask~weredoinginmydrawingroom~71":"Lord Goring — Sra. Cheveley! Santo Deus! … Posso perguntar o que fazia em minha sala de visitas?","mrscheveleymerelylisteningihaveaperfectp~nderfulthingsthroughthem~117":"Sra. Cheveley — Meramente escutando. Tenho uma paixão perfeita por escutar através de buracos de fechadura. Sempre se ouvem coisas tão maravilhosas.","lordgoringdoesntthatsoundratherliketempt~erliketemptingprovidence~53":"Lord Goring — Isso não soa um tanto como tentar a Providência?","mrscheveleyohsurelyprovidencecanresistte~kehercloakoffwhichhedoes~101":"Sra. Cheveley — Oh! certamente a Providência já pode resistir à tentação a esta altura. Faz-lhe sinal para que lhe tire a capa, o que ele faz.","lordgoringiamgladyouhavecallediamgoingto~gtogiveyousomegoodadvice~61":"Lord Goring — Fico contente que tenha vindo. Vou lhe dar um bom conselho.","mrscheveleyohpraydontoneshouldnevergivea~tshecantwearintheevening~80":"Sra. Cheveley — Oh! por favor, não. Nunca se deve dar a uma mulher algo que ela não possa usar à noite.","lordgoringiseeyouarequiteaswilfulasyouus~iteaswilfulasyouusedtobe~46":"Lord Goring — Vejo que continua tão voluntariosa como era.","mrscheveleyfarmoreihavegreatlyimprovedih~edihavehadmoreexperience~60":"Sra. Cheveley — Muito mais! Melhorei enormemente. Tive mais experiência.","lordgoringtoomuchexperienceisadangeroust~nallyiprefertheotherhalf~132":"Lord Goring — Experiência demais é coisa perigosa. Aceite um cigarro. Metade das mulheres bonitas de Londres fuma cigarros. Pessoalmente, prefiro a outra metade.","mrscheveleythanksineversmokemydressmaker~snoonehasasyetdiscovered~143":"Sra. Cheveley — Obrigada. Nunca fumo. Minha costureira não gostaria, e o primeiro dever de uma mulher na vida é para com a costureira, não é? Qual seja o segundo dever, ninguém ainda descobriu.","lordgoringyouhavecomeheretosellmerobertc~chilternsletterhaventyou~63":"Lord Goring — A senhora veio aqui para me vender a carta de Robert Chiltern, não veio?","mrscheveleytoofferittoyouonconditionshow~itionshowdidyouguessthat~55":"Sra. Cheveley — Para oferecê-la a você sob condições. Como adivinhou?","lordgoringbecauseyouhaventmentionedthesu~bjecthaveyougotitwithyou~64":"Lord Goring — Porque não mencionou o assunto. Está com ela?","mrscheveleysittingdownohnoawellmadedress~ellmadedresshasnopockets~52":"Sra. Cheveley — Sentando-se. Oh, não! Um vestido bem-feito não tem bolsos.","lordgoringwhatisyourpriceforit~ringwhatisyourpriceforit~30":"Lord Goring — Qual é o seu preço por ela?","mrscheveleyhowabsurdlyenglishyouaretheen~oldofmoneyisnotwhatiwant~200":"Sra. Cheveley — Como você é absurdamente inglês! Os ingleses acham que um talão de cheques resolve todo problema da vida. Ora, meu caro Arthur, tenho muito mais dinheiro do que você, e tanto quanto Robert Chiltern conseguiu abocanhar. Dinheiro não é o que quero.","lordgoringwhatdoyouwantthenmrscheveley~doyouwantthenmrscheveley~38":"Lord Goring — Que quer então, Sra. Cheveley?","mrscheveleywhydontyoucallmelaura~leywhydontyoucallmelaura~32":"Sra. Cheveley — Por que não me chama de Laura?","lordgoringidontlikethename~rdgoringidontlikethename~26":"Lord Goring — Não gosto do nome.","mrscheveleyyouusedtoadoreit~cheveleyyouusedtoadoreit~27":"Sra. Cheveley — Você costumava adorá-lo.","lordgoringyesthatswhymrscheveleymotionst~sideherhesmilesanddoesso~79":"Lord Goring — Sim: é por isso. A Sra. Cheveley faz-lhe sinal para que se sente ao lado dela. Ele sorri e o faz.","mrscheveleyarthuryoulovedmeonce~eleyarthuryoulovedmeonce~31":"Sra. Cheveley — Arthur, você me amou um dia.","mrscheveleyandyouaskedmetobeyourwife~ndyouaskedmetobeyourwife~36":"Sra. Cheveley — E me pediu que fosse sua esposa.","lordgoringthatwasthenaturalresultofmylov~turalresultofmylovingyou~46":"Lord Goring — Foi o resultado natural de eu amá-la.","mrscheveleyandyouthrewmeoverbecauseyousa~intheconservatoryattenby~132":"Sra. Cheveley — E você me largou porque viu, ou disse que viu, o pobre velho Lord Mortlake tentando ter um violento flerte comigo no jardim de inverno de Tenby.","lordgoringiamundertheimpressionthatmylaw~ntermsdictatedbyyourself~99":"Lord Goring — Tenho a impressão de que meu advogado resolveu esse assunto com a senhora sob certas condições … ditadas pela própria senhora.","mrscheveleyatthattimeiwaspooryouwererich~ttimeiwaspooryouwererich~40":"Sra. Cheveley — Naquela época eu era pobre; você era rico.","lordgoringquitesothatiswhyyoupretendedto~swhyyoupretendedtoloveme~46":"Lord Goring — Perfeitamente. É por isso que fingiu me amar.","mrscheveleyshrugginghershoulderspooroldl~satanenglishcountryhouse~445":"Sra. Cheveley — Dando de ombros. O pobre velho Lord Mortlake, que só tinha dois assuntos de conversa: sua gota e sua esposa! Nunca consegui entender bem de qual dos dois falava. Usava a linguagem mais horrível a respeito de ambos. Bem, você foi tolo, Arthur. Ora, Lord Mortlake nunca foi para mim mais que um divertimento. Um daqueles divertimentos totalmente enfadonhos que só se encontram numa casa de campo inglesa num domingo de campo inglês. Não creio que ninguém seja moralmente responsável pelo que faz numa casa de campo inglesa.","lordgoringyesiknowlotsofpeoplethinkthat~nowlotsofpeoplethinkthat~39":"Lord Goring — Sim. Sei que muita gente pensa assim.","mrscheveleyilovedyouarthur~scheveleyilovedyouarthur~26":"Sra. Cheveley — Eu amei você, Arthur.","lordgoringmydearmrscheveleyyouhavealways~rtoknowanythingaboutlove~79":"Lord Goring — Minha cara Sra. Cheveley, a senhora sempre foi inteligente demais para saber alguma coisa sobre o amor.","mrscheveleyididloveyouandyoulovedmeyoukn~oloveherputsherhandonhis~179":"Sra. Cheveley — Eu amei você. E você me amou. Sabe que me amou; e o amor é uma coisa maravilhosa. Suponho que, quando um homem amou uma vez uma mulher, fará qualquer coisa por ela, exceto continuar a amá-la? Põe a mão sobre a dele.","lordgoringtakinghishandawayquietlyyesexc~awayquietlyyesexceptthat~47":"Lord Goring — Retirando a mão com calma. Sim: exceto isso.","mrscheveleyafterapauseiamtiredoflivingab~nowifyoupromisetomarryme~470":"Sra. Cheveley — Após uma pausa. Estou cansada de viver no estrangeiro. Quero voltar a Londres. Quero ter aqui uma casa encantadora. Quero ter um salão. Se ao menos se pudesse ensinar os ingleses a conversar e os irlandeses a escutar, a sociedade aqui seria bastante civilizada. Além disso, cheguei à fase romântica. Quando vi você ontem à noite na casa dos Chiltern, soube que era a única pessoa de quem eu já gostara, se é que já gostei de alguém, Arthur. E assim, na manhã do dia em que você casar comigo, darei a você a carta de Robert Chiltern. Essa é a minha oferta. Dou-a agora mesmo, se você prometer casar comigo.","lordgoringnow~lordgoringnow~13":"Lord Goring — Agora?","mrscheveleysmilingtomorrow~scheveleysmilingtomorrow~26":"Sra. Cheveley — Sorrindo. Amanhã.","lordgoringareyoureallyserious~oringareyoureallyserious~29":"Lord Goring — A senhora está falando sério?","mrscheveleyyesquiteserious~scheveleyyesquiteserious~26":"Sra. Cheveley — Sim, muito a sério.","lordgoringishouldmakeyouaverybadhusband~ldmakeyouaverybadhusband~39":"Lord Goring — Eu seria um péssimo marido para a senhora.","mrscheveleyidontmindbadhusbandsihavehadt~twotheyamusedmeimmensely~63":"Sra. Cheveley — Não me importo com maridos ruins. Tive dois. Divertiram-me imensamente.","lordgoringyoumeanthatyouamusedyourselfim~yourselfimmenselydontyou~54":"Lord Goring — A senhora quer dizer que a senhora se divertiu imensamente, não é?","mrscheveleywhatdoyouknowaboutmymarriedli~ouknowaboutmymarriedlife~42":"Sra. Cheveley — O que você sabe da minha vida de casada?","lordgoringnothingbuticanreaditlikeabook~ngbuticanreaditlikeabook~39":"Lord Goring — Nada: mas posso lê-la como um livro.","mrscheveleywhatbook~mrscheveleywhatbook~19":"Sra. Cheveley — Que livro?","lordgoringrisingthebookofnumbers~ngrisingthebookofnumbers~32":"Lord Goring — Levantando-se. O Livro dos Números.","mrscheveleydoyouthinkitisquitecharmingof~detoawomaninyourownhouse~75":"Sra. Cheveley — Acha realmente encantador da sua parte ser tão rude com uma mulher em sua própria casa?","lordgoringinthecaseofveryfascinatingwome~xisachallengenotadefence~67":"Lord Goring — No caso de mulheres muito fascinantes, o sexo é um desafio, não uma defesa.","mrscheveleyisupposethatismeantforacompli~erencebetweenthetwosexes~139":"Sra. Cheveley — Suponho que isso queira ser um elogio. Meu caro Arthur, as mulheres nunca são desarmadas por elogios. Os homens sempre são. Essa é a diferença entre os dois sexos.","lordgoringwomenareneverdisarmedbyanythin~anythingasfarasiknowthem~57":"Lord Goring — As mulheres nunca são desarmadas por nada, até onde as conheço.","mrscheveleyafterapausethenyouaregoingtoa~latingyourownperfections~291":"Sra. Cheveley — Após uma pausa. Então você vai permitir que o seu maior amigo, Robert Chiltern, seja arruinado, em vez de casar com alguém que ainda tem consideráveis atrativos. Pensei que você se elevaria a algum grande ápice de autossacrifício, Arthur. Acho que deveria. E o resto da vida você poderia passar contemplando as suas próprias perfeições.","lordgoringohidothatasitisandselfsacrific~selftheyalwaysgotothebad~149":"Lord Goring — Oh! isso eu já faço. E o autossacrifício é coisa que deveria ser proibida por lei. É tão desmoralizante para as pessoas por quem a gente se sacrifica. Elas sempre se perdem.","mrscheveleyasifanythingcoulddemoralisero~hatiknowhisrealcharacter~92":"Sra. Cheveley — Como se alguma coisa pudesse desmoralizar Robert Chiltern! Você parece esquecer que conheço o verdadeiro caráter dele.","lordgoringwhatyouknowabouthimisnothisrea~eforenothistruecharacter~164":"Lord Goring — O que a senhora sabe dele não é o seu verdadeiro caráter. Foi um ato de loucura cometido na juventude, desonroso, admito, vergonhoso, admito, indigno dele, admito, e portanto … não o seu verdadeiro caráter.","mrscheveleyhowyoumenstandupforeachother~oumenstandupforeachother~39":"Sra. Cheveley — Como vocês, homens, se defendem uns aos outros!","lordgoringhowyouwomenwaragainsteachother~womenwaragainsteachother~40":"Lord Goring — Como vocês, mulheres, guerreiam umas contra as outras!","mrscheveleybitterlyionlywaragainstonewom~rihatehernowmorethanever~96":"Sra. Cheveley — Com amargura. Só guerreio contra uma mulher, contra Gertrude Chiltern. Odeio-a. Odeio-a agora mais do que nunca.","lordgoringbecauseyouhavebroughtarealtrag~agedyintoherlifeisuppose~62":"Lord Goring — Porque trouxe uma verdadeira tragédia à vida dela, suponho.","mrscheveleywithasneerohthereisonlyonerea~tureinvariablyherhusband~127":"Sra. Cheveley — Com um sorriso de escárnio. Oh, só há uma verdadeira tragédia na vida de uma mulher. O fato de que o seu passado é sempre o seu amante, e o seu futuro invariavelmente o seu marido.","lordgoringladychilternknowsnothingofthek~ifetowhichyouarealluding~70":"Lord Goring — Lady Chiltern nada sabe do tipo de vida a que a senhora alude.","mrscheveleyawomanwhosesizeinglovesisseve~chemeiexposehimvoilatout~451":"Sra. Cheveley — Uma mulher cujo tamanho de luva é sete e três quartos nunca sabe grande coisa de nada. Sabe que Gertrude sempre usou sete e três quartos? Essa é uma das razões por que nunca houve simpatia moral entre nós. … Bem, Arthur, suponho que esta entrevista romântica pode ser considerada encerrada. Admite que foi romântica, não admite? Pelo privilégio de ser sua esposa, eu estava pronta a renunciar a um grande prêmio, o clímax da minha carreira diplomática. Você recusa. Muito bem. Se Sir Robert não apoiar o meu projeto argentino, eu o denuncio. Voilà tout.","lordgoringyoumustntdothatitwouldbevileho~ldbevilehorribleinfamous~54":"Lord Goring — A senhora não deve fazer isso. Seria vil, horrível, infame.","mrscheveleyshrugginghershouldersohdontus~goodbyewontyoushakehands~288":"Sra. Cheveley — Dando de ombros. Oh! não use palavras grandes. Significam tão pouco. É uma transação comercial. Só isso. Não adianta misturar sentimentalismo nisso. Ofereci vender a Robert Chiltern certa coisa. Se ele não me pagar o meu preço, terá de pagar ao mundo um preço maior. Não há mais nada a dizer. Preciso ir. Adeus. Não quer apertar-me a mão?","lordgoringwithyounoyourtransactionwithro~ttherecanbenoforgiveness~514":"Lord Goring — Com a senhora? Não. A sua transação com Robert Chiltern pode passar por uma repugnante transação comercial de uma repugnante era comercial; mas a senhora parece ter esquecido que veio aqui esta noite falar de amor, a senhora, cujos lábios profanaram a palavra amor, a senhora, para quem a coisa é um livro rigorosamente selado, foi esta tarde à casa de uma das mulheres mais nobres e gentis do mundo para rebaixar o marido aos olhos dela, para tentar matar o amor dela por ele, pôr veneno em seu coração e amargura em sua vida, quebrar seu ídolo e, talvez, arruinar sua alma. Isso eu não posso perdoar. Foi horrível. Para isso não pode haver perdão.","mrscheveleyarthuryouareunjusttomebelieve~theoriginofthewholething~519":"Sra. Cheveley — Arthur, você é injusto comigo. Acredite, você é inteiramente injusto comigo. Não fui de modo algum para zombar de Gertrude. Não tinha ideia de fazer nada disso ao entrar. Fui com Lady Markby simplesmente para perguntar se um adorno, uma joia, que perdi em algum lugar ontem à noite, havia sido encontrado na casa dos Chiltern. Se não acredita em mim, pode perguntar a Lady Markby. Ela dirá que é verdade. A cena que ocorreu aconteceu depois que Lady Markby se foi, e foi realmente imposta a mim pela grosseria e pelos sarcasmos de Gertrude. Fui, oh!... um pouco por malícia, se quiser... mas na verdade para perguntar se um broche de diamantes meu havia sido encontrado. Essa foi a origem de tudo.","lordgoringadiamondsnakebroochwitharuby~mondsnakebroochwitharuby~38":"Lord Goring — Um broche de diamantes em forma de serpente, com um rubi?","mrscheveleyyeshowdoyouknow~scheveleyyeshowdoyouknow~26":"Sra. Cheveley — Sim. Como sabe?","lordgoringbecauseitisfoundinpointoffacti~chisntitholdsupthebrooch~221":"Lord Goring — Porque foi encontrado. Na verdade, eu mesmo o encontrei, e estupidamente esqueci de dizer qualquer coisa ao mordomo ao sair. Vai até a escrivaninha e abre as gavetas. Está nesta gaveta. Não, naquela. Este é o broche, não é? Ergue o broche.","mrscheveleyyesiamsogladtogetitbackitwasa~togetitbackitwasapresent~47":"Sra. Cheveley — Sim. Estou tão contente em tê-lo de volta. Foi … um presente.","lordgoringwontyouwearit~lordgoringwontyouwearit~23":"Lord Goring — Não vai usá-lo?","mrscheveleycertainlyifyoupinitinlordgori~itcouldhewornasabracelet~126":"Sra. Cheveley — Certamente, se o prender em mim. Lord Goring de repente o fecha no braço dela. Por que o põe como pulseira? Nunca soube que podia ser usado como pulseira.","lordgoringreally~lordgoringreally~16":"Lord Goring — Verdade?","mrscheveleyholdingoutherhandsomearmnobut~lonmeasabraceletdoesntit~78":"Sra. Cheveley — Estendendo o belo braço. Não; mas fica muito bem em mim como pulseira, não fica?","lordgoringyesmuchbetterthanwhenisawitlas~betterthanwhenisawitlast~41":"Lord Goring — Fica; muito melhor do que quando o vi da última vez.","mrscheveleywhendidyouseeitlast~veleywhendidyouseeitlast~30":"Sra. Cheveley — Quando o viu da última vez?","lordgoringcalmlyohtenyearsagoonladyberks~kshirefromwhomyoustoleit~62":"Lord Goring — Calmamente. Ah, há dez anos, em Lady Berkshire, de quem a senhora o roubou.","mrscheveleystartingwhatdoyoumean~leystartingwhatdoyoumean~32":"Sra. Cheveley — Sobressaltada. O que quer dizer?","lordgoringimeanthatyoustolethatornamentf~aveheardherownconfession~272":"Lord Goring — Quero dizer que a senhora roubou esse adorno de minha prima, Mary Berkshire, a quem o dei quando ela se casou. A suspeita recaiu sobre uma pobre criada, que foi despedida em desgraça. Reconheci-o ontem à noite. Resolvi não dizer nada até encontrar a ladra. Agora encontrei a ladra, e ouvi a sua própria confissão.","mrscheveleytossingherheaditisnottrue~ossingherheaditisnottrue~36":"Sra. Cheveley — Erguendo a cabeça com desdém. Não é verdade.","lordgoringyouknowitistruewhythiefiswritt~rossyourfaceatthismoment~68":"Lord Goring — A senhora sabe que é verdade. Ora, a palavra ladra está escrita em seu rosto neste exato momento.","mrscheveleyiwilldenythewholeaffairfrombe~itwasneverinmypossession~123":"Sra. Cheveley — Negarei o caso todo, do começo ao fim. Direi que nunca vi essa coisa miserável, que nunca esteve em meu poder.","mrscheveleytriestogetthebraceletoffherar~rposeacursebreaksfromher~130":"A Sra. Cheveley tenta tirar a pulseira do braço, mas não consegue. Lord Goring observa, divertido. Seus dedos finos puxam a joia em vão. Uma praga lhe escapa dos lábios.","lordgoringthedrawbackofstealingathingmrs~tisratherdifficulttofind~215":"Lord Goring — O inconveniente de roubar uma coisa, Sra. Cheveley, é que nunca se sabe quão maravilhosa é a coisa que se rouba. A senhora não consegue tirar essa pulseira, a menos que saiba onde está a mola. E vejo que não sabe onde está a mola. É bastante difícil de achar.","mrscheveleyyoubruteyoucowardshetriesagai~claspthebraceletbutfails~69":"Sra. Cheveley — Seu bruto! Seu covarde! Tenta de novo abrir o fecho da pulseira, mas não consegue.","lordgoringohdontusebigwordstheymeansolit~bigwordstheymeansolittle~43":"Lord Goring — Ora! não use palavras grandes. Significam tão pouco.","mrscheveleyagaintearsatthebraceletinapar~oringwhatareyougoingtodo~121":"Sra. Cheveley — De novo arranca a pulseira, num paroxismo de raiva, com sons inarticulados. Depois para e olha para Lord Goring. O que pretende fazer?","lordgoringiamgoingtoringformyservantheis~ltellhimtofetchthepolice~133":"Lord Goring — Vou chamar meu criado. É um criado admirável. Sempre vem no instante em que se toca para ele. Quando vier, mandarei que chame a polícia.","mrscheveleytremblingthepolicewhatfor~remblingthepolicewhatfor~36":"Sra. Cheveley — Tremendo. A polícia? Para quê?","lordgoringtomorrowtheberkshireswillprose~hatiswhatthepolicearefor~72":"Lord Goring — Amanhã os Berkshire a processarão. É para isso que serve a polícia.","mrscheveleyisnowinanagonyofphysicalterro~nythingintheworldyouwant~182":"Sra. Cheveley — Está agora numa agonia de terror físico. O rosto está desfigurado. A boca, torta. Uma máscara caiu-lhe. Está, por um momento, horrível de se ver. Não faça isso. Farei tudo o que quiser. Tudo, tudo no mundo que quiser.","lordgoringgivemerobertchilternsletter~emerobertchilternsletter~37":"Lord Goring — Dê-me a carta de Robert Chiltern.","mrscheveleystopstopletmehavetimetothink~stopletmehavetimetothink~39":"Sra. Cheveley — Pare! Pare! Deixe-me ter tempo para pensar.","mrscheveleyihavenotgotitwithmeiwillgivei~iwillgiveittoyoutomorrow~54":"Sra. Cheveley — Não a trouxe comigo. Entrego-a amanhã.","lordgoringyouknowyouarelyinggiveittomeat~heishorriblypalethisisit~112":"Lord Goring — A senhora sabe que está mentindo. Dê-me agora mesmo. A Sra. Cheveley tira a carta e a entrega a ele. Está terrivelmente pálida. É esta?","mrscheveleyinahoarsevoiceyes~heveleyinahoarsevoiceyes~28":"Sra. Cheveley — Com voz rouca. Sim.","lordgoringtakestheletterexaminesitsighsa~monsenseicongratulateyou~145":"Lord Goring — Pega a carta, examina-a, suspira e a queima na lâmpada. Para uma mulher tão bem-vestida, Sra. Cheveley, a senhora tem momentos de admirável bom senso. Meus parabéns.","mrscheveleycatchessightofladychilternsle~pleasegetmeaglassofwater~120":"Sra. Cheveley — Avista a carta de Lady Chiltern, cuja capa aparece justamente sob o mata-borrão. Faça o favor de me trazer um copo d’água.","lordgoringcertainlygoestothecornerofther~sherefusesitwithagesture~176":"Lord Goring — Certamente. Vai ao canto do quarto e serve um copo d’água. Enquanto ele está de costas, a Sra. Cheveley rouba a carta de Lady Chiltern. Quando Lord Goring devolve o copo, ela o recusa com um gesto.","mrscheveleythankyouwillyouhelpmeonwithmy~llyouhelpmeonwithmycloak~45":"Sra. Cheveley — Obrigada. Quer ajudar-me com a capa?","lordgoringwithpleasureputshercloakon~thpleasureputshercloakon~36":"Lord Goring — Com prazer. Coloca-lhe a capa.","mrscheveleythanksiamnevergoingtotrytohar~oharmrobertchilternagain~60":"Sra. Cheveley — Obrigada. Nunca mais tentarei fazer mal a Robert Chiltern.","lordgoringfortunatelyyouhavenotthechance~enotthechancemrscheveley~51":"Lord Goring — Felizmente a senhora não tem ocasião, Sra. Cheveley.","mrscheveleywellifevenihadthechanceiwould~torenderhimagreatservice~87":"Sra. Cheveley — Pois bem, ainda que eu tivesse ocasião, não o faria. Pelo contrário, vou prestar-lhe um grande serviço.","lordgoringiamcharmedtohearititisareforma~tohearititisareformation~44":"Lord Goring — Encantado em ouvir isso. É uma regeneração.","mrscheveleyyesicantbearsouprightagentlem~oshamefullydeceivedandso~102":"Sra. Cheveley — Sim. Não suporto que um cavalheiro tão íntegro, um cavalheiro inglês tão honrado, seja tão vergonhosamente enganado, e tão—","mrscheveleyifindthatsomehowgertrudechilt~onhasstrayedintomypocket~90":"Sra. Cheveley — Descubro que, de algum modo, as últimas palavras e a confissão de Gertrude Chiltern foram parar no meu bolso.","lordgoringwhatdoyoumean~lordgoringwhatdoyoumean~23":"Lord Goring — O que quer dizer?","mrscheveleywithabitternoteoftriumphinher~hiswifewrotetoyoutonight~119":"Sra. Cheveley — Com uma nota amarga de triunfo na voz. Quero dizer que vou enviar a Robert Chiltern a carta de amor que a esposa escreveu ao senhor esta noite.","lordgoringloveletter~lordgoringloveletter~20":"Lord Goring — Carta de amor?","mrscheveleylaughingiwantyouitrustyouiamc~ouiamcomingtoyougertrude~58":"Sra. Cheveley — Rindo. “Preciso de você. Confio em você. Estou indo ao seu encontro. Gertrude.”","lordgoringrushestothebureauandtakesupthe~indsisemptyandturnsround~73":"Lord Goring corre ao bureau, pega o envelope, vê que está vazio e se vira.","lordgoringyouwretchedwomanmustyoualwaysb~eavemyroomtillihavegotit~128":"Lord Goring — Mulher miserável, precisa sempre roubar? Devolva-me essa carta. Eu a tirarei da senhora à força. Não sairá do meu quarto antes que eu a tenha.","herushestowardsherbutmrscheveleyatoncepu~berationsandphippsenters~134":"Precipita-se para ela, mas a Sra. Cheveley põe de imediato a mão na campainha elétrica que está sobre a mesa. A campainha soa com estridentes reverberações, e Phipps entra.","mrscheveleyafterapauselordgoringmerelyra~meoutgoodnightlordgoring~83":"Sra. Cheveley — Após uma pausa. Lord Goring tocou apenas para que o senhor me acompanhasse até a porta. Boa noite, Lord Goring!","goesoutfollowedbyphippsherfaceisillumine~ipandlightshisacigarette~177":"Sai, seguida por Phipps. O rosto dela está iluminado por um triunfo maligno. Há alegria em seus olhos. A juventude parece ter-lhe voltado. Seu último olhar é como uma flecha veloz. Lord Goring morde o lábio e acende um cigarro."}$tr$::jsonb, 970)
